window.TECHNIQUE_FEATS = {"e001": [{"name": "Double Up", "prereq": "Prerequisite: Kaichi", "text": "One Kaichi activation may create two drill-horn manifestations; pay and track each horn separately. Both persist under the normal Kaichi duration. Horns are not summoned creatures, do not require a summon command, and do not consume creature or manifestation capacity. When you take the Attack action, resolve each available horn attack as part of that action; this never grants a second action."}, {"name": "Zero Friction", "prereq": "Prerequisite: Reiki", "text": "While Reiki's movement increase is active, you can resolve your Kaichi horn attack at any point during your movement instead of only as part of the Attack action. If you move at least 20 feet in a straight line immediately before the attack, a hit also shoves the target 10 feet away from you, carrying your momentum through the horn."}, {"name": "Maximum: Kirin’s Flames", "prereq": "Prerequisite: Kirin and CE score 20", "text": "While Kirin is active, each melee hit against you deals fire damage to its attacker equal to three times the HP you actually lost after reductions and temporary HP. This requires no reaction, cannot trigger from reflected damage, and cannot recursively trigger itself."}], "e002": [{"name": "Deathwatch", "prereq": "Prerequisite: Cursed Crow", "text": "While seeing through a crow, you can use a bonus action to mark one creature the crow can see. For 1 hour you sense the marked creature's direction and distance through the bond, even through invisibility, darkness, or cover, while both of you remain on the same plane. Only one creature can be marked this way at a time."}, {"name": "Murder's Due", "prereq": "Prerequisite: Omen of Death", "text": "As a bonus action, end Omen of Death's frightened condition on one creature within 60 feet of you. Each of your active crows within 30 feet of it can use its reaction to fly up to its speed toward that creature without provoking opportunity attacks, converging on the scent of its fear."}, {"name": "Maximum: Kamikaze", "prereq": "Prerequisite: Bird Strike and CE score 20", "text": "When your Bird Strike destroys its crow, the death-cry becomes an Omen of Death. Each creature within 15 feet of the target must make your Omen Wisdom save or become frightened of you until the end of your next turn. A creature that succeeds is immune to this effect until the next dawn."}], "e003": [{"name": "Blood Transfusion", "prereq": "Prerequisite: Blood Manipulation", "text": "As an action, spend 1 CE and 5 HP to transfuse freshly produced blood into a willing creature within 5 feet. It regains 2d6 + your CE modifier hit points. You cannot target yourself with this transfusion."}, {"name": "Crimson Clot", "prereq": "Prerequisite: Blood Manipulation", "text": "Once per turn, when you damage a creature with a blood attack, you can use your reaction to clot the blood in the wound. The creature's speed is halved until the end of its next turn as the blood hardens around the injury. A creature with no blood is immune."}, {"name": "Blood Crystallization", "prereq": "Prerequisite: Blood Construction", "text": "Bonus action, 3 CE, Technique Focus for 1 minute: resistance to bludgeoning, piercing, and slashing; unarmed die increases one size; reaction adds +5 AC against one attack. At each turn’s start roll d20; on 1–3 gain one exhaustion level. Ending the form requires no action."}, {"name": "Red Current", "prereq": "Prerequisite: Flowing Red Scale", "text": "While Flowing Red Scale is active, you can move across the surface of liquids and up vertical surfaces without falling; if you end your turn on neither solid ground nor a surface, you fall. Your rushing slipstream carries you past guards: your movement does not provoke opportunity attacks while Flowing Red Scale is active."}, {"name": "Blood Edge", "prereq": "Prerequisite: Convergence and CE score 20", "text": "Once on your turn with no action, spend 1–CE modifier CE and matching HP to form one proficient melee weapon for 1 minute. It is cursed; base damage is d10, rising one step per 2 CE to d12 then 2d8. A suitable outside blood source waives only the HP cost."}, {"name": "Maximum: Supernova", "prereq": "Prerequisite: Piercing Blood and CE score 20", "text": "Action: create up to PB orbs in open spaces within 30 feet. Each costs 10 CE and 10 HP as Piercing Blood. An orb lasts 1 minute and detonates immediately or by your reaction: creatures within 10 feet make Dexterity saves, taking 10d8 piercing and prone on failure, half and no prone on success. Resolve overlapping orbs separately."}, {"name": "Maximum: Wing King", "prereq": "Prerequisite: Piercing Blood and CE score 20", "text": "Bonus action, 10 CE, once per long rest: for 1 minute with Technique Focus, quadruple walking speed and gain flying speed equal to half that walking speed. Gain one restricted extra action that can make three ranged CE attacks, each dealing 3d10 + CE modifier necrotic on hit."}], "e004": [{"name": "Flawless Acting", "prereq": "Prerequisite: Graverobber", "text": "After seven days and $2,500 of expenses, establish one false identity with clothing, records, profession, and affiliations. It cannot duplicate a real person. Investigation contests your Deception to expose inconsistencies; the identity grants no legal authority the fiction cannot support."}, {"name": "Memory Bank", "prereq": "Prerequisite: Skill Theft", "text": "You perfectly remember everything you experience. As an action, touch an object and store any continuous portion of one remembered experience in it; there is no added object or duration cap. A creature touching it may use an action to begin experiencing the memory from your point of view at normal speed and may stop at will. A memory grants information, not proficiency, statistics, or technique access."}, {"name": "Maximum: Backup", "prereq": "Prerequisite: Immortality and CE score 20", "text": "Prepare an eligible humanoid corpse over 8 hours, then use an action and 10 CE to designate it as your only backup. On death, resolve the Clone spell’s soul-transfer procedure using that body, without its gold or maturation time. Preparing a new backup destroys the old link; a trapped or unwilling soul cannot transfer."}], "e005": [{"name": "Boogie Down", "prereq": "Prerequisite: Boogie", "text": "When you are hit by an attack, you can use your reaction to swap yourself with a willing creature or eligible object within range, following all normal Boogie Woogie rules and paying its normal CE cost. The attack instead targets whoever arrives in your space; compare the original attack roll against its AC and resolve damage normally."}, {"name": "Beguiling Tactics", "prereq": "Prerequisite: Woogie", "text": "An unwilling creature swapped by Woogie makes an Intelligence save; failure stuns it until the start of its next turn. After its first success it has advantage on later saves that encounter. As an action, fake-clap with Performance or Deception contested by Insight; on a win it has disadvantage on its next Beguiling save before end of your next turn."}, {"name": "Maximum: Best Friend", "prereq": "Prerequisite: Round of Applause and CE score 20", "text": "At the start of combat, choose one willing ally you can perceive. You fight as a duet: once per round, when either of you is targeted by an attack, you can use your reaction to swap the two of you with no CE cost, following all normal Boogie Woogie range and legality rules. The attack targets whoever arrives in the targeted space; compare the original attack roll against their AC and resolve damage normally."}], "e006": [{"name": "Subtle Constructs", "prereq": "Prerequisite: Construct", "text": "After creating an item, make Dexterity (Sleight of Hand) against each observer’s passive Perception. Against a creature you fool, your first attack or check using that item before end of next turn has advantage. The creation itself remains subject to line of sight and obvious physical evidence."}, {"name": "Imbue", "prereq": "Prerequisite: Cursed Creation", "text": "When using Cursed Creation to construct a cursed tool, pay twice that tool’s normal CE cost to imbue the creation with the tool’s Technique for 7 days. There is no added one-item cap. The created tool uses the normal attunement rules and your CE attack/DC when its technique needs them; Creating a Special Grade tool still kills the creator afterward and cannot be reversed or revived."}, {"name": "Maximum: Perfect Sphere", "prereq": "Prerequisite: Insectoid Armor and CE score 20", "text": "Action, 10 CE: create one 5-foot-radius sphere within 10 feet for 1 minute with Technique Focus. It is indestructible while maintained. Ending a turn adjacent or being rammed forces one Dexterity save per turn for 5d12 force, half on success. Bonus action moves it 30 feet; it destroys barriers and unattended nonmagical structures in its path."}], "e007": [{"name": "Detonate", "prereq": "Prerequisite: Granite Blast", "text": "When activating Granite Blast, you may make it a melee CE attack with 5-foot reach instead of a ranged attack. All cost, damage, and other modifiers remain unchanged."}, {"name": "Canshot", "prereq": "Prerequisite: Grape Shot", "text": "Corrected prerequisite: Grape Shot. Once per Granite Blast activation after one blast hits, spend 3 CE; every other creature within 5 feet of that target takes half the damage actually dealt, with no additional attack or save. The original target is not hit twice."}, {"name": "Maximum: Antimatter Bomb", "prereq": "Prerequisite: Nuclear Shell", "text": "When you activate Nuclear Shell, its cone may become a 100-foot-radius sphere centered on you. You are excluded; all other creatures save normally. Unattended nonmagical objects and structures in the sphere are reduced to dust. Pay Nuclear Shell’s normal cost and charge time."}], "e008": [{"name": "Fighting Words", "prereq": "Prerequisite: Power of Words", "text": "When a creature fails a save against your cursed word, it makes a second Wisdom save. On failure, for 1 minute it has disadvantage on attacks that do not include you as a target; it repeats the save at the end of each turn. A creature can be affected by only one Fighting Words at a time."}, {"name": "Hushed Word", "prereq": "Prerequisite: Interjection", "text": "When you use a word with Interjection, you can pitch it as a whisper aimed at one creature within 30 feet that can hear you. Only that creature hears and is affected by the word, even if it would normally reach further; you still pay its full CE and vocal strain."}, {"name": "Megaphone", "prereq": "Prerequisite: Resounding Voice", "text": "When you use Resounding Voice, you can focus the broadcast into a 5-foot-wide, 70-foot line originating from you instead of a cone. Only creatures in the line that can hear you are affected; all vocal-cord, target, and save rules remain."}], "e009": [{"name": "Cursed Spirit Embodiment", "prereq": "Prerequisite: Cursed Spirit Absorption and CE score 16+", "text": "Action; spend CE equal to the absorbed spirit’s CR, rounded up (minimum 1), and transform for up to half your character level in hours. Replace your Strength, Dexterity, Constitution, AC, current HP, movement, senses, and creature actions with the spirit’s profile; retain your Intelligence, Wisdom, Charisma, personality, alignment, and any proficiency bonus that is higher. You cannot use Cursed Spirit Manipulation features or legendary, lair, or mythic actions while transformed. At 0 spirit HP you revert, and excess damage carries over to your original HP."}, {"name": "Defensive Summoning", "prereq": "Prerequisite: Perfect Control", "text": "Reaction when hit, before damage: spend 5 CE plus the chosen stored spirit’s summon cost and manifest it in an adjacent legal space. It becomes the attack’s target; compare the original attack roll with its AC and apply damage to it. Area effects still affect every creature normally."}, {"name": "Uzumaki Versatility", "prereq": "Prerequisite: Maximum: Uzumaki and CE score 20", "text": "Bonus action: permanently consume exactly two stored spirits to form a miniature Uzumaki for 1 minute. Action or reaction when a target comes within 60 feet, 5 CE: ranged CE attack; hit deals Xd12 necrotic, X = combined CR rounded up. Ignore resistance, treat immunity as resistance. Undetected target grants advantage. Extract one action using the revised Uzumaki rules."}], "e010": [{"name": "Tool Versatility", "prereq": "Prerequisite: Judge’s Gavel", "text": "As a bonus action, reshape the gavel into any melee weapon. You are proficient with it and it uses that weapon’s damage and properties; no ammunition, consumable, or attached special-grade property is created. It returns to gavel form when released."}, {"name": "Weight of Judgment", "prereq": "Prerequisite: Judge’s Gavel", "text": "As an action, spend 2 CE to slam your gavel into the ground. Each creature within 15 feet that can hear the slam must make a Wisdom save against your CE DC. On a failure, it cannot take reactions until the start of your next turn: order in the court."}, {"name": "Judgeman Release", "prereq": "Prerequisite: Deadly Sentencing", "text": "Bonus action, 5 CE, Technique Focus for 1 minute: summon intangible Judgeman and designate one perceived opponent within 60 feet. Every time that opponent attacks, its cumulative assault penalty increases by 1. Subtract the full penalty from its attack rolls and saving throws until Judgeman leaves; there is no added charge cap."}], "e011": [{"name": "Ashfall", "prereq": "Prerequisite: Flames of Disaster", "text": "When you activate Flames of Disaster, you can snuff its damage to fill the cone's area with choking ash for 1 minute. The area is heavily obscured."}, {"name": "Volcanic Launch", "prereq": "Prerequisite: Erupting Volcanoes", "text": "As a bonus action, spend 2 CE to have one of your volcanoes within 30 feet erupt directly beneath you instead of along its line. You are launched up to 60 feet to an unoccupied space you can see and land safely without taking falling damage; the eruption still deals its normal damage along one 30-by-10-foot line of your choice originating from the volcano."}, {"name": "Hellscape", "prereq": "Prerequisite: Maximum: Meteor", "text": "Action, 15 CE, Technique Focus for 1 minute: unattended nonmagical objects and ground in a 100-foot radius melt into lava. It is difficult terrain; entering or ending a turn there causes a Constitution save, 4d6 fire on failure, half on success, once per turn. Bonus action moves one 10-foot lava square up to 20 feet along a surface."}], "e012": [{"name": "Hydrokinesis", "prereq": "Prerequisite: Tides of Disaster", "text": "Action, 2 CE: make a ranged CE attack against a creature within 30 feet, firing a high-pressure lance of water. On a hit, it takes 2d10 cold + 2d6 piercing damage and must make a Constitution save against your CE DC. On a failure, it is knocked prone and takes the rolled damage again as the jet bores through."}, {"name": "Shoal", "prereq": "Prerequisite: Horizon of Captivating Skandha", "text": "You may activate Death Swarm outside the Domain with its normal action, target, summon capacity, and any listed CE cost. It has no sure-hit; attacks and saves resolve normally."}, {"name": "Typhoon", "prereq": "Prerequisite: Water Defensive Ring", "text": "For 4 additional CE, the Ring creates the printed 20-foot storm for the Ring’s duration. A creature saves once when the storm appears and whenever it ends a turn there, taking 2d6 bludgeoning on failure. Bonus action each turn makes the 60-foot 4d6 lightning attack. The area moves with you and is difficult terrain."}], "e013": [{"name": "Chlorokinesis", "prereq": "Prerequisite: Forests of Disaster", "text": "As a bonus action, transform one active root wall into a different wall option without refreshing its HP or duration."}, {"name": "Bouquet", "prereq": "Prerequisite: Flower Field", "text": "Action, 3 CE: one creature within 60 feet makes the normal Flower Field save and suffers its effects for the normal duration. It does not create an area and cannot affect additional creatures through movement."}, {"name": "Stranglehold", "prereq": "Prerequisite: Cursed Bud", "text": "As a bonus action, choose one creature hosting at least one of your buds. The buds constrict: it must make a Strength save against your CE DC. On a failure, it is restrained until the end of its next turn. On a success, it tears one bud off, destroying it."}], "e014": [{"name": "Black Belt", "prereq": "Prerequisite: Martial Prowess", "text": "Repeatable; choose each maneuver once. Takedown uses a bonus-action grapple after a melee hit. Judo Throw triggers on a hit against your grappled Huge-or-smaller target: Strength save, prone on failure and stunned to end of next turn if failed by 5+. Flying Drop Kick uses an action and your jump movement for one unarmed attack, pushing 30 feet on hit."}, {"name": "Opportunistic Blow", "prereq": "Prerequisite: Controlled Divergent Flow", "text": "Once per turn after the delayed Divergent Fist damage lands, the target makes an Intelligence save. On failure, attacks against it have advantage until the start of your next turn."}, {"name": "Maximum: Soul Punch", "prereq": "Prerequisite: Chosen by the Sparks and CE score 20", "text": "Before an unarmed attack, spend 5 CE; all your unarmed hits this turn deal soul damage that ordinary RCT cannot heal. Each hit gives one Output Suppression, maximum CE modifier: reduce optional CE spending ceiling by 1 per stack and disable Maximum Output while any stack remains. All stacks end after a short or long rest."}], "e015": [{"name": "Thunderous Applause", "prereq": "Prerequisite: Hands of Love", "text": "As an action, spend 2 CE to clap your two active hands together around a creature within 5 feet of both. It must make a Constitution save against your CE DC. On a failure, it is deafened until the end of its next turn and pushed 10 feet directly away from the midpoint between the hands. On a success, it is not deafened and is pushed 5 feet."}, {"name": "Handy Dandy", "prereq": "Prerequisite: Hand Shield", "text": "Action, 2 CE: lock one active Hand into a solid 10-by-10-foot platform for up to 10 minutes. It supports up to 2,000 pounds and uses the Hand’s AC/HP. The locked Hand cannot attack, grapple, shove, or shield; bonus action releases it."}, {"name": "Maximum: Love at First Sight", "prereq": "Prerequisite: Cutie Honey and CE score 20", "text": "Action, 10 CE: one creature within an active Hand’s reach makes the Cutie Honey Wisdom save. On failure it suffers that feature’s full 1-minute effect and repeating save without requiring a hit or restraint first."}], "e016": [{"name": "Iceshape", "prereq": "Prerequisite: Ice Creation", "text": "Action, 1 CE: form one simple or martial melee weapon from ice in your reach. You are proficient with it, it counts as cursed, and it lasts 1 hour. It has AC 13 and HP equal to 5 + level, melts harmlessly when destroyed, and grants no copied item property."}, {"name": "Permafrost", "prereq": "Prerequisite: Frost Calm", "text": "When a creature restrained by your ice succeeds on the Strength save to end the restraint, you can use your reaction to keep its feet frozen in clinging ice. Its speed is halved until the end of its next turn."}, {"name": "Maximum: Shatter", "prereq": "Prerequisite: Ice Fall", "text": "Action: choose a creature restrained by your ice; it makes a Constitution save. Failure breaks one chosen limb and ends the restraint. It severs instead only if the restraint or same activation meets the revised Sever threshold, or the target is at or below 25% maximum HP. Success ends the restraint without injury."}], "e017": [{"name": "Remote Transfiguration", "prereq": "Prerequisite: Transfiguration", "text": "A deliberate bare-hand touch may place one detectable soul mark on a Humanoid indefinitely. While on the same plane and knowing its identity, use an action and pay the normal Transfiguration cost to affect it at any distance; it saves normally. The mark is consumed after the attempt and can be removed by Technique Extermination or explicit soul repair."}, {"name": "Awakening", "prereq": "Prerequisite: Ally Alteration", "text": "When altering a willing Non-Sorcerer, make one DC 15 CE ability check per creature. Success and 10 CE awaken a latent, lore-consistent innate technique after 1d4+1 days. The GM records the technique; it uses the target’s character level and does not grant class features or a second technique. The permanent change can reshape a campaign."}, {"name": "Maximum: Spirit Body of Distorted Killing", "prereq": "Prerequisite: Self-Embodiment of Perfection and CE score 20", "text": "Action, 10 CE: for 10 minutes your AC cannot be below 25 and you gain proficient elbow blades (1d12 + CE modifier piercing). On each blade attack, spend 1 CE for advantage and 15-foot reach. The form ends if incapacitated; AC bonuses do not raise the 25-floor unless they normally stack."}], "e018": [{"name": "Offensive Infinity", "prereq": "Prerequisite: Infinity", "text": "Action, spend 1–PB CE: choose a creature within 15 feet and within 10 feet of a solid surface. Constitution save; failure takes Xd6 force and is restrained against that surface until start of your next turn, success takes half and is not restrained. X equals CE spent."}, {"name": "Spatial Skirmishing", "prereq": "Prerequisite: Blue", "text": "Once per turn when making an unarmed strike, pay Blue’s normal cost and use CE ability for the attack; on hit apply Blue and gain advantage on that attack. After learning Red, choose Red instead: on hit the target makes the normal Strength save and is launched as Red states. One strike cannot carry both."}, {"name": "Teleportation", "prereq": "Prerequisite: Blue and CE score 20", "text": "Action, spend 1–PB CE: teleport yourself to an open space you can see, 10 feet per CE. You may carry worn/held equipment and one willing creature no larger than you if you spend 1 additional CE within the same PB cap."}, {"name": "Delayed Purple", "prereq": "Prerequisite: Hollow Purple", "text": "While one of your Blues persists within 120 feet, activate Red into it as an action, or as a reaction when a creature enters or ends a turn in the Blue. Pay both Red and Hollow Purple costs. Every creature—including you—in a 100-foot radius makes a Dexterity save; failure takes the maximum value of Hollow Purple’s 20d12 base dice (240 force damage), success half. Riders and amplifier dice are rolled normally."}], "e019": [{"name": "Lodestar", "prereq": "Prerequisite: Effective Marking", "text": "When you use Effective Marking's additional reaction, you can mark yourself instead of the triggering creature. You bear that star normally, counting toward your per-star limit. While you bear it, Gravity's violation pull can draw pulled creatures toward you whenever you hold the greatest current CE among that star's bearers."}, {"name": "Repelling Forces", "prereq": "Prerequisite: Gravity", "text": "Bonus action, spend 3–PB CE: every marked creature is forced directly away from the marked body with the greatest current CE, 10 feet per CE spent. This is simultaneous forced movement, causes no opportunity attacks, and stops at solid obstacles."}, {"name": "Maximum: Star Crossed", "prereq": "Prerequisite: Shining Star and CE score 20", "text": "Action, 10 CE: choose a creature within 120 feet carrying all five marks. The marks collapse into it; Constitution save, taking 25d4 force on failure or half on success. All five marks are consumed. cannot be multiplied."}], "e020": [{"name": "Defensive Surge", "prereq": "Prerequisite: Electric Energy", "text": "Reaction when a melee attack hits you: the attacker makes a Constitution save. On failure it is paralyzed until the start of its next turn. This does not cancel the triggering hit and can affect a creature only once per turn."}, {"name": "Imbued Weapon", "prereq": "Prerequisite: Lightning Discharge", "text": "Each melee weapon hit may place one positive charge in that weapon, maximum twice CE modifier for one weapon. Bonus action while it is within 60 feet: consume all charges to create a 5-foot-wide line between you and it. Creatures in the line make Dexterity saves, taking 1d12 lightning per charge, half on success."}, {"name": "Final Discharge", "prereq": "Prerequisite: CE score 20 and Mythical Beast Amber Release", "text": "When you deactivate your Mythical Beast Amber Release with a bonus action before the minute-5 collapse, you can vent its remaining charge as a final blast. Each creature within 30 feet of you must make a Dexterity save against your CE DC, taking 2d12 lightning damage per full minute endured (maximum 8d12), or half on a success. You still resolve the Release's deactivation Constitution saves normally."}], "e021": [{"name": "Augmented Vow", "prereq": "Prerequisite: True New Shadow Style: Simple Domain", "text": "When opening Simple Domain, state one symmetrical conduct rule and one consequence no harsher than 5d10 damage or one condition until end of the breaker’s next turn. Every creature inside, including you, knows it and is bound for CE modifier rounds or until leaving. It cannot compel impossible actions, surrender, self-harm, or permanent loss."}, {"name": "Instantaneous Attack", "prereq": "Prerequisite: Batto Sword Draw", "text": "While your Simple Domain is active, use an action to prepare. The next time a hostile creature enters your weapon reach before the Domain ends, use your reaction to make one weapon attack. The preparation is then consumed."}, {"name": "First Strike", "prereq": "Prerequisite: Evening Moon Sword Drawing", "text": "Once per combat, before your first turn begins, you may use your reaction to assume the Evening Moon stance without an active Simple Domain. Until the end of your first turn, hostile creatures entering your weapon reach provoke your Evening Moon reaction attack as normal. The stance ends early if you activate your Simple Domain."}], "e022": [{"name": "Contagious Luck", "prereq": "Prerequisite: Great Luck", "text": "When using Great Luck, you may choose one willing creature within 30 feet instead of yourself. The use, duration, die, and any cost are unchanged; you do not also gain the benefit."}, {"name": "Pachinko Manifest", "prereq": "Prerequisite: Idle Death Gamble", "text": "You may use the technique’s Pachinko Attacks outside the Domain at a 30-foot range. Use their normal actions, attack/DC, and CE costs; they gain no sure-hit, expectation modifier, jackpot roll, or Domain-only event unless an entry expressly grants it."}, {"name": "Maximum: Love Train", "prereq": "Prerequisite: The Fever and Pachinko Manifest", "text": "Action, 10 CE: unleash your Green, Red, and Gold Pachinko attacks as a single activation at 30-foot range, resolving each with its normal attack roll and no sure-hit. Hits add expectation even outside the Domain. If all three strike the same creature, you may immediately place a bet as part of this action."}], "e023": [{"name": "Fortissimo", "prereq": "Prerequisite: Marcado", "text": "When you begin Prayer, choose one willing creature you can perceive within 60 feet as your soloist. Your cumulative personal benefits from the Prayer track - bonuses to AC, saves, damage, attacks, and critical range - apply to the soloist instead of you; penalties to the target are unchanged. If the soloist leaves 60 feet or becomes imperceptible, the benefits return to you."}, {"name": "Cadence", "prereq": "Prerequisite: Caesura", "text": "Reaction, 4 CE, after a creature affected by your Prayer rolls but before outcome: make its attack miss or turn its successful save into a failure. This cannot override Legendary Resistance, immunity, or a natural 20 attack."}, {"name": "Maximum: Grand Chorus", "prereq": "Prerequisite: Crescendo and CE score 20", "text": "Action, 10 CE: for 1 minute using Technique Focus, your Prayer needs no single target - at the start of each of your turns, every hostile creature you can perceive within 60 feet suffers the Prayer penalties for your current beat count, and you gain the personal benefits once. Starting Prayer anew resets the count as normal."}], "e024": [{"name": "White Space", "prereq": "Prerequisite: 24 Frame Rule", "text": "Reaction when targeted by an attack, 2 CE: step between frames. Move up to 15 feet to an unoccupied space you can see without provoking opportunity attacks; the triggering attack resolves against your new position and misses automatically if you left its range or reach. You may use this only while Projection is active."}, {"name": "Air Shatter", "prereq": "Prerequisite: 24 Frame Rule", "text": "When you complete a straight, uninterrupted segment of at least 20 feet on your declared route, use a bonus action and 3 CE to shatter the displaced air. Creatures in a 30-foot line along the segment you just traveled make a Dexterity save, taking CE modifier d10 force on failure or half on success. Roll damage once."}, {"name": "Maximum: Sakuga", "prereq": "Prerequisite: Fastest Sorcerer Alive and CE score 20", "text": "Action, 10 CE: declare a complete route of up to twelve 5-foot frames. Until the end of your next turn you execute it at blinding speed - you may take the Attack action at any point along the route, splitting movement before and after, opportunity attacks against you have disadvantage, and you may pass through hostile spaces. Deviating from the declared route ends the effect."}], "e025": [{"name": "Puppet Armor", "prereq": "Prerequisite: Ultimate Puppet", "text": "Action while adjacent to an active puppet: wear it and remove it from the active roster. Gain temporary HP equal to its current HP, +2 AC, its physical scores, movement, senses, and non-action traits. When temporary HP ends the armor is destroyed; action exits early with remaining puppet HP. It cannot act separately while worn."}, {"name": "Communication Puppets", "prereq": "Prerequisite: Lesser Puppet", "text": "After each long rest create up to PB Tiny messengers, each holding a snapshot of your consciousness and 5 minutes of activity. AC 15, 1 HP, speed 20; no attacks or technique. Set a perceivable trigger. While any are active on the same plane, memories they acquire synchronize with you and each other when the activity ends."}, {"name": "Maximum: Ultimate Puppet", "prereq": "Prerequisite: Absolute Puppet", "text": "During a long rest, fuse two of your prepared puppets into one Ultimate chassis: it uses the higher of their statistics, keeps both puppets' full trait sets, has hit points equal to both combined, and counts as one active puppet. It is summoned for the higher of the two CE costs. If it is reduced to 0 HP, the fusion breaks and both puppets are destroyed."}], "e026": [{"name": "Measured Guard", "prereq": "Prerequisite: Critical Focus", "text": "Reaction when you are hit by a weapon attack, 1 CE: roll your Ratio d10 (two dice from level 11, as the feature). On a 3 or 7 you found the blow's weak ratio and the damage is halved. Declare before damage is rolled."}, {"name": "Weapon Breaker", "prereq": "Prerequisite: Collapse", "text": "Reaction when targeted by a weapon attack, 3 CE: wielder makes Dexterity save. On failure a mundane weapon breaks before damage; a cursed tool breaks only if your striking tool is equal or higher grade, otherwise the attack is deflected and misses. Artifacts and unique Special Grades break only when their own story permits."}, {"name": "Fatal Ratio", "prereq": "Prerequisite: Improved Ratio", "text": "Corrected prerequisite: Improved Ratio. After a Ratio critical, spend 2 CE to make it a limb-tagged hit without targeted-strike disadvantage. Resolve damage and the revised injury threshold/save normally; the feat does not automatically sever a limb."}], "e027": [{"name": "Spiderweb", "prereq": "Prerequisite: Dismantle", "text": "For 1 additional CE, replace Dismantle’s attack with a 30-foot cone. Creatures make Dexterity saves, taking the normal Dismantle damage on failure or half on success. Roll once for the area."}, {"name": "Form of Battle", "prereq": "Prerequisite: Perfect Form", "text": "While you grapple a creature, your Dismantle and Cleave need no ranged attack roll against it - the cuts ride your grip. Resolve them as melee CE attacks instead, with Cleave's mark and penetration applying normally. You cannot target any other creature with those slashes while the grapple holds."}, {"name": "Maximum: World Cutter", "prereq": "Prerequisite: Malevolent Shrine and CE score 20", "text": "Action with an audible chant and free hand: pay Cleave/Dismantle’s cost +5 CE and make its attack. It cuts occupied space, ignores cover, barriers, technique-created AC, resistance, and immunity. Resolve against base armor/natural/unarmored AC. A miss still expends CE; it cannot combine with Chanting or Maximum Output."}], "e028": [{"name": "Cloak of Invisibility", "prereq": "Prerequisite: Sky Shape", "text": "Action, 3 CE: cast Invisibility on yourself using Technique Focus, without needing spellcasting. If you have Sky Armor, its AC and flight remain active while invisible. Attacking or activating a hostile technique ends invisibility as the spell states."}, {"name": "Spatial Tear", "prereq": "Prerequisite: Thin Ice Breaker", "text": "Corrected feature name: Thin Ice Breaker. When activating it, spend 2 additional CE to replace the line and save with one melee CE attack. On hit, deal force damage equal to a number of d10s equal to your CE modifier and knock the target prone; on miss, no damage. It remains one activation."}, {"name": "Maximum: Hurricane", "prereq": "Prerequisite: Thin Ice Breaker and CE score 20", "text": "Action, 10 CE: creatures of your choice within 30 feet make Strength saves. Failure launches a creature 1,000 feet upward; success leaves it in place. Flying, reactions, ceilings, and normal falling damage apply; a ceiling stops ascent at the available distance."}], "e029": [{"name": "Blessing Relay", "prereq": "Prerequisite: Bless", "text": "Action, 3 CE while your Zone is active: designate one willing creature inside it as a relay for up to 1 minute, using your Technique Focus alongside the Zone. Allies you regard as such within 30 feet of the relay gain the Zone's advantage as if standing inside it. The relay itself gains no benefit while relaying."}, {"name": "Blessing of Combat", "prereq": "Prerequisite: Arena", "text": "Once per turn when an ally inside your Zone hits a hostile creature with an attack, they may push that hostile up to 10 feet as part of the hit. If the push carries it across the Zone boundary, it makes the Arena crossing Charisma save as normal."}, {"name": "Maximum: Shrine of the Gods", "prereq": "Prerequisite: Arena, Bless, and CE score 20", "text": "Action, 10 CE: establish your Zone centered on yourself for 1 minute using Technique Focus. It moves with you, applying the Arena boundary and ally benefits from its current position. You cannot sustain Bless separately while it moves."}], "e030": [{"name": "Massive Push", "prereq": "Prerequisite: Virtual Mass Increase", "text": "Once per turn when you score a critical hit while virtual mass is active, push the target 15 feet directly away. This is forced movement and causes no opportunity attack."}, {"name": "Shooting Star", "prereq": "Prerequisite: Virtual Mass Improvement", "text": "Action, 5 CE while mass is active: kick one unsecured object within reach through a 50-by-5-foot line. Creatures make Dexterity saves, taking twice your base unarmed dice plus attack ability modifier bludgeoning on failure, half on success. A failed save also allows an injury check only if that single damage meets the revised threshold."}, {"name": "Maximum: Black Hole", "prereq": "Prerequisite: Virtual Mass Mastery", "text": "Action, 20 CE: choose a radius up to 100 feet and irrevocably sacrifice yourself; your body becomes the singularity. Other creatures make Strength saves. Failure dies; success survives and is pulled 30 feet toward center. A creature immune to instant death instead takes 20d10 force on failure, half on success. Ordinary RCT or revival cannot restore you."}], "e031": [{"name": "Nail Volley", "prereq": "Prerequisite: Nail Projectile", "text": "Action: spend X CE and consume X nails, X from 1 to CE modifier. Create a cone 10 × X feet long. Creatures make Dexterity saves, taking Xd4 piercing on failure or half on success. All nails land in the area and may be recovered normally."}, {"name": "1000 Needles", "prereq": "Prerequisite: Hairpin", "text": "When planting Hairpin nails, pay 1 extra CE per nail. A creature failing any detonation save is restrained for 1 minute. At each turn’s end it chooses Athletics or Acrobatics against CE DC; success ends it, failure deals 1d8 piercing. Multiple nails do not stack the condition or damage."}, {"name": "Maximum: Last Nail in the Coffin", "prereq": "Prerequisite: Improved Resonance", "text": "Action, 10 CE while a Resonance link persists: every nail you planted with Hairpin uproots and streaks unerringly to the linked target, detonating on arrival as Hairpin - one Dexterity save, 6d8 + (X - 1)d8 force for X nails, half on success - regardless of where they were planted. All nails are consumed and the link ends."}], "e032": [{"name": "Blessed Blow", "prereq": "Prerequisite: Extinguishment", "text": "When you hit a creature with a weapon attack, you may spend 1 CE and forgo the attack's damage to force it to make the Charisma save against your Extinguishment's suppression, dealing no radiant damage. On a failure it is suppressed until the end of your next turn; on a success nothing happens."}, {"name": "Archangel’s Present", "prereq": "Prerequisite: Angel’s Blessing and Breakthrough", "text": "Choose a Blessing suited to the breakthrough when it occurs and record its complete rules. A custom Blessing of comparable scope is also valid with your GM’s approval."}, {"name": "Sword of Michael", "prereq": "Prerequisite: Maximum: Jacob’s Ladder and CE score 20", "text": "Action: pay Jacob’s Ladder’s normal cost +5 CE and make one melee CE attack. On hit the creature alone suffers 10d12 radiant damage and the revised Jacob’s Ladder technique-nullification effect; on miss all CE is spent. It does not create the original area."}], "e033": [{"name": "Maximum: Crippling Strikes", "prereq": "Prerequisite: Unblockable Blows and CE score 20", "text": "Your Unblockable Blows extends to the inanimate: your attacks ignore damage thresholds, and a structure's, barrier's, or ward's immunity to your damage becomes resistance. When such an attack destroys a barrier or object, remaining damage carries to one creature directly behind it."}, {"name": "Maximum: Blast Away", "prereq": "Prerequisite: Energy Blast and CE score 20", "text": "When you use Energy Blast, you may target a point in free space within 5 feet of yourself instead of a creature. You are launched 20 feet in a direction of your choice without provoking opportunity attacks and take no damage from the blast. If you spent at least 5 CE, each creature in a 15-foot cone behind your path makes a Strength save or is pushed 10 feet and knocked prone."}, {"name": "Maximum: Fortress", "prereq": "Prerequisite: Defensive Form and CE score 20", "text": "Action while you hold Defensive Form temporary HP: end the form to detonate the ward. Each creature within 10 feet makes a Constitution save, taking force damage equal to the remaining temporary HP on failure (half on success) and being pushed 10 feet on a failed save. You are unaffected."}], "e034": [{"name": "Partial Manifestation Versatility", "prereq": "Prerequisite: Partial Manifestation", "text": "Once per turn when Partial Manifestation would add damage, forgo all of that added damage to attempt one grapple or shove against the hit target as part of the attack, using your CE ability in place of Strength if desired."}, {"name": "Technique Storage", "prereq": "Prerequisite: Mimicry", "text": "A technique your spirit has mimicked can be wielded through you: while the spirit is manifested, partially or fully, you may use your action to activate one stored mimicry as if you knew it, paying its CE cost and using your attack bonus and save DC. The spirit cannot activate that same mimicry on the same turn."}, {"name": "Directed Frenzy", "prereq": "Prerequisite: Stronger Bond", "text": "While the appendix spirit is berserk, use a bonus action to name one creature you can see. Until the start of your next turn the spirit treats that creature as the last creature to damage you when choosing targets, and its attacks against the named creature have advantage. This does not end the berserk state."}], "e035": [{"name": "Divine Dog Totality", "prereq": "Prerequisite: Divine Dogs tamed, and one Divine Dog has died (reduced to 0 HP).", "text": "Inheritance. Manifest the surviving Dog as Divine Dog Totality. Totality is mutually exclusive with both original Dogs and uses the revised Totality stat block."}, {"name": "Shadow Skulker", "prereq": "", "text": "Shadow movement. As an action for 2 CE, submerge into your shadow for consecutive turns equal to your Constitution modifier (minimum one). While submerged, you have total cover and perceive the space around your shadow; your shadow moves across connected surfaces at half your speed; you may summon, dismiss, and command Ten Shadows shikigami; you cannot personally attack, use RCT, expand a Domain, or activate other cursed techniques. Emerge within 5 feet as a bonus action. You are forcibly ejected when the duration ends — or at the end of your next turn if no manifested shikigami remain."}, {"name": "Chimerafication", "prereq": "Prerequisite: Wells Unknown Abyss and a 20 CE ability score.", "text": "Freeform fusion. Build one base plus as many as three donor additions under the Chimerafication rules: living shikigami combine — no shadow is sacrificed and none need be dead. Three ready-to-play presets — Zagroth, Hageshi, and Agito — appear in the Fusion Catalog."}, {"name": "Maximum: Embodiment", "prereq": "Prerequisite: Chimera Shadow Garden (Domain Expansion).", "text": "Maximum Technique. As an action, spend half the manifestation cost (minimum 1 CE) of one of your tamed shikigami (no Totality or Chimera). Rather than summoning it, you instead gain that shikigami's movement, actions, legendary actions, features, and one ability score of your choice for 1 hour. You can embody one shikigami at a time. Mahoraga: borrowing Mahoraga's Adaptation grants its Eight-Handled Wheel three-stage adaptation as described in this dossier's Mahoraga stat block (damage types, conditions, and obstacles each adapt through exposure → resistance → immunity or functional counter)."}], "e036": [{"name": "Early Trigger", "prereq": "Prerequisite: Siphon", "text": "Bonus action: reset your Siphon Counter to 0. If it was at least 2 - or at least 1 from level 6 - Siphon triggers immediately against the last creature you hit since your last turn, draining as normal. If the counter was lower, nothing happens."}, {"name": "Redistributed Drain", "prereq": "Prerequisite: Siphon, level 4", "text": "Bonus action: transfer any amount of your Temporary CE to a willing creature within 30 feet. It gains that Temporary CE, up to its own cap, and you lose it; transferred CE expires on its normal schedule."}, {"name": "Blood-Price Champion", "prereq": "Prerequisite: Amphitheater of the Living Dead", "text": "Once per round when one of your qualifying attacks removes Gladiator HP from a hostile competitor, add 1 CE to the Colosseum Pool after the damage resolves. If that attack was a critical hit, add your PB instead. This contribution does not drain either combatant and cannot itself change Favor until the Pool is recalculated."}, {"name": "Curator of Spoils", "prereq": "Prerequisite: Colosseum Spoils", "text": "You may lend a Spoil you hold to a willing creature: it gains the Spoil's benefit until your next long rest, and you cannot benefit from it meanwhile. Reclaim it as a bonus action while within 60 feet."}], "e037": [{"name": "Flywheel Counter", "prereq": "Prerequisite: Kinetic Transmission", "text": "When you take bludgeoning, piercing, slashing, force, or thunder damage, use your reaction and spend 2 CE. Roll PB Drive Dice and add CE modifier once, reducing the damage by the total. Gain 1 Gear per Drive Die, maximum Gear 10. If inactive, Kinetic Transmission activates at Gear 0 before these Gears are gained."}, {"name": "Suspended Interval", "prereq": "Prerequisite: Velocity Override, level 6", "text": "Projectile: reaction and 3 CE; stop one moving physical projectile within 60 feet for up to 1 minute. Maintain up to PB and release any number as a bonus action, making ranged CE attacks."}, {"name": "Vector Skip", "prereq": "Prerequisite: Clutch Control, CE 18+", "text": "When using Acceleration Shift, pay 1 additional CE. For every Gear lowered, teleport 20 feet instead of gaining 15 feet of speed. Bring one willing adjacent creature by lowering one additional Gear. Your first Impact Shift that turn adds one Drive Die."}, {"name": "Relativistic Break", "prereq": "Prerequisite: Redline, CE 20+, breakthrough", "text": "While at Gear 10 during Redline, as a full-turn action spend 10 CE and lower all 10 Gears. Travel instantly through a 300-foot, 15-foot-wide line. Creatures make Dexterity saves: failure takes 20d12 force, moves to the end, falls prone, and cannot react; success takes half only. Damage ignores resistance; immunity becomes resistance. Structures automatically fail and take maximum damage. Redline ends; take 4 Drive Dice unavoidable recoil and suffer Technique Burnout."}], "e038": [{"name": "Snare Glyph", "prereq": "Prerequisite: Directive Inscription", "text": "When you inscribe arrows, you may designate up to PB of them as snares. When a hostile creature enters a snare's space, use your reaction to expend it: the creature makes a Strength save or is moved the full Arrow Distance in the arrow's direction without provoking opportunity attacks. You decide which arrows are snares when placing them."}, {"name": "Rescue Vector", "prereq": "Prerequisite: Shared Route", "text": "When a willing creature is targeted by an attack while within 10 feet of one of your arrows, use your reaction, spend 2 CE, and expend that arrow to move the creature its full Arrow Distance in the displayed direction without provoking. Recalculate the attack’s reach, range, line, and cover from the new space; it misses only if the target is no longer legal."}, {"name": "Double Bank", "prereq": "Prerequisite: Projectile Redirection", "text": "When you use Projectile Redirection, you may spend 1 additional CE and expend a second active arrow whose space lies in the redirected line. The same attack changes direction again from that arrow before finding its final target. This is one reaction, uses the original attack roll and source, and is an explicit exception to the ordinary one-redirection limit; it cannot be redirected a third time."}, {"name": "Shared Vector Edge", "prereq": "Prerequisite: Acceleraise Boost", "text": "Once per round after a willing creature activates one or more of your arrows and hits with a weapon attack, use your reaction and spend 1 CE. Add one current Arrow Die per arrow it activated that turn, maximum PB dice, to that hit as force damage. This cannot combine with Acceleraise Boost on the same hit, but it can support a different ally or a later turn."}], "e039": [{"name": "Bestowed Memory", "prereq": "Prerequisite: Solar Memory", "text": "When you complete the Solar Memory rite, you may store the rank in a willing creature's held weapon or worn object instead of yourself. That creature may release it once as a bonus action for 2 CE, gaining its effects for 1 minute; the memory is then expended. You cannot release a bestowed memory."}, {"name": "Corona of Command", "prereq": "Prerequisite: Sunshine", "text": "While your effective rank is at least 2, use an action and 3 CE to release a corona pulse: each hostile within 15 feet makes a Constitution save or is blinded until the end of your next turn, and each ally in the pulse has advantage on saves against being frightened or charmed until the end of your next turn. You cannot pulse again until 1 minute passes."}, {"name": "Night-Prowling Lion", "prereq": "Prerequisite: Pride Incarnate", "text": "At effective rank 0, use a bonus action and 1 CE to begin the prowl for 1 minute: you leave no tracks, have advantage on Dexterity (Stealth) checks, and your first weapon or unarmed hit each turn against a creature that cannot see you deals an extra Solar Die of damage. This grants no rank, sunlight, or daylight features."}, {"name": "Grace Bestowed", "prereq": "Prerequisite: Solar Infusion, level 6", "text": "When a willing creature within 120 feet hits with a weapon, unarmed, natural, or CE attack carrying its own CE, use your reaction and pay Solar Infusion’s normal 1 CE to add your current Solar Infusion damage to that hit. This use counts against every per-turn Solar Infusion limit and receives the same station and Perfect Grace multipliers."}], "e040": [{"name": "Armed Ally", "prereq": "Prerequisite: Charge Object", "text": "During a short or long rest, you may charge one object and gift it to a willing creature: its Charge lasts 24 hours in their hands, and they may release it as you could, using your Kinetic Die. You may maintain up to PB such gifted charges; gifting beyond the limit ends one of your choice."}, {"name": "Twin Conduits", "prereq": "Prerequisite: Bound Conduit", "text": "While touching two charged objects, you may link them as a circuit without an action (once per turn). When one releases its Charge, the other immediately releases half its Charge, rounded down, as part of the same detonation, sharing the first object's radius and save. Either object detonating normally breaks the circuit."}, {"name": "Kinetic Catch", "prereq": "Prerequisite: Loaded Toss, level 6", "text": "When you see a physical ranged attack made against a creature within 30 feet, after seeing its roll but before resolution, use your reaction and spend 2 CE. Make a CE attack roll. If your total equals or exceeds the triggering attack roll, that attack misses and its projectile lands in an empty hand or at your feet with 1 Charge. This cannot catch an area, energy beam, siege projectile larger than you, artifact, or attack without a physical projectile."}, {"name": "Royal Flush", "prereq": "Prerequisite: Cardsharp Barrage, level 9", "text": "After one Cardsharp Barrage resolves, if at least four of its separate attacks hit the same creature, that creature makes a Constitution save. On failure it is stunned until the start of your next turn as overlapping kinetic vectors arrest its body. On success it cannot take reactions until the start of your next turn. The condition is one result of the barrage, not an additional hit or detonation."}], "e041": [{"name": "Reel the Arsenal", "prereq": "Prerequisite: Cast a Strand", "text": "When a strand is attached to an object held by a creature, you may use Elastic Recall on that strand to rip it free: the holder makes a Strength saving throw against your Technique DC, and on a failure it drops the object, which is pulled up to the Contraction distance toward the strand’s other endpoint. To attach to a held object, hit the holder with an attack and spend 1 CE to leave the string on the object instead of the creature."}, {"name": "Snapback Counter", "prereq": "Prerequisite: Reel-In Counter", "text": "When a hostile creature attached to one of your strands completes at least 10 feet of voluntary movement, use your reaction and spend 1 CE to immediately use Elastic Recall on that strand. If the creature fails its save and ends within your reach, make one weapon or unarmed attack against it as part of the same reaction. On hit, the target cannot take reactions until the start of its next turn."}, {"name": "Living Texture", "prereq": "Prerequisite: Texture Surprise", "text": "As an action for 1 CE, apply Texture Surprise across yourself or one willing creature you touch for 1 hour. The disguise moves with the body and can alter visible skin, hair, clothing, markings, and apparent injuries within the same general silhouette and size. It does not change voice, scent, weight, anatomy, CE signature, equipment function, or statistics and uses the normal active-investigation rule."}, {"name": "Catch the Impossible", "prereq": "Prerequisite: Return to Sender, level 11", "text": "Elastic Guard can catch a ranged spell attack, CE attack, or visible energy projectile as well as a physical ranged attack. If your Elastic Guard negates it entirely and catches it, Return to Sender may launch a gum facsimile at a creature within Gum Range: make a ranged CE attack that deals the same damage the caught attack would have dealt. It never copies the original effect, conditions, area, spell level, or other riders."}], "e042": [{"name": "Unbroken Mudra", "prereq": "Prerequisite: Prayer Palm", "text": "Your interrupted gestures still complete themselves. When a Palm attack misses, the mudra flows through unbroken: make a second Palm attack against a different creature within 15 feet of the original target as part of the same Palm, paying 1 CE for the echo. If the echo misses, the gesture ends."}, {"name": "Great Compassion", "prereq": "Prerequisite: Hundredfold Matrix", "text": "Your mercy widens to cover two. When Merciful Palm moves a willing creature, you may spend 1 CE to move a second willing creature within 15 feet of the first the same distance along the same vector, resolved with the same roll. When Guarding Palm shields a willing creature, you may spend 1 CE to extend its damage reduction to a second willing creature adjacent to the first."}, {"name": "Opening Salutation", "prereq": "Prerequisite: Prayer Before Violence", "text": "Immediately after initiative is rolled, once per combat, you may perform one Merciful Palm on yourself or a willing creature within Palm Reach without spending an action, reaction, or CE. Resolve this movement before the first turn is taken; it cannot target an unwilling creature."}, {"name": "Hundred-and-First Hand: Lotus Prison", "prereq": "Prerequisite: Third Hand, level 8", "text": "As an action for 4 CE, choose one creature within Palm Reach and make three ranged CE attacks against it. Each hit deals 2 Prayer Dice of force or radiant damage; add your CE modifier to one hit only. If at least two attacks hit, spectral petals restrain the target until the end of your next turn. The prison has AC equal to your CE save DC and HP equal to 10 × PB; destroying it ends the restraint."}], "e044": [{"name": "Many Names, One Banner", "prereq": "Prerequisite: War God's Household", "text": "Your names answer from afar. When you use Battle Muster, you may call one Regalia into vessel form at a point you can see within 60 feet instead of beside you — a Sky Lion where your allies need it, a shield already in a friend's hands. It still counts against your Active Limit."}, {"name": "Line That Casts Out Evil", "prereq": "Prerequisite: Borderline", "text": "Your Borderline may be up to 120 feet long, may bend once at a point you can see, and ignores chosen nonhostile creatures. A hostile creature that fails its save is also Restrained until the end of its turn. If it succeeds, it crosses and cannot be affected by that Borderline again that turn."}, {"name": "Blessed Beyond Death", "prereq": "Prerequisite: Blessed Vessel, level 12", "text": "A blessed vessel's devotion extends to its kin. When a non-Blessed Regalia would become Broken, your Blessed Vessel may use its reaction to suffer the breaking in its place: the Blessed Vessel becomes Broken instead, and the other Regalia remains at 1 Integrity."}, {"name": "Cavalry of Heaven", "prereq": "Prerequisite: Sky Lion vessel, level 6", "text": "Every Sky Lion can carry you plus PB willing Medium or smaller creatures. Once on each of your turns after the Lion moves at least 30 feet, one rider may use its reaction to make one weapon attack or take the Disengage action. A creature can benefit from Cavalry of Heaven only once per round."}], "e045": [{"name": "Postage Due", "prereq": "Prerequisite: Dimensional Authorship", "text": "A folded victim makes an excellent parcel. When you successfully Fold the Panel on a creature, you may immediately use Panel Step — paying its normal cost plus 1 CE — and carry the folded target with you to your destination. It remains folded until the fold’s normal duration ends."}, {"name": "Smash Cut", "prereq": "Prerequisite: Panel Step, level 6", "text": "Once per turn after Panel Step, spend 2 CE to make one weapon attack or Panel Strike without an action. On a hit add one RD and move yourself and the target up to 15 feet in the same direction."}, {"name": "Living Illustration", "prereq": "Prerequisite: Prop Extraction, level 8", "text": "As an action, spend 5 CE and choose a creature depicted in an image within Snap Range. You manifest it in an unoccupied space beside that image for 1 hour; it counts as one Active Edit. It has AC 15 + half PB, HP equal to 10 × PB, speed 40 feet, and one attack using your CE attack bonus that deals 2 RD + your CE modifier in an appropriate damage type. It acts immediately after you and Dodges unless you command it with a bonus action. If reduced to 0 HP, dismissed without an action, or no longer within Snap Range at the end of your turn, it folds back into its source image."}, {"name": "Unreliable Narrator", "prereq": "Prerequisite: Dimensional Authorship, level 4", "text": "As an action, spend 3 CE to place a false caption, sound, image, creature, object, or apparent terrain change inside a 30-foot cube within Snap Range for 10 minutes. The scene counts as one Active Edit and can include touch, temperature, scent, and convincing CE texture. A creature that uses an action to investigate makes an Intelligence save against your Technique DC, recognizing the false scene on a success. Physical interaction does not automatically reveal it; the fiction supplies expected resistance but cannot deal damage, restrain a creature, or bear real weight."}, {"name": "Continuity Error", "prereq": "Prerequisite: Dimensional Authorship, level 14", "text": "When you are reduced to 0 HP, killed by damage, or subjected to an incapacitating condition, use your reaction and spend 8 CE to restore your HP, CE, position, dimensions, and conditions to their state at the start of your previous turn. Other creatures, spent items, and scene changes are not reversed. The first use per long rest is safe; each later use before that rest inflicts 2 levels of exhaustion that cannot be prevented or removed until the scene ends."}, {"name": "Executive Editor", "prereq": "Prerequisite: Authorial Privilege, level 18", "text": "You make two cuts in a single motion. When you apply Cut Turn to a hostile creature, you may spend 2 additional CE to also apply Reblock Scene to that creature alone, teleporting it to a legal space within Snap Range as its turn is removed. This combination costs no additional Authorial Privilege use."}], "e046": [{"name": "Redmane Greatbow", "prereq": "Prerequisite: Gravity Sovereignty", "text": "You can mark ammunition as part of firing it. Long-range weapon attacks against a marked creature ignore disadvantage from long range, and once per turn a hit may Pull the target 10 feet."}, {"name": "Lion’s Gravity", "prereq": "Prerequisite: level 6", "text": "When you succeed on a save against forced movement or prone, use your reaction to place an Anchor mark on yourself and Pull the source 15 feet toward you if it is within Gravity Range."}, {"name": "Starcaller’s Mark", "prereq": "Prerequisite: Starcaller Cry", "text": "What the cry cannot crush, it claims. Each creature that succeeds on its save against Starcaller Cry gains a Gravity Mark with the Anchor vector for 1 minute, with no additional save; a creature can carry only one such mark at a time."}, {"name": "Grand Conjunction", "prereq": "Prerequisite: Maximum: Festival of Falling Stars", "text": "You merge held meteors into a greater one. When you launch meteors as a bonus action, you may merge two or more into a single burst: it creates a 15-foot-radius burst dealing 4d8 per merged meteor, with a Dexterity save for half. Declare the merger before launching."}], "e047": [{"name": "Beast’s Agility", "prereq": "Prerequisite: Destined Death", "text": "After using Beast Step, you may move along walls or ceilings for that movement without falling until it ends, the beast’s stride ignoring the floor’s claim on it."}, {"name": "Rune-Eater", "prereq": "Prerequisite: Deathbrand", "text": "When a creature with Fate Scars spends 3+ CE on one activation, once per round you may use your reaction to extend all its Fate Scars by 1 round."}, {"name": "Black Knife Geometry", "prereq": "Prerequisite: Black Blade Wave", "text": "Black Blade Wave ignores half and three-quarters cover and can originate from the edge of your manifested blade even while you are airborne."}, {"name": "The Beast Collects", "prereq": "Prerequisite: level 11", "text": "You harvest the dooms you have marked. When you would drop to 0 HP, use your reaction and spend 3 CE to consume all Fate Scars on one creature you can see within 60 feet, regaining 10 HP per scar consumed. If this healing leaves you above 0 HP, you do not fall unconscious."}], "e048": [{"name": "Sigil Shatter", "prereq": "Prerequisite: Dark Moon Covenant", "text": "As a bonus action, consume all Lunar Sigils on one creature you can perceive within Lunar Range. It takes 5 cold damage per sigil consumed, and its speed is reduced by 10 feet until the end of your next turn as the shattered cold sinks into its limbs."}, {"name": "Bell of Many Ashes", "prereq": "Prerequisite: Ashen Familiar", "text": "When your Ashen Familiar is destroyed, its ashes remember the cold. It bursts into freezing mist: creatures within 10 feet of it make a Constitution save against your Technique DC, taking 5 cold damage and suffering −10 speed until the end of your next turn on a failure, or half damage on a success."}, {"name": "Occult Moon", "prereq": "Prerequisite: Cold Moon Guard", "text": "The dark moon returns what it swallows. When Cold Moon Guard fully negates a ranged technique attack, you may immediately make one Lunar Bolt attack against the attacker as part of the same reaction, spending 1 CE or 1 Moon Shard."}, {"name": "Fingerslayer Principle", "prereq": "Prerequisite: level 11", "text": "Your Dark Moon learns new prey. It may target control effects, barriers, and technique-created constructs in addition to technique manifestations, using the normal suppression check. Domains remain beyond it."}], "e049": [{"name": "Feed the Flame", "prereq": "Prerequisite: Flame of Frenzy", "text": "As a bonus action, voluntarily gain 1 Madness, feeding the fire on purpose. The next Frenzy feature you use before the end of your turn deals +1 Frenzy Die."}, {"name": "Shabriri’s Cry", "prereq": "Prerequisite: Howl of Frenzy", "text": "You learn to aim the howl. While Howl of Frenzy is active, you may use your bonus action to loose a focused cry at one creature within 30 feet that can hear you; it makes a Wisdom save against your Technique DC, becoming frightened of you until the end of its next turn on a failure. The cry adds no Madness."}, {"name": "Yellow-Eyed Prophet", "prereq": "Prerequisite: level 6", "text": "You can sense frightened, charmed, or Madness-affected creatures within 120 feet even without line of sight."}, {"name": "Lord Candidate", "prereq": "Prerequisite: level 11", "text": "The first time each long rest you would gain Madness above 10, instead gain PB temporary HP per excess point and remain at 10."}], "e050": [{"name": "Apostle’s Reach", "prereq": "Prerequisite: Black Flame Apostasy", "text": "In Apostle stance, your opportunity attacks may apply Kindling, paying its normal CE cost — the long limb punishes retreat with godfire."}, {"name": "Shared Vestments", "prereq": "Prerequisite: Black Flame Apostasy", "text": "As a bonus action for 1 CE, extend your Godskin Stance to one willing creature within 15 feet until the start of your next turn. It gains the stance’s passive benefits — Apostle’s speed and reach, or Noble’s armor and stability — but not your armament, Black Flame, or stance actions."}, {"name": "Swaddling Cloth", "prereq": "Prerequisite: Swaddling Recovery", "text": "When you would gain temporary HP from Swaddling Recovery, you may instead grant those temporary HP to one willing creature within 15 feet, wrapping it in spectral swaddling cloth."}, {"name": "Choir of Two", "prereq": "Prerequisite: Skinbound Partner", "text": "Partner gains proficiency in one skill you have; while within 30 feet, you may perceive through its senses without an action."}], "e051": [{"name": "Assassin’s Hands", "prereq": "Prerequisite: Living Circuit", "text": "Once per turn after Lightning Palm hits, you may move 5 feet without provoking opportunity attacks, the discharge grounding through your step and carrying you clear."}, {"name": "Ground Current", "prereq": "Prerequisite: Living Circuit", "text": "As an action for 2 CE, discharge your Bioelectric Aura into a conductive surface — water, metal, wet stone — within 5 feet of you. Until the start of your next turn, any creature that starts its turn touching that surface within 20 feet of you must succeed on a Constitution save against your Technique DC or lose its reactions until the start of its next turn."}, {"name": "Programmed Guard", "prereq": "Prerequisite: Whirlwind", "text": "You may write Reflex Programs keyed to your own failures — ’when I fail a Dexterity save, reroute.’ When such a trigger occurs, you may use your reaction to move up to 10 feet without provoking opportunity attacks, turning the failure into repositioning."}, {"name": "Arc Relay", "prereq": "Prerequisite: Godspeed", "text": "Your palm’s lightning learns to jump. When Lightning Palm hits, you may spend 1 CE to arc the discharge to one creature within 15 feet of the target; it makes a Constitution save against your Technique DC, losing its reactions until the start of its next turn on a failure."}], "e052": [{"name": "Flowing Blade Disciple", "prereq": "Prerequisite: Scarlet Bloom", "text": "When you move through a hostile creature’s threatened space using Flowing Sword, you may leave an afterimage behind. The next attack that creature makes against you before the start of your next turn has disadvantage, striking the image instead. Once per round."}, {"name": "Cleanrot Resolve", "prereq": "Prerequisite: Rot Marks", "text": "The hand that sows the rot can reap it. As an action for 2 CE, touch a creature bearing your Rot Marks or suffering your Scarlet Rot and end the condition, removing all marks. Mercy, interrogation, or cleaning up after your own Aeonia — the rot obeys its gardener."}, {"name": "Waterfowl Savant", "prereq": "Prerequisite: Waterfowl Dance", "text": "You may perform Waterfowl Dance as a defensive spiral, forgoing all of its attacks. Until the start of your next turn, melee attacks against you have disadvantage and your movement does not provoke opportunity attacks."}, {"name": "Rot-Petal Squall", "prereq": "Prerequisite: Scarlet Wings", "text": "While Scarlet Wings is active, as a bonus action for 1 CE, beat your wings in a rot-laden gust. Each hostile creature within 15 feet makes a Constitution save against your Technique DC; on a failure it gains one Rot Mark. A creature can gain only one mark this way per round."}], "e053": [{"name": "Carian Dueling Form", "prereq": "Prerequisite: Twin Moon Armament", "text": "As a bonus action for 1 CE, mark one creature within 30 feet as your duelist until the end of your next turn. If you hit it with both a Moon-imbued and a Flame-imbued attack while it is marked, it becomes Eclipsed until the end of its next turn: it has disadvantage on attack rolls against creatures other than you."}, {"name": "Phalanx Reserve", "prereq": "Prerequisite: Carian Phalanx", "text": "As a bonus action, order your active glintblades into a screening orbit until the start of your next turn. Ranged attacks against you have disadvantage; each time a ranged attack misses you, one glintblade of your choice shatters intercepting it."}, {"name": "Messmer Ember", "prereq": "Prerequisite: Flame Spiral", "text": "Your spiral leaves an ember wake. Each hostile creature whose space you enter during Flame Spiral’s post-resolution movement takes 1 Twin Die of fire damage; a creature takes this damage only once per Spiral."}, {"name": "Moon Princess’s Guard", "prereq": "Prerequisite: Twin Aspect Guard", "text": "Your ward extends to another. When you use Twin Aspect Guard, you may also shield one willing creature within 10 feet: it gains the same reduction against the next instance of the matching damage type before the start of your next turn."}], "e054": [{"name": "Dragon Communion Savant", "prereq": "Prerequisite: Dragonheart Incarnation", "text": "Learn one additional lineage’s breath rider; you may apply it to your primary Breath by paying +1 CE, without gaining its resistance."}, {"name": "Scale Shelter", "prereq": "Prerequisite: Gravel Scales", "text": "While Gravel Scales is active, as a bonus action you may extend stony plates over one willing creature within 5 feet; it gains +1 AC until the start of your next turn. Your own scales are not diminished by the sharing."}, {"name": "Winged Predator", "prereq": "Prerequisite: Wings", "text": "After descending at least 20 feet before a melee attack, the target makes a Strength save or falls prone; you land without falling damage."}, {"name": "Dragonlord’s Echo", "prereq": "Prerequisite: level 11", "text": "The storm answers at a distance. You may originate Dragonstorm at a point you can see within 90 feet instead of centered on yourself, shaping the same 30-foot-radius storm around that point."}], "e055": [{"name": "Loaded Feint", "prereq": "Prerequisite: Jajanken Feint", "text": "You can spend real aura to sell a fake release. When you use Jajanken Feint, you may release one stored Charge Beat; the target has disadvantage on its Insight check against the feint, fooled by the genuine discharge."}, {"name": "Hidden Hand", "prereq": "Prerequisite: level 3", "text": "Creatures have disadvantage on checks to determine which Jajanken choice you will make, and your Feint can target up to PB observers."}, {"name": "Greed Island Training", "prereq": "Prerequisite: level 6", "text": "While charged, you may use your reaction to add one Jajanken Die to a Strength or Constitution save, then lose one Beat."}, {"name": "One More Round", "prereq": "Prerequisite: level 11", "text": "After releasing a 5+ Beat Jajanken, move up to half speed without provoking from the creature you targeted."}], "e056": [{"name": "Southpaw Cyclotron", "prereq": "Prerequisite: Ripper Cyclotron", "text": "Choose left or right arm each time you begin winding. Rotations belong to that arm; you may maintain separate totals, but your global cap is shared."}, {"name": "Backlash Wind", "prereq": "Prerequisite: level 3", "text": "The wound arm lashes out on its own. As a reaction when a creature misses you with a melee attack, you may spend 2 Rotations to make one unarmed strike against it."}, {"name": "Counting Out Loud", "prereq": "Prerequisite: Ripper Cyclotron", "text": "Sometimes the count is the weapon. As a bonus action, wind theatrically without storing a Rotation — a feinted count. One creature that can see you contests its Insight against your Deception or Intimidation; on a failure it has disadvantage on its next attack roll against you before the start of your next turn, flinching from the expected blow."}, {"name": "Fifteen Is Plenty", "prereq": "Prerequisite: level 6", "text": "When you spend exactly 15 Rotations on an attack that triggers Shockwave Punch, you may shape the shockwave into a 30-foot line instead of a cone, and creatures in the line have disadvantage on the Dexterity save. Precision earns its own reward."}], "e057": [{"name": "Field Surgeon", "prereq": "Prerequisite: Doctor Blythe", "text": "Blythe can stabilize a dying creature within tether range as a reaction without CE once per round."}, {"name": "Invisible Strings", "prereq": "Prerequisite: Puppeteer", "text": "Your Puppeteer attachments are hidden from passive CE perception; active Perception/CE check vs your DC reveals them."}, {"name": "Feral En", "prereq": "Prerequisite: Predatory En", "text": "You can shape En as a narrow tendril at twice normal range or a broad sphere at one-quarter range."}, {"name": "Dance Beyond Death", "prereq": "Prerequisite: Terpsichora", "text": "When Terpsichora would end because you are incapacitated, spend 3 CE before becoming unable to act; it persists until end of your next turn and moves you defensively according to a preset command."}], "e058": [{"name": "Kind Creditor", "prereq": "Prerequisite: Hakoware", "text": "When you forgive Debt with Payment Plan or manually before level 11, the debtor gains temporary HP equal PB; cannot affect yourself."}, {"name": "Repo Agent", "prereq": "Prerequisite: level 6", "text": "Repossession can trigger when a debtor activates a cursed tool costing CE or feeds CE into a barrier, not only an innate technique."}, {"name": "Foreclosure Notice", "prereq": "Prerequisite: level 11", "text": "As an action for 2 CE, serve notice on one creature within Hakoware range bearing your A.P.R. It makes a Wisdom save against your Technique DC; on a failure it is frightened of you until the end of its next turn, and on a success its speed is reduced by 10 feet until the end of its next turn as the debt drags at its heels."}, {"name": "No Defaulting", "prereq": "Prerequisite: Bankruptcy", "text": "A Bankrupt creature cannot hide its CE signature from you and has disadvantage on checks to deceive you about its current CE state."}], "e059": [{"name": "Lung of the Sea", "prereq": "Prerequisite: Deep Purple", "text": "You can hold your breath for 30 minutes and have advantage on saves against inhaled poisons/gases."}, {"name": "Purple In", "prereq": "Prerequisite: Living Decoy", "text": "You may hide the CE signature of up to PB smoke constructs at once; active CE Perception vs your DC can reveal them."}, {"name": "Trooper Doctrine", "prereq": "Prerequisite: Smoke Details", "text": "Choose one preset doctrine after long rest: Guard (+1 AC), Pursue (+10 speed), or Rescue (can drag willing/unconscious allies without speed penalty). All Details use it."}, {"name": "Jailhouse Rock", "prereq": "Prerequisite: Smoky Jail", "text": "Your jail can roll. When you create Smoky Jail, you may anchor it to yourself so it moves with you, keeping its radius centered on you. A rolling jail’s barrier HP is reduced by 5 × PB (minimum 10) — mobility has a price in smoke."}], "e060": [{"name": "Low Waltz", "prereq": "Prerequisite: Battle Waltz", "text": "As a bonus action, send one active top spinning into a hostile creature’s space within 30 feet of the top. The creature makes a Dexterity save against your Technique DC or falls prone, tripped by the waltzing top; the top then returns to its previous position."}, {"name": "Gyro Balance", "prereq": "Prerequisite: Dancing Top", "text": "As a bonus action, attune one willing creature within 30 feet to your tops’ gyroscopic rhythm until the start of your next turn. It has advantage on ability checks and saving throws against being knocked prone, steadied by the hum."}, {"name": "Blue Shot", "prereq": "Prerequisite: Shotgun Blues", "text": "When using single-target Shotgun Blues, sacrifice one selected top to add 2 Top Dice; the sacrificed top shatters after damage."}, {"name": "Ringmaster", "prereq": "Prerequisite: level 11", "text": "You may designate PB willing creatures that your simple “attack nearby” orders automatically treat as friendly."}], "e061": [{"name": "Armored Vessel", "prereq": "Prerequisite: Anime & Manga, level 4+", "text": "While Full Cowl is active, your whole body is one braced vessel. When you take falling damage or damage from a collision, you may use your reaction to reduce it by one Stockpile Die + PB, the distributed output absorbing the impact."}, {"name": "Tendril Snare", "prereq": "Prerequisite: Blackwhip", "text": "As an action for 2 CE, weave Blackwhip tendrils into a lattice across a 15-foot cube within reach. Until the start of your next turn the cube is difficult terrain for hostiles, and the first hostile to enter it must succeed on a Strength save against your Technique DC or be restrained until the end of its next turn."}, {"name": "Council of Embers", "prereq": "Prerequisite: at least two awakened Vestiges", "text": "The past bearers hold counsel. Spend 10 minutes in meditation to convene them; you gain advantage on one Intelligence or Wisdom check made within the next hour, as the vestiges weigh in with lifetimes of experience."}, {"name": "Smash Artisan", "prereq": "Prerequisite: Air Force or Kinetic Surge", "text": "You fuse your signature forms. When you hit with a Smash, you may spend 2 CE to add one rider from another Smash form you know: Groundbreak's prone (Dexterity save negates), St. Louis's push (5 feet × Output Band; Strength save halves), or Whip-Sling's continued movement (up to half your remaining speed). Only one added rider per Smash."}], "e099": [{"name": "Passive Filter", "prereq": "Prerequisite: level 3", "text": "You have learned to share your calculations: once per round, when an ally within 15 ft would be hit by a known physical vector, you may spend your reaction and 1 CE to extend your Filter over them, reflecting the attack as if it targeted you."}, {"name": "Kihara Counterstudy", "prereq": "Prerequisite: level 6", "text": "Once you have witnessed a creature bypass your Filter, you learn the path it took: once per long rest, when that creature attacks you with the same bypass method, you may spend a reaction and 2 CE to reflect the attack back along its own bypass path — it cannot use that method to avoid the reflection."}, {"name": "Borrowed Vector", "prereq": "Prerequisite: level 9", "text": "Reaction when an ally within 30 ft willingly moves: redirect up to 20 ft of that movement to yourself or another willing creature."}, {"name": "White Wings", "prereq": "Prerequisite: Black Wings", "text": "When Black Wings would end, you may spend 4 CE to shed the wings in a single vector discharge instead: each creature within 20 ft makes a Str save, taking 4 Vector Dice force and being pushed 20 ft on a failure, or half damage and no push on a success. Black Wings then ends."}], "e100": [{"name": "Good Dog", "prereq": "Prerequisite: Dominion", "text": "Your Compelled creatures throw themselves in harm's way: once per round, when you would be hit by an attack, a Compelled creature within 15 ft may use its reaction to interpose itself, becoming the target instead."}, {"name": "Contract Lawyer", "prereq": "Prerequisite: Public Safety Contract", "text": "You enforce the fine print: when a creature breaks the stated price of a written contract you hold or witnessed, you may spend a reaction and 2 CE to call in the debt — it makes a Cha save, becoming Dominion-eligible until the end of its next turn on a failure."}, {"name": "Lower Yourself", "prereq": "Prerequisite: level 6", "text": "Bonus action, 2 CE: one creature you damaged this turn makes Wis save; failure is Frightened of you until end next turn and therefore becomes Dominion-eligible."}, {"name": "Remote Handler", "prereq": "Prerequisite: Eyes and Ears", "text": "You may issue simple commands telepathically to Dominated creatures within 1 mile."}], "e101": [{"name": "Vrrrm Vrrrm", "prereq": "Prerequisite: Rip Cord", "text": "You rev the chainsaws as you manifest them: when you activate Rip Cord, you may spend 2 Blood tokens to make the manifestation itself an attack — each creature within 5 ft makes a Dex save, taking one Devour Die slashing on a failure."}, {"name": "Blood Lash", "prereq": "Prerequisite: Blood-Fed Engine", "text": "As a bonus action, spend 3 Blood tokens to extend your chainsaws with whips of pressurized blood: your chainsaw attacks gain 10-ft reach until the end of your turn."}, {"name": "Door to Hell", "prereq": "Prerequisite: level 9", "text": "When you reduce a cursed spirit to 0 HP, learn whether it has previously manifested elsewhere or can reincarnate under campaign lore."}, {"name": "Save Me, Chainsaw Man", "prereq": "Prerequisite: Hero of Hell", "text": "Reaction when an ally within 60 ft drops to 0 HP: move up to speed toward them and make one chainsaw attack against a creature adjacent to them."}], "e102": [{"name": "Ki Savant", "prereq": "Prerequisite: Ki Read", "text": "While Ki Read is active, you may spend a bonus action to focus on one creature you sense: you learn whether it is concentrating on a technique or effect, and you have advantage on the first Black Hole contest against its effects this round."}, {"name": "Dark Cloaked Blade", "prereq": "Prerequisite: level 3", "text": "Your weapon counts as magical/cursed while technique is available and may deal necrotic instead of its normal physical type."}, {"name": "Black Hole Mastery", "prereq": "Prerequisite: Black Hole", "text": "You have learned to catch rather than merely erase: when Black Hole consumes a projectile or line effect, you may spend a reaction and 2 CE to hold it for one round, then release it as a 60-ft line using its original damage dice (Dex save for half)."}, {"name": "Surpass Your Limits", "prereq": "Prerequisite: level 11", "text": "When you are reduced to 0 HP, before falling you may spend all remaining CE (minimum 5) to release one final Dimension Slash along your facing; resolve the attack, then fall unconscious."}], "e103": [{"name": "Second Hand", "prereq": "Prerequisite: Time Theft", "text": "You lend stolen seconds to others: when an ally within 30 ft fails a saving throw, you may spend a reaction and 2 TU to grant them a borrowed moment — they reroll the save and take the better result. Once per round."}, {"name": "Precise Stasis", "prereq": "Prerequisite: Stasis Sphere", "text": "You may allow a frozen target to perceive/speak while still preventing movement/actions."}, {"name": "Borrowed Second", "prereq": "Prerequisite: level 9", "text": "Reaction, spend 3 TU to grant an ally within 30 ft +10 ft movement and one object interaction immediately."}, {"name": "Grand Clock", "prereq": "Prerequisite: level 15", "text": "Your mastery of the rewind is surgical: when you use Chrono Anastasis, you may spend 2 TU per creature to exclude up to PB creatures from the rewind — they keep their current HP, positions, and conditions."}], "e104": [{"name": "Anti-Magic Swordsman", "prereq": "Prerequisite: Demon-Slayer", "text": "Your sword drinks curses aimed at others: when an ally within 5 ft must save against an external CE effect, you may use your reaction to interpose your anti-cursed sword — they use your save result in place of their own."}, {"name": "Bull Thrust", "prereq": "Prerequisite: Black Form", "text": "When you take the Dash action and move at least 20 feet in a straight line, you can use a bonus action to drive your anti-cursed sword into a creature you move adjacent to during the dash, making a single melee attack with the sword as the charge’s momentum carries the cut."}, {"name": "Sword Flight", "prereq": "Prerequisite: Demon-Dweller", "text": "Ride Demon-Slayer/Dweller for fly speed equal walking while Black Form is active."}, {"name": "Liebe's Partner", "prereq": "Prerequisite: Devil Union", "text": "When Devil Union ends, the departing devil's anti-magic discharges as a parting gift: as a reaction, you may end one ongoing CE effect on each hostile creature within 30 ft (as Demon-Destroyer, no check required)."}], "e105": [{"name": "Dustproof", "prereq": "Prerequisite: Decay", "text": "Your Decay recognizes its maker: you are immune to your own Decay damage, and ruined terrain you create is never difficult terrain for you. When you trigger Awakening or Deika Collapse, you may ride the crumble as part of the same action, moving up to your speed across the affected area — sinking through cracked ground and erupting at its edge. This movement does not provoke opportunity attacks from creatures standing in the decay."}, {"name": "Chain Reaction", "prereq": "Prerequisite: level 9", "text": "A creature reduced to 0 by Decay automatically spreads 1 Mark to all creatures touching it."}, {"name": "Selective Hand", "prereq": "Prerequisite: level 6", "text": "You can make ordinary hand contact without accidental Decay even under stress; advantage on saves against effects that would force your technique to trigger."}, {"name": "Ruined City", "prereq": "Prerequisite: Awakening", "text": "You shape the ruin as you make it: when you use Awakening, you may spend 1 CE to raise one 10-ft section of debris into a 5-ft-high rubble rampart (half cover) or collapse it into a 10-ft-deep pit (climb check to escape)."}], "e106": [{"name": "Surgeon's Hand", "prereq": "Prerequisite: Reconstruction", "text": "Your repairs rebuild more than flesh: when you heal a creature with Overhaul, you may spend 1 AP to also end one poison or disease affecting them, disassembling the affliction outright."}, {"name": "Living Architecture", "prereq": "Prerequisite: Ground Spikes", "text": "Your structures wake at your command: when you create terrain with Ground Spikes or Terrain Dominion, you may spend 1 CE to animate one 10-ft section for 1 minute — it moves 20 ft per round under your bonus-action command and may make one slam attack (+CE attack bonus, 2 Overhaul Dice bludgeoning)."}, {"name": "Clean Fusion", "prereq": "Prerequisite: Fusion", "text": "You fuse cleanly under pressure: when you or a willing creature within 5 ft takes damage, you may spend a reaction and 1 AP to begin Fusion immediately; it completes at the start of your next turn, and the triggering damage is divided evenly between you. Normal costs apply when it completes."}, {"name": "Plague Mask", "prereq": "Prerequisite: level 9", "text": "You overhaul the very air: as an action, spend 1 AP to disassemble contaminants in a 15-ft cube around you for 1 minute — inhaled poisons and diseases are destroyed on contact, and creatures in the cube have advantage on saves against airborne hazards."}], "e107": [{"name": "Baskerville", "prereq": "Prerequisite: Black Hound", "text": "Your hound hunts with a body now: Black Hound may grapple creatures up to Large using your CE attack bonus for the grapple check, and while it holds a victim you may spend 1 soul as a bonus action to have it drag them 15 ft."}, {"name": "Casull & Jackal", "prereq": "Prerequisite: level 3", "text": "Gain paired cursed firearms; ranged attacks 60/240 ft use Dex or CE ability and qualify for technique riders, but not for automatic soul consumption."}, {"name": "No Life King", "prereq": "Prerequisite: Extra Life", "text": "They watched you refuse to die: when Extra Life triggers, you may spend 1 additional soul to let the moment land — each hostile within 10 ft that witnessed it makes a Wis save, becoming Frightened of you until the end of your next turn on a failure."}, {"name": "Named Dead", "prereq": "Prerequisite: Named Familiar", "text": "The named dead still talk: you may spend 10 minutes communing with one stored Elite/Named soul, asking three questions about its life (answered truthfully for what it knew) or gaining advantage on one History, Arcana, or Insight check drawing on its expertise."}], "e108": [{"name": "Crimson Bullet", "prereq": "Prerequisite: Parts Bullet", "text": "You have learned to plant rather than merely fire: you may fire a Parts Bullet into an unattended object or surface within 60 ft without damaging it; the embedded part remains for 1 minute, and as a bonus action you may detonate it — creatures within 10 ft make a Dex save, taking 3 Undead Dice slashing on a failure."}, {"name": "Bloody Arts", "prereq": "Prerequisite: Blood Propulsion", "text": "Your propulsion carries more than you: when you Blood Propel, you may bring one willing creature you touch along (it does not provoke), or drag one creature you are grappling. A carried willing creature may make one melee attack at any point during the movement."}, {"name": "Sword in the Body", "prereq": "Prerequisite: Repair Boost", "text": "Draw/store one one-handed weapon inside your regenerating body; cannot be disarmed of it while conscious."}, {"name": "Never Stop", "prereq": "Prerequisite: level 15", "text": "Once/short rest when Restrained, Paralyzed, or Stunned, spend 10 Repair to repeat the relevant save immediately."}], "e109": [{"name": "Perfect Sheathe", "prereq": "", "text": "When you reduce a hostile creature to 0 HP, you may spend 2 Concentration as a reaction to sheathe Yamato in one perfect motion: each hostile within 10 ft that witnessed it makes a Wis save, becoming Frightened of you until the end of your next turn on a failure."}, {"name": "Rapid Slash", "prereq": "", "text": "After using Trick, your first Yamato attack this turn may cleave into a second creature within 10 ft of the first: split the attack's damage dice evenly between them, rolling one attack roll against each."}, {"name": "Summoned Sword Master", "prereq": "", "text": "You may spend 2 unspent Mirage Blades as a bonus action to weave them into a spinning guard: until the start of your next turn, ranged attacks against you have disadvantage and you gain +2 AC against them."}, {"name": "Dark Slayer", "prereq": "", "text": "While you are at 10 Concentration, when you are targeted by an attack you may use your reaction to spend 1 CE and Trick up to 30 ft before the attack resolves; the attack misses if it can no longer reach you. If you reappear within 10 ft of the attacker, you may make one Yamato attack against them as part of the same reaction."}], "e110": [{"name": "Enemy Step", "prereq": "", "text": "When you hit a creature your size or larger with a melee attack, you may use your reaction to springboard off them: leap up to 20 ft in any direction without provoking, and the creature makes a Str save or is knocked prone by the push-off."}, {"name": "Royal Guard Savant", "prereq": "", "text": "You guard others as yourself: as a reaction when an ally within 10 ft takes damage, you may spend 2 Guard to interpose — you take the damage instead, reduced by your Royalguard reduction (1d10 + level)."}, {"name": "Weapon Freak", "prereq": "", "text": "Once per turn, when you hit with a bound Devil Arm, you may draw a second bound Devil Arm and make one attack with it as a bonus action, provided it is a different named attack than your previous qualifying action (it still advances Style)."}, {"name": "Jackpot", "prereq": "", "text": "When you roll a natural 20 on a ranged attack, you may call Jackpot: instead of rolling critical damage, fire a celebratory spread — up to two other creatures within 15 ft of the target take half the attack's damage (Dex save for half)."}], "e111": [{"name": "Long Blade", "prereq": "", "text": "Once per turn, when you miss with Masamune, you may extend the swing into a second creature within 15 ft of the first, making a new attack roll at disadvantage."}, {"name": "Chosen by Jenova", "prereq": "", "text": "When you would be subjected to a disease, poison, or transformation effect, you may spend a reaction to let Jenova's cells devour it: you are unaffected, and you learn the effect's nature and source."}, {"name": "Peerless SOLDIER", "prereq": "", "text": "When you use Octaslash, you may move up to 10 ft between each attack without provoking opportunity attacks, and each slash may target a different creature. This movement does not count against your speed for the turn, letting you carve a path through a scattered formation in a single action."}, {"name": "Black Materia", "prereq": "", "text": "Supernova charge cannot be interrupted by ordinary damage once/long rest."}], "e112": [{"name": "Moon of Mahaa-Kalaa", "prereq": "", "text": "When a creature misses you with a melee attack, you may spend your reaction and 1 Tempo to parry the blow into another creature within 5 ft of you: reroll the attack against that creature."}, {"name": "Bat Within", "prereq": "", "text": "When you take damage from an effect you could see, you may spend 1 Tempo as a reaction to burst into a swarm of bats: you take half damage and immediately move 15 ft without provoking, reforming at the destination."}, {"name": "Accessory Witch", "prereq": "", "text": "Your accessories drink your Witch Time: once per turn, when you trigger Witch Time, you may also activate one accessory's effect as part of the same reaction without spending its normal action."}, {"name": "Pure Platinum", "prereq": "", "text": "Your debut is flawless: the first time each combat you trigger Witch Time, you may extend its effects to one additional creature within 30 ft (speed 0, no reactions) until the end of your next turn."}], "e113": [{"name": "Conductive Arc", "prereq": "", "text": "You may fire Lightning Bolt at an unattended metal object or conductive surface within range instead of a creature: the charge arcs outward — each creature within 10 ft of the point makes a Dex save, taking the bolt's damage on a failure."}, {"name": "Polarity Shift", "prereq": "", "text": "When a creature within 30 ft makes a ranged weapon attack, you may spend 1 Charge as a reaction to bend the projectile's path: redirect the attack to a different creature within 15 ft of the original target, making a new attack roll."}, {"name": "Thunder Drop", "prereq": "", "text": "When you fall at least 20 ft, you may spend 1 Charge as a reaction just before landing: you take no falling damage, and the grounded impact erupts — each creature within 10 ft of where you land makes a Dexterity save, taking 2d8 lightning damage on a failure. Structures and unattended metal objects in the burst take double dice."}, {"name": "Karmic Overload", "prereq": "", "text": "You may discharge all remaining Charge at once (minimum 6) as an action: each creature within 20 ft makes a Con save, taking 1d8 lightning per 2 Charge discharged on a failure (half on success); you are left at 0 Charge."}], "e114": [{"name": "Smoke & Mirrors", "prereq": "", "text": "When you use Smoke Dash, you may leave a 10-ft-radius cloud of thick smoke in the space you departed: it heavily obscures the area until the start of your next turn. The first attack you make before the cloud fades has advantage if its target cannot see you."}, {"name": "Neon Runner", "prereq": "", "text": "You run through enemies as light: when you Neon Dash, you may pass through hostile creatures' spaces — each must make a Dex save or take 2d8 radiant damage."}, {"name": "Digital Angel", "prereq": "", "text": "When you activate Video flight, you may spend 2 CE to hard-light the wings into blades for the round: you may make one Video Blade attack at any point during the movement, and attacking does not end the flight early."}, {"name": "Concrete Skin", "prereq": "", "text": "When you take bludgeoning, piercing, or slashing damage, you may spend 1 CE as a reaction to petrify the wound shut: reduce the damage by 1d10 + your CE modifier, and you cannot be moved against your will until the start of your next turn."}], "e115": [{"name": "Parkour Predator", "prereq": "", "text": "You gain a climb speed equal to your walking speed, and your claws let you climb sheer surfaces without needing free hands. When you take the Dash action, your long jump distance is doubled, and you may launch a jump directly out of a climb without landing first."}, {"name": "Patsy", "prereq": "", "text": "You consume intentions along with flesh: when you Consume a creature, you learn one short-term goal or plan it held (GM's discretion), and you may spend 5 Biomass to perfectly reproduce one specific memory under questioning for 10 minutes."}, {"name": "Adaptive Biomass", "prereq": "", "text": "Your body eats what hurts it: when you take damage of a type, you may spend 5 Biomass as a reaction to analyze it — the next time you take that damage type this combat, you may convert up to 10 of it into Biomass instead of losing HP."}, {"name": "Pack Leader", "prereq": "", "text": "As an action, spend 15 Biomass to tear free a piece of yourself that grows into an infected hound: use the wolf stat block, but it has 1 HP and adds your PB to its attack and damage rolls. It obeys your commands and acts immediately after you in initiative; after 10 minutes, or when reduced to 0 HP, it collapses into 5 Biomass you may reabsorb by touching it."}], "e116": [{"name": "Let Me Solo", "prereq": "", "text": "You know this boss: when facing a boss-tier creature you have fought before, you may spend 1 minute studying its patterns before combat (or an action and a DC 15 Insight check during it) to learn one of its resistances, immunities, or legendary actions."}, {"name": "Potent Ash", "prereq": "", "text": "You layer arts on a single weapon: when you bind an Ash of War, you may bind a second art to the same weapon for 1 extra CE, switching between them as a bonus action."}, {"name": "Rune Arc", "prereq": "", "text": "You project the rune outward: you may suppress your Great Rune's passive benefit for 1 minute to instead grant it to allies within 30 ft — they gain the benefit while you lose it."}, {"name": "Thy Strength Befits a Crown", "prereq": "", "text": "Your victories crystallize faster now: when you personally reduce a boss-tier creature to 0 HP, you may immediately attempt to crystallize a Remembrance from it, spending the usual costs, without waiting for post-combat downtime."}], "e117": [{"name": "Spider-Sense Echo", "prereq": "", "text": "The symbiote watches your blind spots: attackers gain no advantage against you from flanking or pack tactics, and when a hidden creature attacks you, you learn its direction immediately after the attack resolves."}, {"name": "Living Parachute", "prereq": "", "text": "When you begin to fall, you may use your reaction to have the symbiote snap out web-wings: you take no falling damage and glide instead, moving up to 60 ft horizontally for every 10 ft you descend, and you land on your feet. You may steer around obstacles while gliding but cannot gain altitude."}, {"name": "Eat Your Brains", "prereq": "", "text": "You taste memories with the flesh: when you damage a grappled creature with a bite, you may spend 1 CE to learn one fact it knows (GM's discretion) or gain advantage on your next Insight check against it."}, {"name": "Anti-Sonic Conditioning", "prereq": "", "text": "You separate on your own terms: once per long rest, when sonic damage would forcibly separate you, you may instead partially detach on purpose — one tendril swarm (half the King in Black Echo swarm's dice) acts independently for 1 minute while you remain bonded."}], "e118": [{"name": "Blood Trail", "prereq": "", "text": "When you damage a living creature with a Red Weapon, you taste its blood: for the next hour you unerringly know its direction while it is within 1 mile of you, and you have advantage on Wisdom (Perception) checks to detect it while it is within 60 ft. The trail ends early if you wound another creature — you can only savor one hunt at a time."}, {"name": "Wall of Teeth", "prereq": "", "text": "You catch what strikes you: when a creature hits you with a melee attack, you may spend your reaction to snare the limb in the symbiote's maw — it makes a Str save or is grappled by you (escape DC = technique DC)."}, {"name": "Red Rain", "prereq": "", "text": "Instead of adding Shard Volley's die to a weapon hit, you may spend 1 CE as an action to hurl a spray of symbiote shards at up to two creatures within 30 ft: make a ranged technique attack against each, dealing 1d8 piercing damage on a hit. This counts as your Shard Volley use for the turn."}, {"name": "Born Killer", "prereq": "", "text": "You mark the dying: once per turn, when you hit a creature below half HP with a Red Weapon, you may forgo the damage to leave a bleeding wound instead — the next attack against it before the end of your next turn has advantage."}], "e119": [{"name": "Invisible Objects", "prereq": "", "text": "When you activate Invisibility, objects you wear and carry share it — they flicker visible for a round when you attack, exactly as you do. Additionally, you may spend 1 extra CE to veil one unattended object or 10-ft surface you touch; it remains invisible for the full 10 minutes even if your own invisibility ends early, letting you hide a door, a trap, or an ally's hiding spot."}, {"name": "Hard-Light Step", "prereq": "", "text": "When you are shoved, knocked prone, or begin to fall, you may use your reaction and spend 1 CE to flash-form a hard-light foothold beneath you: move up to 10 ft to an unoccupied space, including mid-air, without provoking opportunity attacks. If you were falling, you land safely on the platform instead, and it supports your weight until the start of your next turn."}, {"name": "Fine Control", "prereq": "", "text": "Your force constructs gain fine articulation: any platform, bubble, wall, or dome you create can manipulate objects like a spectral hand. As a bonus action you may have a construct make a Dexterity (Sleight of Hand) check using your CE attack bonus, lift up to 10 lb, or operate a simple mechanism within 60 ft — picking a lock, turning a key, or pulling a lever from across the room."}, {"name": "Mother's Shield", "prereq": "", "text": "when you intercept an attack targeting an ally with Force Screen, you may also slide the ally up to 10 ft to unoccupied ground as part of the same reaction."}], "e120": [{"name": "Hotshot", "prereq": "", "text": "at Heat 5+, your fire bolt can be fired as a focused lance: one creature within 120 ft, ignoring half and three-quarters cover. This uses your action and deals normal fire bolt damage."}, {"name": "Skywriter", "prereq": "", "text": "You shape flame and smoke with photographic precision. As a bonus action, you may write a message, sketch a map, or conjure an image in the air — legible up to 1 mile away at night or 300 ft by day — that burns for 1 minute. You may also sculpt a flame-duplicate of yourself that lasts until the start of your next turn: the first attack made against you while it burns has disadvantage, as the attacker strikes the wrong target."}, {"name": "Thermal Updraft", "prereq": "", "text": "While flying with Jet Flight, you may carry one willing creature of your size or smaller without reducing your speed, cradling them in a heat-shielded updraft that grants them your fire resistance for the ride. Your fiery aura does not harm your passenger, and you may release them as a free action — if released within 30 ft of the ground, they drift down safely and land on their feet."}, {"name": "Flame Cage", "prereq": "", "text": "As an action for 2 CE, you raise a 10-ft-radius, 10-ft-tall ring of white-hot flame that lasts 1 minute (Focus). Any creature that enters the ring's wall or ends its turn there takes 3d8 fire damage, or half on a successful Dexterity save. The cage restrains through threat as much as flame: enemies inside must choose between burning through the wall or staying trapped."}], "e121": [{"name": "Lucky Hex", "prereq": "", "text": "once per short rest, when a hostile within 60 ft rolls a natural 1, you may use your reaction to spend one Chaos Die and redirect the failed roll onto a different target of your choice within range."}, {"name": "Chaos Vision", "prereq": "", "text": "as an action, you can read probability residue: learn what reality-altering or illusion effects have occurred within 60 ft in the last hour."}, {"name": "Red Thread", "prereq": "", "text": "when you use Hex, you may spend 1 additional CE to thread it through probability itself, targeting a creature you cannot see as long as you know its exact location within 60 ft."}, {"name": "What Hex?", "prereq": "", "text": "once per long rest, when a Chaos Surge would trigger, you may use your reaction to ground it in an unattended object within 30 ft instead: the object warps harmlessly (changes color, floats briefly) and the Surge is spent."}, {"name": "Nexus Being", "prereq": "", "text": "as a reaction when a creature within 30 ft would be teleported or forcibly displaced by a supernatural effect, you may spend 1 Chaos Die to pin its probability in place (contested against the effect's DC if opposed)."}, {"name": "Witch's Grief", "prereq": "", "text": "once per short rest, when you drop below 25% of your maximum HP, reality shudders: each hostile within 30 ft must succeed on a Wisdom save or roll its next attack, check, or save twice and take the worse."}], "e122": [{"name": "Hulk Catch", "prereq": "", "text": "When a ranged weapon or thrown-object attack hits you or an ally within 10 feet, you may use your reaction to snatch it out of the air: make a Strength (Athletics) check against the attack's total. On a success the attack is negated, and if the projectile is physical you may immediately hurl it back as part of the same reaction — make a ranged attack against a creature within 60 feet, dealing 3d10 + your Strength modifier bludgeoning damage on a hit. You need a free hand, and you cannot catch energy beams, sure-hits, or anything larger than Large."}, {"name": "Collateral Bulwark", "prereq": "", "text": "at Rage 5+, as a bonus action you can tear up the terrain into an improvised bulwark: until the start of your next turn, ranged attacks against you have disadvantage and you have half cover."}, {"name": "Banner's Mind", "prereq": "", "text": "You can force a moment of Banner-like lucidity inside the rage. As a bonus action, spend 2 Rage: for the next minute you ignore the disadvantage on Wisdom and Intelligence checks imposed by high Rage, retain full memory of what happens while transformed, and can speak in complete sentences. You may also end Hulk Out early by spending your action — your Rage falls to 0 and you revert to normal size — but your pulse needs a minute to steady, and you cannot transform again until then."}, {"name": "Green Scar", "prereq": "", "text": "at Rage 5+, as a bonus action you can spend 1 Rage to roar: creatures of your choice within 15 ft make a Wisdom save or become Frightened of you until the end of your next turn."}], "e123": [{"name": "Diplomatic Immunity", "prereq": "", "text": "Doom's sovereignty is itself a technique. When you formally invoke your rank, title, or the authority of Latveria, you have advantage on Charisma (Persuasion) and Charisma (Intimidation) checks for the next 10 minutes, and creatures that recognize your authority cannot willingly target you with hostile technique effects until you or an ally acts against them. This immunity is void against beings that do not recognize mortal titles — Domains, Calamity-grade horrors, and the genuinely insane."}, {"name": "Hidden Doombot", "prereq": "", "text": "Once per long rest, when you would be reduced to 0 HP, you may reveal that the 'you' just defeated was a Doombot all along — provided it is logically possible: you must have had a Doombot deployed this combat or an unspent Scheme slot, and no effect may have explicitly prevented the swap. You instead appear unharmed at a location of your choice within 60 feet, leaving the Doombot behind as sparking wreckage. This revelation costs no action; it was planned for long before the battle began."}, {"name": "Mystic Armor", "prereq": "", "text": "when you succeed on a save against a technique while wearing Doom Armor, you may spend 1 CE as a reaction to siphon its residue, gaining a Siphon token as if from Power Siphon."}, {"name": "DOOM Does Not Beg", "prereq": "", "text": "once per short rest, when you fail a Wisdom or Charisma save, you may use your reaction to file the attack as intelligence: you learn the source's technique and one named feature it used, and you gain advantage on saves against that source for 1 minute."}], "e124": [{"name": "Faster Than a Bullet", "prereq": "", "text": "When an ally within 20 feet is targeted by an attack, you may use your reaction to move up to 20 feet to a space adjacent to them — you may fly for this movement without spending Charge. If you end the movement between the attacker and your ally, the attack targets you instead. Damage you take this way is halved while your Solar Body is active; the Man of Steel was built for exactly this."}, {"name": "Freeze Breath", "prereq": "", "text": "When you use Super Breath, you may flash-freeze instead of pushing: targets make a Constitution save instead of Strength. On a failure they take the breath's cold damage and are Restrained until the end of your next turn, ice sheathing their limbs; on a success they take half damage and are not restrained. The ice melts at the end of your next turn, or early if the target takes 10 or more fire damage at once."}, {"name": "Hope", "prereq": "", "text": "as an action for 1 Solar Charge, each ally within 30 ft who can see you may immediately attempt a new save against one Frightened effect, with advantage."}, {"name": "Sun-Drinker", "prereq": "", "text": "when you take fire or radiant damage, you may use your reaction to absorb it: halve the damage and gain 1 Solar Charge. Once per round."}], "e125": [{"name": "Bullets & Bracelets", "prereq": "", "text": "when your Bracelets reduce a ranged attack's damage to 0, you may spend 1 Favor as a reaction to ricochet it: make a ranged technique attack against a creature within 60 ft, dealing the projectile's original damage on a hit."}, {"name": "Amazon Grappler", "prereq": "", "text": "a creature grappled by your Lasso cannot use reactions, and you may use your bonus action to drag it up to 15 ft."}, {"name": "Princess of Peace", "prereq": "", "text": "You are an emissary of Themyscira, not only its blade. If you spend one full minute formally de-escalating — speaking terms, offering quarter, letting the Lasso's spirit of truth hang over the table — you gain expertise in Charisma (Persuasion) for the duration of the negotiation, and any creature that accepts your terms must succeed on a Wisdom save to break its word to you within the next 24 hours. Rushed words gain nothing; peace takes a minute."}, {"name": "Warrior Born", "prereq": "", "text": "Your divine weapon is an oath, not an object. During a short or long rest, you may spend 10 minutes in Themysciran weapon-rites to rebind your armament: your sword becomes a spear, your spear a shield, your shield a sword — carrying the same divine enchantment, damage die, and Favor interactions. You may also reshape its appearance freely each rest; the gods recognize the wielder, not the shape."}], "e126": [{"name": "Creative Mind", "prereq": "", "text": "Your constructs are never single-purpose. When you forge a Complex Construct, you may weave one additional utility function into it at no extra Charge: silent operation, a built-in light source, a sealed airtight compartment, wheels or skids, or a fine-manipulation limb. The utility shares the construct's Integrity and duration, and cannot duplicate another feature's damage. There is always one more use for the ring."}, {"name": "Ring Slinging", "prereq": "", "text": "when you create a projectile construct, you may launch it from any point within 30 ft of you that you can see, rather than from yourself."}, {"name": "Fearless", "prereq": "", "text": "when a creature attempts to Frighten you, you may use your reaction to forge the fear into a construct: create a 10-Integrity construct shaped like the source of the fear. If it still exists at the start of your next turn, you gain 1 Will."}, {"name": "Emergency Protocol", "prereq": "", "text": "Your will outlives your body. Once per long rest, when you are reduced to 0 HP while wearing the ring, it flares on instinct: you are automatically stabilized and gain temporary HP equal to your remaining Will + your proficiency bonus, lasting 1 minute. You remain unconscious — but your constructs do not fall. Any you were maintaining persist for the minute, held together by refusal alone."}], "e127": [{"name": "Detective Mind", "prereq": "", "text": "Reading a mind is half of detection; understanding the reading is the other half. While you hold a creature's surface thoughts through Mind Link, you have advantage on Wisdom (Insight) checks against it, and you immediately sense when its words contradict the thoughts you are reading. Once per short rest, you may spend 1 CE as a bonus action to cross-reference: ask one yes-or-no question about the creature's current intentions, answered truthfully from what it is thinking right now."}, {"name": "Ghost", "prereq": "", "text": "while Phased, you may partially solidify one hand as a bonus action to make a single unarmed strike or manipulate an object without ending Phase; attacks against you lose the B/P/S resistance until the start of your next turn."}, {"name": "Many Faces", "prereq": "", "text": "Your shapeshifting is only skin-deep until you learn someone properly. If you observe a creature for at least 10 minutes — or read its surface thoughts — your Shapeshift can also mimic its voice, scent, and biometric details: retinal pattern, fingerprints, heartbeat cadence. Mundane scrutiny, guard dogs, and voice-print locks cannot tell you apart. Magical or supernatural detection still contests your technique DC, and you must have seen and heard the target to attempt this."}, {"name": "Fear of Flame", "prereq": "", "text": "when you succeed on a save against fire exposure or fear, you may use your reaction to scatter your density: until the end of your next turn you count as Light density for movement (squeeze through tiny gaps, +10 speed) without spending the bonus action to switch."}], "e128": [{"name": "Parademon General", "prereq": "", "text": "Apokolips provides. As an action for 3 CE, you may crack a brief Boom Tube and call a parademon hunting pack: three 1-HP parademons (AC 13, fly 40, bite 1d8+2) that last 1 minute and share one command as a bonus action. They are cowardly — if the whole pack dies, you cannot call another until you finish a short rest. Their minds are too broken to carry messages or leave the battle."}, {"name": "Stone God", "prereq": "", "text": "while your Avatar is active, your Omega Beam may originate from any point within 15 ft of you that you can see."}, {"name": "Equation Fragment", "prereq": "", "text": "You have glimpsed a fragment of the Anti-Life Equation, and it shows in your voice. You have advantage on Charisma (Intimidation) checks against creatures Frightened of you, and when you successfully intimidate such a creature it also cannot willingly move away from you until the end of its next turn — despair roots it in place. This is a fragment, not the Equation; it compels dread, never action."}, {"name": "There Is No Escape", "prereq": "", "text": "after a missed Omega Beam, you may use your bonus action on your next turn to redirect the still-burning beam at the same target with a new attack roll, without spending CE again."}, {"name": "Kneel", "prereq": "", "text": "when a hostile kneels, surrenders, or drops to 0 HP from your actions, you may use your reaction to demand fealty: one other hostile within 30 ft that sees it makes a Wisdom save or is Frightened of you until the end of your next turn."}, {"name": "Final Crisis", "prereq": "", "text": "once per long rest, when you use Omega Sanction you may open it as a doorway instead of a prison: you or one willing creature within 30 ft may step through as a bonus action, emerging within 60 ft of the target when it returns."}], "e129": [{"name": "Mental Fortress", "prereq": "", "text": "when you succeed on an Intelligence or Wisdom save, you may spend 1 Thought as a reaction to reflect the probe: learn the surface thought of the creature that targeted you, as Telepath with no save."}, {"name": "False Memory", "prereq": "", "text": "An illusion built from the victim's own mind is almost real. When you create an illusion — such as Perfect Illusion or Illusory Double — to deceive a creature whose surface thoughts you have read within the last minute, you have advantage on the technique contest or save against it, and it has disadvantage on its first Investigation check to see through the illusion, which wears the shape of something it already believes. This advantage does not stack with other advantage on the same roll."}, {"name": "Architect of Thought", "prereq": "", "text": "when you spend Thought on a feature, you may set it as a contingency: the effect waits up to 1 minute for a trigger you name, then resolves. You can maintain one contingency at a time."}, {"name": "Unraveler", "prereq": "", "text": "your Unsummon can target a persistent magical effect or Focus-maintained feature within 60 ft instead of a summon or construct; on a won contest it is suppressed until the end of its controller's next turn."}], "e130": [{"name": "Gravecrawler", "prereq": "", "text": "One of your dead refuses to stay down. Choose one Zombie under your control as your Gravecrawler: the first time it is destroyed each combat, it rises again at the start of your next turn with 1 HP, dragging itself from its own corpse. It keeps its position and your commands but loses any elite upgrades. You can maintain only one Gravecrawler at a time; you may choose another during a short rest."}, {"name": "Cruel Bargain", "prereq": "", "text": "when you sacrifice a summon with Dark Bargain, you may detonate its corpse instead of regaining CE or temp HP: creatures within 10 ft make a Dexterity save, taking 2d8 necrotic on a failure."}, {"name": "Necromancer's Command", "prereq": "", "text": "you may issue commands to your undead telepathically within 120 ft, and command one undead to use the Help action or make a Strength (Athletics) check as your bonus action."}, {"name": "Liliana's Triumph", "prereq": "", "text": "when one of your undead is destroyed, you may use your reaction to harvest its final moment: record a Corpse card from its remains, as if a meaningful creature had died."}], "e131": [{"name": "Young Pyromancer", "prereq": "", "text": "Your big magic sheds sparks that live. The first time each combat you cast a fire technique costing 3 or more CE, the excess flame coalesces into a 1-HP fire elemental token (AC 13, fly 30, touch 1d6 fire) that lasts 1 minute and acts on your initiative under your bonus-action command. It cannot leave a 30-foot radius around you — it is a spark, not a summon — and it winks out if you go a full round without dealing fire damage."}, {"name": "Shared Flame", "prereq": "", "text": "as a bonus action, you can share your Living Flame with a willing creature: the next weapon attack it makes before the end of your next turn deals an extra 1d8 fire damage."}, {"name": "Reckless Spark", "prereq": "", "text": "Pain is fuel. When you roll fire damage for one of your techniques, you may take damage equal to your proficiency bonus — this cannot be reduced or redirected — to reroll any number of the dice and keep the new results. You must accept the second roll. If this damage drops you to 0 HP, the reroll still resolves; Chandra's spark does not care what it burns, including her."}, {"name": "Can't Be Extinguished", "prereq": "", "text": "once per long rest, when you take damage while Ember is 5+, use your reaction to erupt: the attacker takes PBd8 fire, Dexterity save for half, and you gain 1 Ember."}], "e132": [{"name": "Lotus Cobra", "prereq": "", "text": "when you attune a new Land, you may read its memory: learn what creatures have crossed it within the last hour."}, {"name": "Elvish Guidance", "prereq": "", "text": "as a bonus action, one ally standing on your Land may move up to 10 ft without provoking opportunity attacks."}, {"name": "Living Terrain", "prereq": "", "text": "as a bonus action, you can coax your Land to shelter one willing creature standing on it: ranged attacks against that creature have disadvantage until it leaves the Land or the start of your next turn."}, {"name": "Nature's Claim", "prereq": "", "text": "structures damaged by your land effects become unstable: the ground in a 15-ft radius around them is difficult terrain until repaired."}], "e133": [{"name": "Mage of Zhalfir", "prereq": "", "text": "you cannot be surprised, and once per short rest you may swap your initiative result with one willing ally after initiative is rolled."}, {"name": "Momentary Blink", "prereq": "", "text": "as a bonus action, you can phase only your senses for an instant: see and hear through up to 10 ft of solid obstruction until the end of your turn."}, {"name": "Untap", "prereq": "", "text": "when a delayed effect you created resolves, you may use your reaction to echo its timing: one willing creature within 30 ft may immediately use its reaction to move up to half its speed."}, {"name": "No, Not Yet", "prereq": "", "text": "you can lend your Delay to others: as a reaction when an ally within 60 ft is targeted by a 1-action technique, you may contest it with Delay on their behalf (normal cost)."}], "e134": [{"name": "Cruel Intellect", "prereq": "", "text": "when you deal psychic damage to a creature, you may spend 1 Supremacy as a bonus action to sift the pain: learn one of the target's currently available named options."}, {"name": "Dragon's Hoard", "prereq": "", "text": "when your Spellbreaker halves a technique's damage, you may capture the suppressed half: as a bonus action within 1 minute, release it as a 15-ft cone dealing the captured dice as force damage (Dexterity save halves)."}, {"name": "Schemer", "prereq": "", "text": "Your Mind Shatter does more than wound — it reads. When you deal psychic damage to a creature with Mind Shatter, you skim its surface thoughts in the same instant: for the next 10 minutes you have advantage on Charisma (Deception) and Charisma (Intimidation) checks against that creature, and you learn one fear or desire it holds. This is a psychic echo, not ongoing telepathy, and it fades if you use it against another creature."}, {"name": "The Ravager", "prereq": "", "text": "your breath can be exhaled as a lingering miasma instead of a cone: a 20-ft-radius cloud lasting until the start of your next turn; creatures entering or starting their turn inside make the save, taking half damage on a success."}, {"name": "Planeswalker Spark", "prereq": "", "text": "when you teleport in combat, you may arrive striking: make one melee attack against a creature within reach of your destination as part of the same action."}, {"name": "Bolas's Citadel", "prereq": "", "text": "while below half HP, your stolen magic strains to be free: once per round, when you use a stored Echo, you may have it also target one additional creature within 30 ft of the original target at half dice."}], "e135": [{"name": "Walking Ballista", "prereq": "", "text": "You can animate with purpose. When you use Animate Artifact on an object with a ranged function or shape — bow, crossbow, cannon, sling, or similar — it becomes a Walking Ballista: its attack becomes a 60-foot ranged attack dealing 2d8 force, but it cannot make melee attacks and its HP is reduced by 5 for the delicate clockwork. You choose this configuration when you animate it; changing it requires re-animating."}, {"name": "Voltaic Key", "prereq": "", "text": "You carry a voltaic key — a silver wand of command for your machines. Once per round on your turn, you may move one animated Artifact you control up to 10 feet; this costs no action and does not consume your command. The key's pull is gentle: it cannot lift an Artifact off the ground, move it through a barrier, or drag it out of a grapple."}, {"name": "Darksteel", "prereq": "", "text": "as a bonus action, one animated Artifact becomes immobile until the start of your next turn; while immobile it grants half cover to creatures behind it."}, {"name": "Urza's Legacy", "prereq": "", "text": "when you use Creator's Touch, you may grant a temporary modification instead of healing: +10 ft range, one damage resistance, or advantage on one save type, lasting until your next long rest."}], "e136": [{"name": "Vampiric Link", "prereq": "", "text": "Your thirst is efficient; nothing is wasted. Whenever one of your vampire features would heal you above your maximum HP, the excess becomes temporary HP instead, up to a maximum of 5 + your level. This stolen-blood shield lasts 1 minute and visibly darkens your veins, and it does not stack with itself — recalculate the total each time."}, {"name": "Blood Artist", "prereq": "", "text": "Every death near you is a vintage. Once per round, when a creature within 30 feet of you dies — including one of your own summons — you may use your reaction to harvest its final pulse, gaining 1 Blood. This works on any death you witness, friend or foe; Sorin does not discriminate. You cannot gain Blood twice from the same death."}, {"name": "Ancient Grudge", "prereq": "", "text": "when a creature damages you, you may use your reaction to taste its blood from afar: learn its current HP total and whether it is below half."}, {"name": "Sanguine Bond", "prereq": "", "text": "You forge a sanguine bond with a chosen enemy: as a bonus action for 1 Blood, mark one creature you can see within 60 feet until the end of your next turn. The first time each turn you heal yourself while the mark persists, the marked creature takes necrotic damage equal to your proficiency bonus — your wounds close and theirs open in sympathy. The bond breaks early if the target receives magical healing from another source; foreign blood muddies the link."}], "e137": [{"name": "Dream Eater", "prereq": "", "text": "when your Nightmare damages a creature with 3 Fear Marks, you may remove all its Marks to grant the Nightmare +2d8 psychic on its attacks for 1 minute."}, {"name": "Faceless Fear", "prereq": "", "text": "Your Blueprint is never what it was a moment ago. Your summoned Nightmare Shikigami can alter its appearance freely as a bonus action — face, voice, stature — becoming anyone the marked creature fears or trusts, without changing its statistics. A creature that sees through the disguise (Investigation vs. your technique DC) is immune to this trick for 24 hours, but the fear remains: it keeps its Fear Marks. This is presentation, not transformation — claws remain claws."}, {"name": "Mill the Mind", "prereq": "", "text": "when a creature reaches 3 Fear Marks, you may immediately use Exile Thought against it as a reaction without spending CE. Once per round."}, {"name": "Night Terror", "prereq": "", "text": "when a creature with at least 1 Fear Mark moves, your Nightmare may move up to its speed as a reaction to follow it. Once per round."}], "e138": [{"name": "Pack Bond", "prereq": "", "text": "when you command your beasts, you may have two of them combine attacks on one target: make a single attack roll with advantage, dealing both beasts' damage on a hit."}, {"name": "Primal Hunter", "prereq": "", "text": "Your beasts do not hunt with eyes alone. A creature marked by your Hunter's Mark cannot benefit from invisibility, obscurement, or being Hidden against your beasts — scent, sound, and the tremor of its steps betray it. Your beasts have advantage on Wisdom (Perception) checks to locate the marked target, and it cannot surprise your pack while the mark persists. The mark still ends after one hour."}, {"name": "Trample", "prereq": "", "text": "A charging beast is a siege engine. When one of your beasts with the Charge trait moves at least 20 feet straight toward a creature and hits it with a melee attack, the target must succeed on a Strength save against your technique DC or be pushed 10 feet directly away from the beast. The beast may continue its movement after the push if it has speed remaining."}, {"name": "Unnatural Predation", "prereq": "", "text": "reaction command beast to attack enemy that harms ally once/short rest."}], "e139": [{"name": "Mox Engineer", "prereq": "", "text": "When one of your constructs, Thopters, or Blueprint devices is destroyed, you can use your reaction to salvage its wreckage: it makes one final attack or activation at its current position before collapsing."}, {"name": "Academy Rector", "prereq": "", "text": "You can open your Tolarian Academy workshop to allies: during a short rest, one willing ally can attune to a single prepared Blueprint device and use it once before your next long rest."}, {"name": "Master Transmuter", "prereq": "", "text": "As an action for 2 CE, you can transmute one prepared Blueprint into another you know, rebuilding the device in the field. The new device must serve a similar function (a sensor array can become a grapnel, not a Titan Engine), and a burned Blueprint cannot be transmuted."}, {"name": "Blind Seer", "prereq": "", "text": "Your hands read machines the way scholars read books. By touching a cursed tool and concentrating for 1 minute, you learn its name, its activated properties, its command words, and whether it is trapped or cursed — as the identify spell, but only for crafted objects and devices. This reveals function, not history; it will not tell you who made it or why. True artifacts and legendary tools resist: from such an item you learn only one property of your choice."}, {"name": "Mishra's Rival", "prereq": "", "text": "Your Titan Engine can mount one of your other Blueprints as a hardpoint: while the Engine is active, one prepared device (beam, shield, or sensor) is integrated into it and can be used as a bonus action on your turn."}, {"name": "The Brothers' War", "prereq": "", "text": "Your Titan Engine can carry your smaller machines into battle: up to four Thopters or one drone can dock with the Engine. While docked they cannot be targeted separately, and the Engine can deploy them as a bonus action."}], "e140": [{"name": "Toxic", "prereq": "", "text": "Your oil hangs in the air around you: once you reach Oil 5, you exude a miasma. A creature that starts its turn within 5 feet of you must make a Constitution save or gain 1 Infection (maximum 3)."}, {"name": "Viral Drake", "prereq": "", "text": "Your Infection spreads like a virus: when you Proliferate, choose one creature bearing your Infection. One creature within 10 feet of it must make a Constitution save or gain 1 Infection as the oil leaps hosts."}, {"name": "Steel Thane", "prereq": "", "text": "Your compleated plating can lock rigid: as a reaction when you take bludgeoning, piercing, or slashing damage, you gain resistance to that instance of damage, but your speed becomes 0 until the start of your next turn as the plating seizes."}, {"name": "Gitaxian Probe", "prereq": "", "text": "You extend a hair-thin probe of glistening oil toward one creature you can see within 60 feet: as a bonus action for 1 CE, you learn its damage resistances, immunities, and vulnerabilities, plus how hurt it is — unharmed, bloodied, or critical. The probe is near-invisible (Wisdom (Perception) vs. your technique DC to notice) and leaves no Infection; it is observation, not corruption. Once you have probed a creature, your Adapt feature may copy its resistance profile even if you have not yet taken that damage type."}], "e141": [{"name": "Pathrazer", "prereq": "", "text": "Your Void Limb phases through obstructions: its attacks ignore half and three-quarters cover, and you can strike a creature through a wall or barrier within your reach. The barrier takes the damage first, and any excess carries through to the creature."}, {"name": "Brood Lineage", "prereq": "", "text": "Your brood feeds on its own dissolution: when one of your Eldrazi Scions is sacrificed or destroyed, you gain 1 Void, or one surviving Scion deals an extra 1d8 damage on its next attack."}, {"name": "Reality Smasher", "prereq": "", "text": "At Void 6+, your warped mass barrels through the world: you can move through difficult terrain without penalty and smash through nonmagical barriers and walls, leaving a 5-foot breach in your wake."}, {"name": "Ulamog's Hunger", "prereq": "", "text": "Reality Hunger devours what it unmakes: if its sphere destroys a summon, construct, or barrier, you regain 2 CE and 1 Void."}, {"name": "Kozilek's Distortion", "prereq": "", "text": "You can twist a hostile illusion back on its caster: as a reaction for 1 Void when you succeed on a save against an illusion, the caster must succeed on an Intelligence save or suffer the illusion's effect as if they were its target."}, {"name": "Emrakul's Whisper", "prereq": "", "text": "Once per long rest, when a creature fails a save against one of your technique features, you can whisper through the Blind Eternities: it is charmed by you until the end of its next turn, and you can dictate one action it takes on its next turn."}], "e142": [{"name": "Gemhide", "prereq": "", "text": "A sliver's gemhide is condensed mana. As a bonus action, you may sacrifice one of your summoned Slivers within 30 feet: it dissolves into component mana and you regain 1 CE. You cannot sacrifice the Sliver Queen this way — her hide is load-bearing. A sacrificed sliver cannot be re-summoned until your next turn."}, {"name": "Hibernation", "prereq": "", "text": "When your brood is caught in an area effect, instinct takes over. As a reaction when one or more of your Slivers would take damage from an area effect, you may dismiss any number of them into hibernation: they vanish into the hive-mind's dormant state, take half damage from the effect, and return at the start of your next turn in their previous spaces (or the nearest free space). Slivers reduced to 0 HP by the halved damage do not return — hibernation cannot save the already dead. Dormant slivers cannot act or be targeted."}, {"name": "Crystalline", "prereq": "", "text": "Your Slivers' refractive hides turn blades aside: as a reaction when a Sliver is hit by an attack, another Sliver within 5 feet can interpose itself, becoming the target instead."}, {"name": "Necrotic", "prereq": "", "text": "A dying sliver's final act is spite. When one of your Slivers is destroyed, one hostile creature adjacent to it takes 1d8 necrotic damage with no save, as rupturing ichor sprays outward. This is not an attack and cannot be redirected — it is simply what happens when sliver-flesh bursts. Slivers sacrificed cleanly, such as through Gemhide, do not burst; their mana is harvested before it can rupture."}], "e143": [{"name": "Mana Dork", "prereq": "", "text": "Once per short rest, you can grow a 1-HP mana dork for 1 minute: it holds one temporary Mastery rank of a color you choose, and any ally within 5 feet of it can spend that rank once as if it were their own rank-1 color feature."}, {"name": "Fetchland", "prereq": "", "text": "Your mana base is a landscape you can reshape. As an action once per short rest, you may redistribute one Mana Mastery point from one color to another — pulling the right 'land' from the deck, in the old parlance. The point must come from a color with at least 2 ranks, and the receiving color cannot exceed 3 ranks this way. Colors you have already spent from this turn are locked; you cannot fetch what is already cast."}, {"name": "Gold Spell", "prereq": "", "text": "Your guild repertoire runs deeper than most. You learn one additional two-color pair spell beyond the two you choose at rest, drawn from the same list — Azorius detention, Dimir mind theft, Rakdos sacrifice-flame, Gruul overrun, Selesnya mass ward, and the rest. This third pair is fixed, the guild you apprenticed in, while your other two remain re-choosable at each rest. It costs the same CE and obeys the same rank requirements as your other pair spells."}, {"name": "Command Tower", "prereq": "", "text": "Once per long rest, you can raise your Command Tower for 1 minute: during that time you can cast any color's rank-1 basics by spending 1 CE, regardless of your current Mastery distribution."}, {"name": "Progenitus Echo", "prereq": "", "text": "Once per long rest, as a reaction when you or an ally within 10 feet would take damage, you can echo Progenitus's immunity to harm: choose one damage type, and you and allies within 10 feet gain resistance to that type until the start of your next turn."}, {"name": "Door to Nothingness", "prereq": "", "text": "Once per long rest, while you have at least 1 rank in all five colors, you can open the Door as an action for 10 CE: one creature within 60 feet makes a Charisma save or is exiled to the void between colors until the end of your next turn, returning with 1 level of exhaustion."}], "e144": [{"name": "Museum-Grade Repair", "prereq": "", "text": "Your golden seams hold stronger than the original: when you fully repair an object, construct, or cursed tool, you can lace the break with gold. The next time it would take damage, it takes none instead, once per object."}, {"name": "Beautiful Scar", "prereq": "", "text": "A creature you Mend yourself (an ally’s self-seal with Seal the Seam does not count) gains advantage on its next saving throw before the end of your next turn. Once per creature per short rest."}, {"name": "Shatterpoint", "prereq": "", "text": "When a hostile creature reaches its maximum number of Fractures, you may immediately move 10 feet without provoking opportunity attacks. Your next attack against it before the end of the turn has advantage."}], "e145": [{"name": "Foundation First", "prereq": "", "text": "You survey foundations before the first blow: if you spend 10 minutes studying a location, you can designate up to PB willing creatures there as Supports the instant initiative is rolled within the next 24 hours, without using an action."}, {"name": "Shock Absorber", "prereq": "", "text": "When you take damage redirected through Weight Distribution, you can Discharge the shock as part of the same reaction: one creature within 15 feet makes a Dexterity save or takes that damage as thunder and is pushed 10 feet away from you. Once per round."}, {"name": "Counterweight", "prereq": "", "text": "When you push a creature with Discharge, you may move the same distance in the opposite direction without provoking opportunity attacks."}], "e146": [{"name": "Sailor’s Hands", "prereq": "", "text": "You can splice your cords through existing Knots: when you tie a Knot, you may route it through another creature or object already bearing one of your Knots, extending your tying range to 60 feet for that Knot and ignoring cover between the relay and the target."}, {"name": "Quick Release", "prereq": "", "text": "When one of your Knots ends, move up to 5 feet without provoking opportunity attacks. Once per turn."}, {"name": "Executioner’s Knot", "prereq": "", "text": "As an action for 3 CE, you can tie a hangman's noose around a creature bearing 3+ of your Knots within 30 feet: it makes a Constitution save or is restrained until the end of your next turn, unable to speak or use verbal components while the noose holds."}], "e147": [{"name": "Seismograph", "prereq": "", "text": "You can read the earth's complaints: as an action, take a seismic reading. You learn how many creatures within 60 feet are touching the ground, and whether any Huge or larger creature is moving within 300 feet."}, {"name": "Hairline Crack", "prereq": "", "text": "When you roll initiative, place one Fault on a visible surface or creature that has already taken damage, no action required."}, {"name": "Cascade Failure", "prereq": "", "text": "After a creature bearing your Fault drops to 0 HP, one Fault within 30 feet immediately gains 2 Strain."}], "e148": [{"name": "Joseki Study", "prereq": "", "text": "You know the classical shapes: when you place a Stone adjacent to at least two of your other Stones, you may immediately move one deployed Stone up to 10 feet across a surface, as if using Sente."}, {"name": "Sacrifice Play", "prereq": "", "text": "Reaction when one of your Stones would be destroyed: detonate it. Creatures within 5 feet make a Dexterity save or take 2 Influence Dice force damage."}, {"name": "Reading Ahead", "prereq": "", "text": "At the start of combat, after initiative is rolled, place one Stone within 10 feet of yourself for free."}], "e149": [{"name": "Old Growth", "prereq": "", "text": "After a long rest, choose one of your Nodes to become old growth: it becomes Large with double HP and counts as two Connected Nodes for adjacency and teleportation, but it can never be converted into a Bloom."}, {"name": "Medicinal Culture", "prereq": "", "text": "You cultivate a healing strain: as an action for 1 Nutrient, graft a poultice onto a willing creature within 10 feet of a Node. The poultice persists until the bearer actually takes damage — it does not expire after 1 minute, and if the bearer phases out of a blow (such as through Distributed Organism) and takes no damage, the poultice remains, ready for the hit that actually lands. When that happens, the poultice bursts and heals it for 2 Spore Dice."}, {"name": "Cordyceps Reflex", "prereq": "", "text": "When a hostile creature within 10 feet of a Node falls prone, grappled, or restrained, gain 1 Nutrient. Once per round."}], "e150": [{"name": "Archivist’s Eye", "prereq": "", "text": "You can read an object's revisions: by touching an object for 1 minute, you learn whether it has been magically altered since you last touched it, and you gain advantage on checks to discern the alteration's nature."}, {"name": "Margin Walker", "prereq": "", "text": "You can linger in the margin between records: when you use Position Note on yourself, you can delay your return until the start of your next turn. While in the margin you cannot be targeted or act; you then return as a free action."}, {"name": "Errata", "prereq": "", "text": "When a creature succeeds on a save against Position Note or Redaction, it still subtracts one Revision Die from its speed until the end of the turn."}], "e151": [{"name": "Emergency Lane", "prereq": "", "text": "As a bonus action, declare one of your Lanes an emergency lane until the start of your next turn: willing creatures traveling along it gain 10 feet of speed, and the first hostile creature each turn that enters it must make a Strength save or be pushed 10 feet along the lane's direction."}, {"name": "Traffic Camera", "prereq": "", "text": "You know the current speed and number of Citations of every creature standing in one of your Lanes."}, {"name": "Repeat Offender", "prereq": "", "text": "When a creature reaches 3 Citations, your attacks against it ignore half cover until its Citations are spent."}], "e152": [{"name": "Perfumer’s Case", "prereq": "", "text": "You can decant a formula into a thrown vial: as an action, throw one prepared bottle up to 30 feet. It shatters on impact, applying its effect in a 10-foot radius (single-target formulas allow a Dexterity save for half). A thrown Courage Accord is a splash of fortitude: each creature in the radius that fails the Dexterity save gains half the Veil’s temporary HP (rounded down); every creature’s Scent Veil still blooms when depleted."}, {"name": "Cold Extraction", "prereq": "", "text": "You can gather Hunter’s Trace from a scene up to 24 hours old if physical residue remains."}, {"name": "Acquired Taste", "prereq": "", "text": "A creature that fails its save against one of your formulas develops a craving for it: for the next hour, you can use a bonus action and 1 CE to release a trace of that scent. The craving creature must make a Wisdom save or use its reaction to move up to half its speed toward you by the safest route."}], "e153": [{"name": "Organized Shelving", "prereq": "", "text": "Your archive is cross-indexed by need: once per short rest, when you or an ally within 30 feet needs a mundane item (rope, tools, rations, a healer's kit), you can produce it from the archive immediately without spending a Claim Ticket, provided it fits your size limit."}, {"name": "No Receipt Needed", "prereq": "", "text": "When you successfully disarm a creature, you may Archive the dropped eligible object immediately without using your reaction."}, {"name": "Premium Loaner", "prereq": "", "text": "Choose Weapon, Barricade, or Restraint after each long rest: your premium loaner is presentable enough to lend. An ally can wield it as if you had created it for them, and it persists for 1 hour even if you fall unconscious."}], "e154": [{"name": "Blink Hunter", "prereq": "Blind Spot", "text": "When a creature that is currently Observing you spends or loses its reaction for any other reason, its Observation immediately ends. Once per round this may trigger Blink Reflex."}, {"name": "Concrete Idol", "prereq": "Blind Spot, level 3", "text": "If you willingly move 0 feet on your turn, you may use a reaction before your next turn to reduce one damage instance by 5 × PB + CE modifier."}, {"name": "No Peripheral Vision", "prereq": "Blind Spot, level 6", "text": "If exactly one Observer can see you, you may attempt Blind Spot Step by paying +2 CE. That Observer makes a Wisdom save; on failure it experiences a micro-blink and ceases Observing before the Step resolves."}, {"name": "Neck-Line Anatomy", "prereq": "Blind Spot, level 11", "text": "Once per short rest when Snap Strike hits and the target fails its Constitution save by 5 or more, it is stunned until the end of your next turn instead of the normal failed-save result."}], "e155": [{"name": "Grief-Fueled Momentum", "prereq": "Shamebound Pursuit", "text": "Once per round when your Quarry damages you, gain 1 Fury after that damage resolves."}, {"name": "Unseen Photograph", "prereq": "Four Pixels", "text": "Your cursed face imprints may be as small as a four-pixel detail. A creature must actually perceive the detail to become a Witness; merely possessing the image is not enough."}, {"name": "No Rest Until Silence", "prereq": "Shamebound Pursuit, level 6", "text": "When your Quarry drops to 0 HP, retain up to half your current Fury until the end of your next turn. If you choose another Witness as Quarry before then, transfer that Fury."}, {"name": "Inhuman Acceleration", "prereq": "Shamebound Pursuit, level 11", "text": "Once per short rest, when you start your turn at least 60 feet from the Quarry, you may Dash without an action and your movement that turn may cross liquid surfaces and vertical walls."}], "e156": [{"name": "House Call", "prereq": "Pestilence Doctrine", "text": "Clinical Touch and The Cure gain 15-foot reach through a spectral gloved hand. This does not let you pass through total cover."}, {"name": "Second Opinion", "prereq": "Clinical Examination", "text": "Your examinations render deeper diagnoses: when you use Clinical Examination on a creature, choose one — learn its current hit points as a number, or learn one of its damage resistances or vulnerabilities."}, {"name": "Field Surgeon", "prereq": "Crude Surgery", "text": "Outside combat, Crude Surgery takes 1 minute instead of 10. In combat, a corpse you personally reduced to 0 HP may be made a Patient as a full-turn action for 4 CE even before level 11."}, {"name": "Humoral Imbalance", "prereq": "Pestilence Doctrine, level 11", "text": "A creature with 4+ Symptoms also has its speed reduced by 10 feet and cannot take reactions after it fails a Constitution save against your technique until the start of its next turn."}], "e157": [{"name": "Black Mucus", "prereq": "Corrosive Threshold", "text": "A Surface Mark creates a 5-foot patch of difficult terrain for enemies. A creature that falls prone in it cannot stand without spending an additional 5 feet of movement."}, {"name": "Predator Beneath", "prereq": "Predatory Emergence", "text": "After Threshold Walk, you may remain partially submerged until the start of your next turn. You have half cover but your speed is 0 and you cannot make opportunity attacks while submerged."}, {"name": "Liquefying Grip", "prereq": "Corrosive Touch, level 6", "text": "When you apply the third Corrosion Mark to a creature, it cannot take reactions until the end of its next turn and you may attempt to grapple it as part of the same attack."}, {"name": "Recall Protocol", "prereq": "Corrosive Threshold, level 11", "text": "Once per short rest when damage would reduce you below one-quarter HP, use your reaction and 2 CE to teleport to any Surface Mark within 120 feet after the damage resolves."}], "e158": [{"name": "Perfect Voiceprint", "prereq": "With Many Voices", "text": "Your mimicry extends beyond speech: you can reproduce any nonverbal sound made by a creature whose voice you have archived — breathing, crying, footsteps — and layer two archived sounds at once, a voice calling from one direction and footsteps from another."}, {"name": "Dark Hunter", "prereq": "Troglobitic Senses", "text": "Your voice hunts ahead of you: as a bonus action for 1 CE, project a Voiceprint to a point within 60 feet. Until the start of your next turn you can hear through that point as if you were there, and your blindsight extends 30 feet from it."}, {"name": "No New Memories", "prereq": "Amnestic Breath, level 6", "text": "A creature that fails its save against your Amnestic Breath also loses its short-term memory of the last minute: for the next hour it cannot describe you, recall the room's layout, or remember orders received in that time."}, {"name": "Pack Echo", "prereq": "With Many Voices, level 11", "text": "When an ally within 30 feet attacks a creature with 2+ Lost Moments, use your reaction and 1 CE to make the target hear the ally from the wrong direction. That attack gains advantage; this does not make you hidden."}], "e159": [{"name": "Lent Loathing", "prereq": "Adaptive Hatred", "text": "Once per round, when you take damage from a Threat Tag for which you have an installed Adaptation, you may use your reaction and 1 CE to lend that Adaptation’s benefit to one ally you can see until the start of your next turn: resistance for a damage Tag, or advantage on saves against a condition Tag. Your own Adaptation is unaffected."}, {"name": "Hostile Evolution", "prereq": "Reactive Morphology", "text": "Once per turn, after a creature damages you with a Tag for which you have an installed Adaptation, you may use your reaction and 1 CE to make one unarmed strike against that creature. On a hit it takes an additional Adaptation Die of damage of the Tag’s damage type, or force damage if the Tag is a condition or environmental hazard."}, {"name": "Keter Genome", "prereq": "Adaptive Hatred, level 6", "text": "Once per round, when you take damage from a Threat Tag for which you hold at least 1 Data but have no installed Adaptation, you may use your reaction and 1 CE to immediately replace one installed Adaptation with an Adaptation to that Tag without spending Data."}, {"name": "Consume and Rebuild", "prereq": "Adaptive Hatred, level 11", "text": "During a short rest you may consume or incorporate a meaningful quantity of organic or inorganic matter. Regain PB Adaptation Dice HP and gain 1 Data for one environmental or material Threat Tag that the consumed matter reasonably demonstrates; GM adjudicates the Tag."}], "e160": [{"name": "Honeyed Words", "prereq": "The Possessive Mask", "text": "Once per turn when you succeed on Deception, Persuasion, or Intimidation against a creature currently at 0 Temptation, you may spend 1 CE to give it 1 Temptation without using an action."}, {"name": "Black Ichor", "prereq": "Corrosive Secretion", "text": "When Corrosive Secretion corrodes an unattended surface, leave a 5-foot corrosive patch until the start of your next turn. A creature entering it for the first time on a turn has its speed halved until the start of your next turn, maximum once per turn."}, {"name": "Borrowed Aptitude", "prereq": "Host Transfer, level 6", "text": "When you enter a living Host, choose one skill in which that Host is proficient. You gain proficiency in it while possessing that body; if already proficient, you gain no additional expertise."}, {"name": "Never Without a Face", "prereq": "Host Transfer, level 11", "text": "During a short rest, designate one valid nonliving vessel — a corpse, mannequin, or statue you have prepared — within 1 mile as your contingency. The first time within the next 24 hours that a Host ejects you or reaches 0 Integrity, your consciousness transfers to the contingency vessel immediately without spending CE or an action, instead of returning to the Prime Host or falling free."}], "e161": [{"name": "Salvage Intake", "prereq": "Refining Clockworks", "text": "When a construct, vehicle, or unattended object is destroyed within 30 feet of your manifested Clockworks, you may use your reaction to feed the wreckage straight into the Intake, gaining Scrap as though you had used Rough on it for its size, without spending an action."}, {"name": "Restorative Refinement", "prereq": "Very Fine", "text": "When you activate Very Fine, you may choose restoration instead of rolling: rebuild one damaged or broken mundane object, or one non-Special-Grade cursed tool, placed in the Intake, restoring it to full function and clearing the broken condition. Pay the normal activation cost; no roll is made and no Risk is gained."}, {"name": "Decoupled Line", "prereq": "Portable Clockworks", "text": "When you manifest the Clockworks, you may place the Intake and Output frames up to 30 feet apart — both within 60 feet of you — instead of adjacent. Items fed into the Intake emerge refined from the Output normally."}, {"name": "Hot-Swap Tuning", "prereq": "Fine, level 6", "text": "As a bonus action, move one active Fine upgrade from an item you touch to another valid item you touch; the upgrade’s remaining duration continues on the new item. An item may still hold only one Fine upgrade."}], "e162": [{"name": "Flat-Pack Trap", "prereq": "Infinite Retail", "text": "When you use Flat-Pack Manifestation, you may target a prone creature within 30 feet instead of an unoccupied space, assembling the Merchandise around it. The target makes a Strength saving throw against your technique DC; on a failure it is restrained inside the furniture until it uses an action to break free against your technique DC. The Merchandise has its normal statistics and can be attacked."}, {"name": "Fire Exit Plan", "prereq": "Closing Shift", "text": "When a creature you can perceive manifests an Exit by succeeding on Search for an Exit, you may use your reaction to choose where that Exit appears: any unoccupied space within 30 feet of that creature, inside the Domain, instead of within 10 feet of it."}, {"name": "Night Watch", "prereq": "Settlement Founder, level 6", "text": "When Closed Hours begins, you may use your reaction to rouse one Settlement you can perceive. Until the next Store Phase, up to PB creatures inside it may make opportunity attacks against Staff that enter or leave the Settlement, and your Display Fixtures’ difficult terrain does not impede them."}, {"name": "Exchange & Returns", "prereq": "Restocking Cycle, level 11", "text": "When Open Hours begins, instead of restoring Merchandise or removing Remains with Restocking Cycle, choose one Settlement that survived the previous Closed Hours. Every willing creature inside it may immediately spend one Hit Die and regain that much HP without using an action."}], "e163": [{"name": "Bridgewatcher", "prereq": "", "text": "When initiative is rolled, choose one visible structure, vehicle, barrier, or terrain feature. You know whether it is currently stable, damaged, trapped, or likely to catastrophically fail within the next minute. If it fails during the encounter, gain 2 Omens."}, {"name": "Scarlet Afterimage", "prereq": "", "text": "When Eyes Before the Storm moves a creature, leave a red afterimage in its old space until the start of its next turn. The first hostile attack made through or into that space is made with disadvantage."}, {"name": "Bad Feeling", "prereq": "", "text": "Once per short rest, after the GM describes a location but before the party commits to entering it, spend 1 CE to ask whether an immediate physical or cursed threat is present within 300 feet. The answer is yes/no/unclear; it does not identify the threat."}, {"name": "Prophet of Impact", "prereq": "", "text": "Prerequisite: Disaster Clock. When a Clock reaches 3, you may spend 2 Omens to mark one 10-foot square you can see. If the marked creature enters that square before your next turn, it falls prone and cannot take reactions until the end of that movement."}], "e164": [{"name": "Eddy Reading", "prereq": "", "text": "While your Veil is active, you read the atmosphere eddying around bodies: you know the direction and distance of every creature inside the Veil that has at least 1 Exposure, even if you cannot see them."}, {"name": "Sickening Trail", "prereq": "", "text": "Spaces you leave during your turn remain Veiled until the start of your next turn. A creature can gain Exposure from only one of your Veil areas per turn."}, {"name": "Static Autopsy", "prereq": "", "text": "After observing a creature with Exposure 3+ for one round, learn whether its highest saving throw is Strength, Dexterity, Constitution, or mental (Int/Wis/Cha)."}, {"name": "Red Star Descent", "prereq": "", "text": "Prerequisite: Floating Apparition. When you descend at least 20 feet immediately before using Atmospheric Pulse, you may drive the Veil down with you: the Pulse affects only creatures within 10 feet of you, but creatures that fail the save gain 2 Exposure instead of 1."}], "e165": [{"name": "Roofline Hunter", "prereq": "", "text": "Climbing costs no extra movement and you may run across vertical surfaces during your turn if you end on a legal surface or remain flying."}, {"name": "Hellish Whinny", "prereq": "", "text": "When a creature fails its save against Devil’s Cry, its panic betrays it: for 1 minute you always know its direction and distance, and it cannot become hidden from you. This does not let you see it while invisible, but you know which space it occupies."}, {"name": "Near Miss", "prereq": "", "text": "When a creature misses you with an opportunity attack, gain 1 Pursuit, once per round. The hunt feeds on near misses."}, {"name": "Broken-Bridle Pursuit", "prereq": "", "text": "Prerequisite: Marked Quarry. When your Quarry imposes restrained, grappled, or prone on you, gain 2 Pursuit after the condition is applied."}], "e166": [{"name": "Polite Stranger", "prereq": "", "text": "You may deliver Offer through a phone, speaker, intercom, or other live two-way communication within 1 mile. The target must hear and voluntarily accept."}, {"name": "Take My Hand", "prereq": "", "text": "Add one Offer option: the target may stand from prone and move 10 feet toward you without provoking. If accepted, you may move 10 feet toward it as well."}, {"name": "Guest Right", "prereq": "", "text": "While inside a Threshold whose controller has invited you, you cannot be surprised, and you sense whenever a creature enters or leaves that Threshold."}, {"name": "The Eyes Are Wrong", "prereq": "", "text": "A creature that has granted you 2+ Open Doors has disadvantage on Insight checks against you and cannot benefit from being invisible against your technique senses."}], "e167": [{"name": "Tall Enough", "prereq": "", "text": "Your standing jump distance and height double, and you may step over Large or smaller creatures without treating their spaces as difficult terrain."}, {"name": "Walk Behind the Camera", "prereq": "", "text": "If you end your turn in dim light or darkness after moving 30+ feet, you may Hide without an action once per round."}, {"name": "Friendly Procession", "prereq": "", "text": "When an ally moves along your Procession Path, you may use your reaction to move up to 15 feet along the same path without provoking opportunity attacks, falling in step behind them."}, {"name": "Dropped Frame", "prereq": "", "text": "Prerequisite: Processional Echoes. When an attack misses you due to Echo disadvantage, gain 1 Step."}], "e168": [{"name": "Count Again", "prereq": "", "text": "When a creature fails an Insight check to identify you or a decoy, it is left doubting every face: it has disadvantage on its next attack roll before the end of its next turn."}, {"name": "Campfire Voice", "prereq": "", "text": "You can perfectly reproduce any voice heard for at least 1 minute, though this alone never grants a Headcount benefit."}, {"name": "Wrong Footprints", "prereq": "", "text": "As an action and 1 CE, create false tracks, scent, and mundane evidence for one Headcount creature across a 60-foot trail."}, {"name": "Seventh Shadow", "prereq": "", "text": "Prerequisite: There Were Six of Us. Your decoy may take the Help action once on your turn; doing so destroys it after the helped roll resolves."}], "e169": [{"name": "Livestock Sense", "prereq": "", "text": "You can determine whether a creature you can smell within 30 feet currently has CE and whether it is above or below half HP."}, {"name": "Spraying Wound", "prereq": "", "text": "Once per turn, when you score a critical hit with a piercing or slashing melee attack, you may mark a second creature within 5 feet of the target with a Feeding Wound without spending CE; it counts against your maximum active wounds."}, {"name": "Packless Hunter", "prereq": "", "text": "When no ally is within 15 feet of you, your solitude is a weapon: once per turn when you hit a wounded creature, you may drive it from the herd. It makes a Wisdom saving throw against your technique DC, becoming frightened of you until the end of your next turn on a failure."}, {"name": "Purging Molt", "prereq": "", "text": "As an action, regress one stage on the Metamorphosis track (minimum Gaunt Predator) to slough tainted flesh: end one poisoned condition or disease affecting you."}], "e170": [{"name": "Sand Listener", "prereq": "", "text": "As an action, press yourself to one of your Tremor Path segments and read its memory: learn the number, size categories, and direction of travel of creatures that crossed that segment in the last 10 minutes."}, {"name": "False Tremor", "prereq": "", "text": "As an action and 1 CE, create a fake Path signature within 60 feet that lasts 10 minutes and fools ordinary tremor detection."}, {"name": "Venom Static", "prereq": "", "text": "When one creature takes both acid and lightning damage from you in the same round, its nerves short-circuit: it cannot take reactions until the start of your next turn."}, {"name": "Buried Ambush", "prereq": "", "text": "If combat begins while you are underground in one of your existing Paths, you may spend 1 CE to Erupt against a creature within 10 feet of your position before the first round begins, resolving the attack before initiative order starts."}], "e171": [{"name": "Ambush Sign", "prereq": "", "text": "When you create a False Trail, you may designate one 10-foot segment of it as your ambush point. The first hostile creature to willingly enter that segment provokes an opportunity attack from you if you are hidden within 10 feet of it."}, {"name": "Tree Line", "prereq": "", "text": "You may climb natural surfaces at full speed and gain half cover while at least 10 feet above the ground among dense branches/foliage."}, {"name": "No Clear Photo", "prereq": "", "text": "A creature using a divination, camera, scope, or recording device to identify you must beat your CE DC with its relevant check if you have at least 1 Evidence."}, {"name": "Track the Tracker", "prereq": "", "text": "When a creature succeeds on tracking you and grants Evidence, learn its direction and approximate distance for 1 hour."}], "e172": [{"name": "Shiny Eyes", "prereq": "", "text": "The swarm sheds dim light 10 feet when you choose and can see invisible creatures within its space."}, {"name": "Roof Scratcher", "prereq": "", "text": "A creature starting its turn directly beneath the swarm on a ceiling makes Wisdom save or has disadvantage on its first attack that turn."}, {"name": "Tiny Thieves", "prereq": "", "text": "Grab may target a worn pouch, keyring, magazine, potion, phone, talisman, or similarly small accessible object, but never armor, an attuned item, or an object physically integrated into the target."}, {"name": "No Bodies Found", "prereq": "", "text": "When the swarm disperses, it leaves no corpse or permanent material — and it may complete one last delivery: it deposits one object it is holding in an unoccupied space within 60 feet of its position before vanishing."}], "e173": [{"name": "Snake Crown", "prereq": "", "text": "You gain blindsight 10 feet from the snakes’ senses and advantage on Perception based on vibration or scent."}, {"name": "Do Not Look Away", "prereq": "", "text": "When an Averting creature voluntarily moves away from you, use reaction and 1 CE to move 10 feet toward it."}, {"name": "Mirror-Bearer", "prereq": "", "text": "You can make one weapon, shield, or carried object you touch count as a polished reflection for Bronze Reflection."}, {"name": "Cracking Stone", "prereq": "", "text": "Prerequisite: Calcification 3. Once per round, when a creature with Calcification 3+ is hit by an attack you did not make, you may use your reaction to shatter its calcifying shell: it sheds 1 Calcification and falls prone. This may spare an ally from petrification — or deny an enemy its stony armor — without spending your own attack."}], "e174": [{"name": "Swamp-Born", "prereq": "", "text": "You gain a swim speed equal to your walking speed and can hold your breath for 1 hour. While fully submerged, fire and radiant damage lose their cauterizing edge: a Neck Wound marked on a turn you end underwater cannot be cauterized until after your next turn begins, giving the regrowth time to root. As a bonus action while submerged, you may spend 1 CE to exhale venom-tinged murk into a 15-foot radius around you, heavily obscuring it until the start of your next turn."}, {"name": "Guarding Heads", "prereq": "", "text": "When an adjacent ally is hit, spend 1 Head Die and reaction to reduce its damage by the die + CON modifier."}, {"name": "Venom Reservoir", "prereq": "", "text": "A creature poisoned by your Hydra Venom also has its speed reduced by 10 feet. Your necks track the venom's spread through the victim's body: your Bite's reach extends by 5 feet against a poisoned creature, and when it tries to move away from you, you may spend 1 CE as a reaction to force a Strength saving throw — on a failure its movement ends immediately. The speed penalty and the leash both end when the poison ends."}, {"name": "Heracles Problem", "prereq": "", "text": "When an enemy deals fire/radiant damage solely to cauterize a pending Neck Wound, gain one Head Die of temporary HP after that damage resolves."}], "e175": [{"name": "Weigh the Dead", "prereq": "", "text": "As an action and 2 CE, you may Weigh the heart of a corpse dead no more than 1 hour; it makes no save. You learn one significant burden it knowingly accepted in life — a bargain, betrayal, or sacrifice — as the GM describes. This offers no Temptations and adds no Heart Weight."}, {"name": "Sweet Temptation", "prereq": "", "text": "Add Safety : when you or an ally within 30 feet would take damage from the Weighed creature, you may offer it Safety as a Temptation without spending an action (once per round). Accept: the damage is halved and it gains 1 Heart Weight. Refuse: the damage lands in full."}, {"name": "Borrow the Burden", "prereq": "", "text": "When an ally within 30 feet accepts a Temptation, you may take the Heart Weight instead of them once per round. Temptations accepted by the hostile Weighed creature (such as Safety) do not trigger this feat — it covers allies’ acceptances only."}, {"name": "Devour Excess", "prereq": "", "text": "When a 6-Weight creature spends 3+ CE, gain 1 temporary CE, maximum PB temporary CE, expiring after 1 minute. Temporary CE never raises your CE maximum."}], "e176": [{"name": "Iron Appetite", "prereq": "", "text": "While obeying Tyr’s Hand, healing you grant yourself through RCT is not prohibited, but costs +1 CE."}, {"name": "Moon-Eater", "prereq": "", "text": "When Moon Chain breaks, you may use your reaction to bite the backlash: the creature whose action triggered the break takes 5 psychic damage as the snapped chain lashes through its overspent cursed energy."}, {"name": "Slipped Leash", "prereq": "", "text": "When you succeed on a saving throw against a grapple, restraint, or forced-movement effect, you may use your reaction to move up to 10 feet without provoking opportunity attacks, slipping through the failed hold."}, {"name": "Unbroken Oath", "prereq": "", "text": "If you complete an encounter without breaking a prepared Bond, choose one of your prepared Bonds. The next time that Bond’s trigger occurs, you may keep it unbroken instead of breaking it; you gain no Ragnarök from the ignored trigger."}], "e177": [{"name": "Ocean Coil", "prereq": "", "text": "Segments may be placed on water and you gain swim speed equal walking speed."}, {"name": "Tail Around the Party", "prereq": "", "text": "Guard Rings grant allies advantage on saves against forced movement across their boundary."}, {"name": "Venom of the World", "prereq": "", "text": "Poison immunity treats your Coil poison as resistance; poison resistance still functions normally."}, {"name": "Closing Snap", "prereq": "", "text": "When a Segment you place completes a Ring, the circuit closes with a snap: one hostile creature of your choice inside the new Ring makes a Strength saving throw against your technique DC; on a failure it is pulled 10 feet toward the Ring’s center."}], "e178": [{"name": "Perfect Accent", "prereq": "", "text": "After listening to a language for 1 hour through a recorded Mask, you can reproduce its accent flawlessly but do not learn the language itself."}, {"name": "Dinner Guest", "prereq": "", "text": "While impersonating someone inside a place where that identity is expected, gain advantage on checks to avoid casual scrutiny until you behave obviously out of character."}, {"name": "Backward Hands", "prereq": "", "text": "Once per round, when you fail a Sleight of Hand or Deception check while masked, the Mask reads the room: you immediately learn which creatures that witnessed the check are suspicious of you."}, {"name": "Predator’s Memory", "prereq": "", "text": "You can store one additional purely social Memory Note per Mask: a public relationship, routine, title, or preference you personally observed. It grants no secret knowledge."}], "e179": [{"name": "Rain-Bringer", "prereq": "", "text": "As an action and 1 CE, create light rain in a 30-foot radius for 10 minutes; it extinguishes mundane flame and gives advantage on Survival to find water."}, {"name": "Jeweled Hood", "prereq": "", "text": "While at least one of your Coils is active, you sense the space around every Coil-bearing creature: you have blindsight to 10 feet centered on each creature bearing one of your Coils, and you cannot be surprised by a creature within that radius."}, {"name": "Constriction Expert", "prereq": "", "text": "When a creature bearing one of your Constrict Coils would be forcibly moved, you can use your reaction to spend that Coil and anchor it in place, negating the movement entirely."}, {"name": "Shared Skin", "prereq": "", "text": "As a bonus action, a willing creature bearing one of your Ward Coils can pass it to another willing creature within 30 feet; the Coil keeps its remaining duration."}], "e180": [{"name": "Fox Bridegroom", "prereq": "", "text": "Gain proficiency or expertise in Deception; harmless cosmetic shapechanging can alter hair, eyes, ears, tail, and clothing appearance at will."}, {"name": "Blue Foxfire", "prereq": "", "text": "You may kindle a foxfire wisp in the space of one of your Paper Foxes. The first creature that becomes lured by that wisp regards you as a trusted ally while lured, hearing an ally’s voice calling from the flame."}, {"name": "Clever Enough to Believe Yourself", "prereq": "", "text": "When you fail a save against being frightened or charmed, you may use your reaction and spend 1 CE to make one of your Paper Foxes within 30 feet believe the lie instead: the condition ends on you and the illusion is destroyed."}, {"name": "Thousand-Year Trick", "prereq": "", "text": "Prerequisite: level 11. The first time each round a creature identifies one of your illusions, you may treat that wasted inspection as fuel: it counts as a deception that wasted an action for the purpose of claiming your next lie."}], "e181": [{"name": "Bone Chime", "prereq": "", "text": "You can sense creatures below half HP within 30 feet if they have bones or a comparable internal structure."}, {"name": "Graveyard Architecture", "prereq": "", "text": "Torso of a Nation may anchor to terrain and counts as a structure for allies using cover or climbing."}, {"name": "Starving Maw", "prereq": "", "text": "When you would take starvation damage for ending your turn at Hunger cap, you may instead force one creature grappled by your Jaw to take that damage as necrotic, your manifested skeleton gnawing through its own hunger. The grapple continues."}, {"name": "Jaw of Famine", "prereq": "", "text": "As a bonus action while a creature is grappled by your Jaw, you may end the grapple to feed: gain 1 Hunger and temporary HP equal to 5."}], "e182": [{"name": "Zal’s Feather", "prereq": "", "text": "Once per long rest, when a creature within 30 feet would fall to 0 HP, consume any Feather to leave it at 1 HP instead. This cannot prevent instant death that does not reduce HP."}, {"name": "Scholar of Ages", "prereq": "", "text": "Gain proficiency or expertise in History or Medicine. A Skill Feather may be spent on either of those skills regardless of how it was created."}, {"name": "Carry the Young", "prereq": "", "text": "While flying, you may carry one willing creature of your size or smaller without reducing your speed."}, {"name": "Memory of Fire", "prereq": "", "text": "When a willing creature within 60 feet fails a save against fire, fear, or death effects, you may use your reaction and spend 1 CE to record the moment of survival: create one Resolve Feather immediately (once per round, still subject to your cap)."}], "e183": [{"name": "Polyphonic Horror", "prereq": "", "text": "When a creature fails saves against two different Typhon phenomena in one round, you may use your reaction and spend 1 Cataclysm to force it to make a Wisdom save against your CE DC; on a failure it is frightened of you until the end of its next turn, as the storm speaks with many throats."}, {"name": "Tireless Coils", "prereq": "", "text": "As a bonus action, you can drive your serpent limbs into the ground: until the start of your next turn you cannot move, but you cannot be moved against your will and you have advantage on Strength checks and saves to shove or grapple."}, {"name": "Volcanic Prison", "prereq": "", "text": "As an action while a creature is grappled by your Serpent Limbs, you may spend 2 Cataclysm to encase it in cooling magma: it must succeed on a Strength save against your CE DC or be restrained until the end of your next turn, taking 1 fire die at the start of each of its turns while restrained."}, {"name": "Last Challenge of Olympus (11+)", "prereq": "", "text": "When you drop to 0 HP, you may use your reaction to spend any amount of Cataclysm and erupt: each creature within 15 feet must make a Dexterity save against your CE DC, taking 1 fire, lightning, or thunder die per Cataclysm spent (your choice) on a failure, half on success. You then fall unconscious as normal."}], "e184": [{"name": "Ambidexterity Is Meaningless", "prereq": "", "text": "You can commit Hands to the Help action: each committed Hand aids a different creature you can see within 30 feet, granting the aid's benefit on the first attack roll or ability check that creature makes before the start of your next turn."}, {"name": "Jailor of Titans", "prereq": "", "text": "You can maintain two 20-foot spectral grapples at once, paying the normal Hand cost for each and making separate contested checks for each."}, {"name": "Catch the Sky", "prereq": "", "text": "defensive Hand reaction can protect against ranged technique attacks from 30 ft."}, {"name": "Briarean Barrage (11+)", "prereq": "", "text": "When you use Stone Barrage, you may instead fuse the Hands into one massive fist: make a single melee technique attack with 30-foot reach, dealing one Hand Die per Hand spent plus your CE modifier once; on a hit the target must succeed on a Strength save against your CE DC or be knocked prone."}], "e185": [{"name": "Appraiser's Eye", "prereq": "", "text": "As a bonus action, you may appraise one object you can see within 30 feet, learning its approximate value, whether it bears cursed energy, and whether it shows signs of a curse, binding, or forgery. If the object is eligible to become a Hoard Mark, you may immediately mark it with Covetous Scale as part of the same bonus action, still paying the 1 CE. Once per long rest, you may appraise a cursed tool worn or carried by a creature this way, reading its nature despite its keeper."}, {"name": "Jealous Wings", "prereq": "", "text": "While in Wyrm Shape, you may spend 2 Greed as a bonus action to unfurl jealous wings, gaining 30-foot flight until the end of your next turn."}, {"name": "No Thief Escapes", "prereq": "", "text": "Once per round when Dragon's Claim reveals a thief's direction, you may spend 1 CE as a bonus action to share the hunt: your allies perceive a glinting golden thread pointing at the thief until the start of your next turn, and each may use their reaction to move up to half their speed toward it."}, {"name": "Accursed Gold (11+)", "prereq": "", "text": "As a bonus action, you may spend 1 Greed to make one stolen Hoard Mark within your Claim's 1-hour window unbearably heavy: the carrier's speed is halved while it carries the mark, until it drops it."}], "e186": [{"name": "Burial Goods", "prereq": "", "text": "You may maintain a second, portable Grave Anchor — a sealed burial token weighing 5 lb — alongside your main Anchor, though only one Anchor projects your Grave Mound at a time; switching which Anchor projects the Mound costs a bonus action and 1 CE. A hostile creature that moves while carrying or touching the portable Anchor generates Restlessness for you as though it were moving inside your guarded space, rewarding the thief's greed. If the portable Anchor is destroyed, you take psychic damage equal to one Grave Die per Restlessness you hold, up to a number of dice equal to your PB."}, {"name": "Anchor's Pull", "prereq": "", "text": "When you hit a creature with an opportunity attack, you may spend 1 Restlessness to drag it 10 feet toward your Grave Anchor instead of dealing damage; a creature that enters your guarded space this way generates Restlessness as normal."}, {"name": "Corpse Weight", "prereq": "", "text": "count one size larger for carrying/grapple/forced movement while swollen."}, {"name": "Unquiet Dead (11+)", "prereq": "", "text": "When Too Angry to Die triggers, your rage infects the field: each hostile creature within 15 feet must succeed on a Wisdom save against your CE DC or be frightened of you until the end of your next turn."}], "e187": [{"name": "Winged Escort", "prereq": "", "text": "When you fly — under your own power or by Carry from the Field — you may carry one willing creature without any reduction to your flying speed. While carrying a creature this way, your Ride to the Fallen reaction move extends to 30 feet toward a Deed-holder, and the carried creature gains half cover against attacks made from below you. You cannot carry a creature larger than you or heavier than your carrying capacity."}, {"name": "Saga-Keeper", "prereq": "", "text": "You may record Deeds from your own dramatic moments — your critical hits, your brushes with death, your rescues — as though you were one of the allies you watch; these Deeds are stored under your name and spent normally."}, {"name": "Shieldmaiden", "prereq": "", "text": "When you use Ride to the Fallen, you may forgo the damage reduction to instead impose disadvantage on the triggering attack roll, decided before the roll is made — your interposition ruins the strike's line rather than absorbing it. If the attack still hits, you may still spend the creature's Deed after damage is rolled to reduce it by one die + your CE modifier, completing the same 20-foot reaction move. Against effects that call for a saving throw instead of an attack roll, you may grant the protected creature advantage on the save instead."}, {"name": "Last Seat in Valhalla (11+)", "prereq": "", "text": "When an ally fails a death save, you may spend one of their Deeds as a reaction to let them reroll it; they use the new result."}], "e188": [{"name": "Footprints Vanish", "prereq": "", "text": "You leave no tracks in snow, ice, or frost that a mundane tracker could follow, and you have advantage on Dexterity (Stealth) checks in cold terrain or inside your Snowfield. When you use Woman in the Storm to teleport between snow-obscured spaces, you arrive without sound: creatures relying on hearing have disadvantage on Wisdom (Perception) checks to notice your arrival until you take an action. While you stand motionless in falling snow or a blizzard, you are treated as invisible to creatures more than 30 feet away that lack magical sight."}, {"name": "Kiss of Winter", "prereq": "", "text": "As a bonus action for 1 CE, you can press a winter's kiss to a willing creature's brow: until the end of your next turn it ignores Frost accumulation and treats your Snowfield as normal terrain."}, {"name": "Snowblind", "prereq": "", "text": "When a creature reaches 2 Frost, you may use your reaction to blind it with driven snow until the end of its next turn unless it succeeds on a Constitution save against your CE DC."}, {"name": "First Flurry (6+)", "prereq": "", "text": "When you roll initiative, you may fling the battle's first chill: one creature you can see within 30 feet must succeed on a Constitution save against your CE DC or gain 1 Frost."}], "e189": [{"name": "Iron Skin", "prereq": "", "text": "While wearing the Blue Mask, when an ally within 10 feet takes physical damage you may use your reaction to interpose yourself: you take the damage instead, reduced by your Blue Mask's damage reduction."}, {"name": "Red Horn", "prereq": "", "text": "While wearing the Red Mask, if you move at least 15 feet straight toward a creature before hitting it with a melee attack, the target must succeed on a Strength save against your CE DC or be knocked prone."}, {"name": "Dread Laugh", "prereq": "", "text": "While wearing the Black Mask, you may use your bonus action to laugh: one creature within 30 feet that can hear you must succeed on a Wisdom save against your CE DC or be unable to move closer to you until the end of your next turn."}, {"name": "Parade Master (11+)", "prereq": "", "text": "As a bonus action, you may merge with one of your spectral oni silhouettes within 30 feet: until the start of your next turn you gain the benefits of a second Mask of your choice in addition to the one you wear; the silhouette is consumed."}], "e190": [{"name": "Silk Architect", "prereq": "", "text": "When you create Anchor Threads, you may anchor one end to a willing creature within 30 feet instead of a surface; the thread moves with the creature, and you always know its direction and distance while the thread lasts."}, {"name": "Tremor Reader", "prereq": "", "text": "While you are touching one of your Anchor Threads, you gain blindsight with a 10-foot radius centered on every anchor connected to that thread, reading movement through the web as though you stood at each anchor. A creature moving inside this tremor-sense cannot benefit from being unseen against your thread-snapping reactions. The sense is passive, but it ends for any anchor whose thread is cut or dismissed."}, {"name": "Spider Drop", "prereq": "", "text": "When you drop at least 10 feet from the ceiling onto a creature, you may forgo your attack to land on it instead: it must succeed on a Strength save against your CE DC or be knocked prone and grappled by you."}, {"name": "Eightfold Knot (11+)", "prereq": "", "text": "As an action, you may collapse a Loom Trap into a portable snare that lasts 1 hour; as a bonus action you can throw it at a point within 30 feet to instantly reform the trap there."}], "e191": [{"name": "Monkey's Cunning", "prereq": "", "text": "While the Monkey aspect is active, you gain proficiency in Sleight of Hand, or expertise if you are already proficient. You may perform one fine-manipulation object interaction — picking a lock, palming a component, cutting a purse — as a bonus action instead of an action, and creatures have disadvantage on Wisdom (Perception) checks to notice it while you remain in Monkey aspect. The aspect's precision is in the hands, not just the eyes."}, {"name": "Tiger's Pounce", "prereq": "", "text": "While the Tiger aspect is active, when you hit a creature with a melee attack after moving at least 15 feet straight toward it, you may force it to make a Strength saving throw against your technique DC. On a failure it is knocked prone; on a success it is pushed 5 feet away from you. You may use this once per turn, and it has no effect on a creature two or more sizes larger than you."}, {"name": "Serpent's Patience", "prereq": "", "text": "While the Serpent aspect is active, when you have a creature grappled you may use your action to make a contested grapple check; on a success the grapple tightens into a restraint as your coils lock, lasting until the grapple ends or you change Aspect. A restrained creature takes 1 die of bludgeoning damage at the start of each of its turns while the restraint holds. Changing Aspect ends the restraint but not the underlying grapple."}, {"name": "Tanuki Mist", "prereq": "", "text": "While the Tanuki aspect is active, you may attempt to Hide even when only lightly obscured by natural phenomena — mist, foliage, falling snow, or dim light. If you end your turn hidden this way without having attacked, you may move up to 10 feet without breaking hiding, your Tanuki swiftness carrying you between cover. Creatures have disadvantage on checks to track you by scent or sound while you remain hidden under this feat."}], "e192": [{"name": "Feather Shield", "prereq": "", "text": "When an ally within 15 feet is targeted by an attack, you may use your reaction and spend 1 Pinion to interpose a shield of pinion feathers, granting the ally +2 AC against that attack. Decide after seeing the attack roll but before knowing the result. If the attack misses because of this bonus, the feather returns to your wings and you regain the spent Pinion, up to your maximum."}, {"name": "Sky Ferry", "prereq": "", "text": "While flying with your Golden Pinions, you may carry one willing creature without reducing your flying speed. The carried creature may use its reaction during your movement to make one attack or cast a cantrip, striking from above; your movement still provokes opportunity attacks as normal. If you are forced to land while carrying a creature, you may spend 1 Pinion as a reaction to glide it safely to the ground within 15 feet of you, negating its falling damage."}, {"name": "Venom Breaker", "prereq": "", "text": "Enemy of Venom can apply to disease/corrosive ongoing effects when appropriate."}, {"name": "Solar Plumage (11+)", "prereq": "", "text": "When you start your turn in direct sunlight, you may end the poisoned or restrained condition on yourself without spending Pinions, as the sun's light does the cleansing for you."}], "e193": [{"name": "Light-Eater", "prereq": "", "text": "When Swallow the Light extinguishes a light source, you may use your bonus action to weaponize the eaten light: one creature within 30 feet that you can see must succeed on a Constitution save against your CE DC or be blinded until the end of your next turn."}, {"name": "Endless Coil", "prereq": "", "text": "At Depth 3, your Coil of Night can strike through darkness itself: you may originate the attack from any dimness or darkness you created within 60 feet instead of from yourself."}, {"name": "Enemy of Sunrise", "prereq": "", "text": "When a radiant effect reduces your Night Depth, you may use your reaction to lash back at the light-bringer: it must succeed on a Constitution save against your CE DC or take 2 Night Dice necrotic damage."}, {"name": "Chaos Before Creation (11+)", "prereq": "", "text": "The first time each long rest your Night Depth would fall to 0, you may unleash its dregs instead: every light source within 30 feet is extinguished, and each creature of your choice within 15 feet must succeed on a Constitution save against your CE DC or be blinded until the end of your next turn. Your Depth becomes 0 afterward."}], "e194": [{"name": "Lion's Pursuit", "prereq": "", "text": "At Heat 3+, when you take the Dash action you may leave a 5-foot-wide trail of fire along your path: creatures that enter it before the start of your next turn take 1 fire die."}, {"name": "Red Beer Ritual", "prereq": "", "text": "You may administer your Blood-Red Draught to an adjacent willing ally instead of drinking it yourself: the ally gains the healing (1 die + your CE modifier) and the end of the frightened condition, while your Heat still falls by 3 as the ritual's cooling passes through another's body. A use spent this way counts against your once-per-short-rest limit, and the ally must drink as part of your action. You cannot split a single draught's effects between two creatures."}, {"name": "Fever Claw", "prereq": "", "text": "When you hit a creature with a melee attack, you may spend 1 CE to deliver your plague by claw: the target's healing is reduced by your PB until the end of your next turn, as with Breath of Pestilence."}, {"name": "Two Faces of the Sun (11+)", "prereq": "", "text": "Once during your Maximum's 3-round duration, you may switch between Slaughter and Mercy as a bonus action, the sun turning its other face. Your Heat immediately becomes 5 for Slaughter or 0 for Mercy to match the new mode, and the spent round still counts toward the duration. You cannot switch again for the rest of the Maximum."}], "e195": [{"name": "Lantern Eyes", "prereq": "", "text": "Your detached spectral Head gains darkvision out to 120 feet and can see invisible creatures and objects within 10 feet of it, its lantern-light burning through concealment. While your sight and hearing originate from the Head, you have advantage on Wisdom (Perception) checks that rely on sight. If the Head is destroyed while you are seeing through it, you are blinded until the end of your next turn as your senses snap violently back to your body."}, {"name": "Unbroken Gallop", "prereq": "", "text": "When you would be forcibly moved, you may spend 1 Gallop as a reaction to refuse it: the forced movement becomes 0 as your steed's momentum carries straight through."}, {"name": "Death Coach", "prereq": "", "text": "While your Black Steed is manifested, it may carry one willing ally in addition to you, and the ally shares your movement — including Gallop-fueled charges and Unbroken Gallop's refusal of forced movement — without costing either of you actions. An ally riding with you gains half cover against attacks coming from the steed's flanks. If the steed is dismissed or you are knocked prone while mounted together, the ally lands safely in an unoccupied adjacent space of its choice."}, {"name": "Last Name Spoken (11+)", "prereq": "", "text": "As a bonus action, you can call your Road's End down the road: it must succeed on a Wisdom save against your CE DC or use its reaction to move up to its speed toward you by the most direct route."}], "e196": [{"name": "Family Wail", "prereq": "", "text": "Choose PB allies after each long rest; your keen’s witness range extends to 90 feet for them."}, {"name": "Glass-Shattering Keen", "prereq": "", "text": "Your Piercing Wail deals double damage to fragile mundane objects — glass, ceramics, thin wood, and the like — shattering windows and pottery in its cone on a failed save regardless of their remaining hit points. You may exempt objects carried or worn by creatures from the cone's destructive resonance. As a finer application, you may spend 1 CE to narrow the wail to a 15-foot cone that affects only objects, keening the room's glass to shards while leaving every creature untouched."}, {"name": "Professional Mourner", "prereq": "", "text": "When an ally you keened for dies, you may spend 1 minute keening over the body: you learn the exact direction and distance of whatever dealt the killing blow (if within 1 mile), and you cannot be surprised by it for the next 24 hours."}, {"name": "Second Cry (11+)", "prereq": "", "text": "When the keen fires, you may spend 2 CE to shape its echo into a warning for one ally within 60 feet: that ally gains +2 AC until the start of your next turn, having heard death coming."}], "e197": [{"name": "Long Arms", "prereq": "", "text": "While transformed, you may use your bonus action to plant Blight with your long arms: touch a point within your reach to create a 5-foot Blight patch there for 1 minute."}, {"name": "Murrain Wind", "prereq": "", "text": "When you take the Dash action while transformed, you may exhale your breath behind you, leaving a 5-foot-wide trail of Blight along your path until the start of your next turn."}, {"name": "Salt-Air Rot", "prereq": "", "text": "As a bonus action, you can taste the Wither on a creature within 30 feet that has at least 2 Wither: learn its current HP total and whether it is maintaining Focus on anything."}, {"name": "Black Tide (11+)", "prereq": "", "text": "once/short rest move one Blight patch 10 ft, never across fresh water."}], "e198": [{"name": "Roost Walker", "prereq": "", "text": "You gain a climb speed equal to your walking speed and can hang hands-free from any surface you could climb, talons and tail holding you fast. While hanging hands-free and unseen, From the Sound applies to every attack you make that turn, not just the first. Releasing your grip deliberately is silent: you have advantage on Dexterity (Stealth) checks to land unheard when you drop on purpose."}, {"name": "Blood Echo", "prereq": "", "text": "A bloodied creature moving within 30 feet of one of your Echo nodes leaves a sound-track you can follow until the end of your next turn."}, {"name": "Silent Wing", "prereq": "", "text": "When you use Razor Swoop, your passage stays unrevealed until the attack resolves: you are treated as unseen for the swoop's attack, and enemies cannot use reactions triggered by your movement during it. Creatures that had not perceived you before the swoop do not learn your location until after damage is rolled. If the attack misses, you may immediately Swap to an Echo node within 30 feet as part of the same action, gone on the wingbeat."}, {"name": "Vanishing Wing (11+)", "prereq": "", "text": "When you are hit by an attack, you may use your reaction and spend 1 CE to swap with an Echo node within 30 feet; the attack misses if your new position is beyond the attacker's reach or out of its line of sight."}], "e199": [{"name": "Precious Plumes", "prereq": "", "text": "When you generate a Plume from a full traversal, you may instead immediately redraw one of your Wind Roads, keeping its length but choosing a new position and direction anchored within 30 feet of you."}, {"name": "Tailwind Archer", "prereq": "", "text": "When you make a ranged attack along the direction of a Wind Road, you may have the attack emerge from a Crossroad within 60 feet of you instead, originating there and ignoring cover between you and the target."}, {"name": "Cloud Serpent", "prereq": "", "text": "While flying with Serpent of the Updraft, you may use a bonus action to trace a Wind Road up to 30 feet long along your flight path. It counts against your normal maximum."}, {"name": "Four Directions (11+)", "prereq": "", "text": "When you or a willing ally teleports between Crossroads, you may instead swap the positions of two willing creatures standing at two different Crossroads within range."}], "e200": [{"name": "Inscribed Gate", "prereq": "", "text": "When you inscribe a Threshold, you may spend 1 Vigilance to render it invisible to hostile creatures. A hostile creature can spot it with a successful Wisdom (Perception) check against your technique save DC."}, {"name": "Winged Guardian", "prereq": "", "text": "When you use Bull-Lion Intercession, you may instead teleport the ally from one Threshold to another Threshold within 30 feet of the first, rather than swapping positions with them; you still take the hit either way."}, {"name": "Palace Watch", "prereq": "", "text": "As a bonus action, you may spend 2 Vigilance to relocate one Threshold you can see to a new valid anchor within 60 feet."}, {"name": "No Unrecorded Passage (11+)", "prereq": "", "text": "Hostile invisible creatures that cross one of your Thresholds are revealed until the end of their turn: invisibility and similar concealment are suppressed for the crossing creature as the gate counts its passage. The creature may attempt a Wisdom save against your technique DC; on a success it remains unseen but still generates Vigilance as normal. You always know the exact space where the crossing occurred. This revelation pierces magical invisibility but not total cover or anti-divination effects."}], "e201": [{"name": "Cedar Warden", "prereq": "", "text": "The forest carries your face farther and wider. Your active Terror Face's aura effects now originate from a 20-foot radius around each cedar zone within 120 feet of you (instead of 15 feet within 60 feet). Your own 15-foot personal aura is unchanged."}, {"name": "Terrible Countenance", "prereq": "", "text": "When a Cedar zone is destroyed, you may immediately switch your Face without using an action and resolve the new Face against the creature that destroyed it."}, {"name": "Forest Voice", "prereq": "", "text": "Switching your Terror Face is not a verbal act: you may change Faces even while silenced, gagged, or inside magical silence — and while you cannot speak, switching your Face costs no action at all. The forest speaks where your voice cannot."}, {"name": "Sevenfold Guardian (11+)", "prereq": "", "text": "Once per short rest, when you switch your Terror Face, you may maintain two Faces simultaneously until the end of your next turn — your visage splits and both fear-laws hold. Hostiles in your Aura resolve both Faces' effects where applicable, but a single creature cannot suffer more than one failed-save result from this overlap. When the duration ends, you keep the most recently chosen Face and the other fades."}], "e202": [{"name": "Compound Payload", "prereq": "", "text": "When you spend 2 Spines on a single Tail Volley attack, you may combine two payload effects on that attack, such as a Barbed Venom quill, instead of choosing only one."}, {"name": "Scorpion Tail", "prereq": "", "text": "You may deliver your Venom payload through your Lion’s Maw instead of a quill. When you hit with Lion’s Maw, you may spend 1 Spine to force the target to make the Venom saving throw."}, {"name": "Quill Catcher", "prereq": "", "text": "Once per round, when a ranged weapon attack misses you, you may use your reaction to snatch the projectile from the air and add it to your Tail Magazine, recovering 1 Spine. If you do, you may immediately make a Tail Volley attack against a creature within range without spending a Spine, firing the caught missile back. This return shot follows the normal Tail Volley rules but cannot apply payload effects."}, {"name": "Hunter's Mouth", "prereq": "", "text": "When you hit an object or a dead or incapacitated creature with Lion’s Maw, you recover 2 Spines instead of 1."}], "e243": [{"name": "Dialed In", "prereq": "Ben 10 feat", "text": "As a bonus action, you may rearrange your Active Playlist, swapping one loaded ordinary form for another Subjugated ordinary form you know. This does not count as transforming and adds no Instability."}, {"name": "Hero Time", "prereq": "Ben 10 feat", "text": "Once per short rest, use one of these triggers: when initiative is rolled, immediately transform into a loaded ordinary form without an action or CE; or when a creature you can see within 30 feet is targeted by an attack, use your reaction to transform for 0 CE before the attack resolves. The second option does not redirect the attack or grant a second reaction."}, {"name": "Quick-Change Combatant", "prereq": "Prerequisite: level 6", "text": "When you Quick Change, you retain one passive trait of your previous form, such as a movement mode or sense, until the end of your next turn."}, {"name": "Form Specialist", "prereq": "Repeatable: different forms", "text": "Choose one Subjugated non-Way Big form. Once per short rest, while transformed into a different form, you may use one feature of your chosen form, paying its normal CE cost. You may take this feat again for another form, but never twice for the same form."}], "e244": [{"name": "Fast Scribe", "prereq": "", "text": "Once per turn, you may inscribe a Tier I rune as a bonus action instead of an action."}, {"name": "Blood-Carved Staves", "prereq": "", "text": "You may carve a persistent rune directly into your own flesh as a living stave. A rune carved this way moves with you, cannot be dispelled by effects that target objects, and once per short rest you may invoke it as a bonus action instead of an action."}, {"name": "Ætt-Binder", "prereq": "", "text": "When you form a Bindrune from two runes of the same ætt, you may inscribe it on a weapon, shield, or tool you touch. Either component rune can then be invoked separately without breaking the Bindrune. Wyrd belongs to no ætt and can never benefit from this feat."}, {"name": "Runeseer", "prereq": "", "text": "Reading of the Three takes 1 minute instead of 10. Its Foretold Die becomes your Rune Die. Once per long rest, you may ask one simple yes/no question concerning the next 24 hours; the GM answers truthfully according to the most likely course of events at the time of the reading."}], "e246": [{"name": "Straight Man", "prereq": "Prerequisite: Must have Comedy", "text": "Choose one willing ally who can see and hear you. That ally may deliver one of your Gags as if they were you, using your CE save DC, though you still pay any CE cost. The ally must be within 30 feet of the Gag’s target."}, {"name": "Super Gag", "prereq": "Prerequisite: Must have Commit to the Bit", "text": "You have stepped up your game with some premium material you read online. You gain the following gags while your technique is active: Written on your Face. As an action for 3 CE, you target a creature within 30 ft that you can see. For 1 minute or when your technique ends, the target’s emotions and intentions are literally written on their face. The target has disadvantage on attacks against anyone who can see their face. Anyone that can see their face knows their general emotions and can tell whenever they are scheming or planning something by reading the doodles on their face. Costume Switch. As an action for 2 CE, you apply a wardrobe change to a number of creatures equal to your CE modifier within 30 ft of you that you can see. This effect is purely cosmetic and cannot change their AC or movement and cannot give them any conditions. You can also change a property about them, such as giving them multiple eyes or arms. These changes are nonfunctional and a creature can take an action to make a Wisdom (Perception) or Intelligence (Investigation) against your CE save DC inspect these changes. On a success, they realize the changes are fake. This feature lasts for a number of minutes equal to your CE modifier before disappearing."}, {"name": "Maximum: Laugh Track", "prereq": "Prerequisite: Must have Peak Comedy", "text": "While your technique is active, your invisible audience can deliver your Gags for you. A Gag you use may originate from any point within 30 feet of you that you choose; creatures cannot tell the Gag came from you without succeeding on a Wisdom (Perception) check against your CE save DC."}], "e247": [{"name": "Bestial Seance", "prereq": "Prerequisite: Must have Seance", "text": "You have learned to bring a bit of whimsy to your usually ghastly technique. When you use Seance on yourself, you can choose to instead channel the Physical Information of a Beast with a CR equal to or less than your proficiency bonus. You gain all the creature’s traits, senses, movements and actions in addition to the normal effects of Physical Information. To use this technique, you must be wearing a costume of that specific animal, costing $200 x the Beast’s CR. You can wear this costume with armor, but if it takes an amount of damage (other than psychic) equal to 3 x your level, it becomes unusable and you lose any benefits from this feature."}, {"name": "Warded Circle", "prereq": "Prerequisite: Must have Ritual of Resurrection", "text": "When you begin your Ritual of Resurrection, you may trace a warding circle around yourself. For the ritual’s duration, hostile creatures treat the 10-foot-radius circle as difficult terrain and must succeed on a Wisdom saving throw against your CE save DC to willingly enter it."}, {"name": "Cling to Life", "prereq": "Prerequisite: Must have Maximum: Black Seance", "text": "When a target runs out of cursed energy and can no longer maintain the seance, they can choose to forcefully hold the spirit within their body. At the beginning of the target’s turn, they instead spend 5 HP, reducing their maximum by the same amount. Your hit point maximum is restored by 15 after each long rest."}], "e248": [{"name": "Blood Production", "prereq": "Prerequisite: Must have Rot Techniques", "text": "You have found a way to link your blood to Cursed Energy. For 1 CE, you can create a sufficient source of blood worth 10 HP that can only be used for your Rot features. This does not regain HP."}, {"name": "Condensed Decay", "prereq": "Prerequisite: Must have Scarlet Rot", "text": "When you hit a creature with a Rot Technique, you may spend up to 4 HP. The target’s speed is reduced by 5 feet for every 2 HP spent until the end of its next turn, as your blood clots around its limbs."}, {"name": "Blackened Blood", "prereq": "Prerequisite: Must have Maximum: Wing King", "text": "Your blackened blood marks what it touches. You always know the direction and distance of any creature damaged by your Rot Techniques within the last hour, and you have advantage on Wisdom (Survival) checks to track them."}, {"name": "Wingbeat", "prereq": "Prerequisite: Must have Maximum: Wing King", "text": "While using Wing King, you may beat your veined wings as a bonus action. Each creature within 15 feet of you must make a Strength saving throw against your CE save DC or be pushed 10 feet away from you and knocked prone."}], "e249": [{"name": "Patchwork Salvage", "prereq": "Prerequisite: Must make Cursed Corpse Creation", "text": "When one of your Cursed Corpses is destroyed, you may spend 1 hour harvesting its intact parts. You may transfer one mutation from the destroyed corpse to another of your Cursed Corpses."}, {"name": "Soul Imbuement", "prereq": "Prerequisites: Must have Cursed Corpse Creation", "text": "You have learned to copy a creature’s soul information into a Cursed Corpse. You can only have 1 soul imbued corpse at a time. This increases to 2 at 11th level and 3 at 18th level. It takes 3 long rests to imbue someone’s soul information into the core. You must have the person readily available or have a good memory of the person to turn their physical information into soul information. Once a corpse has been created, it takes 2 weeks to develop before it becomes sentient. It gains the Autonomy mutation and can choose a Cursed Energy feat as if it were a player. A corpse with this core is sentient and mimics the behavior of the soul they are imbued with, but it does not gain its memories."}, {"name": "Cursed Tactician", "prereq": "Prerequisite: Must have Corpse Tactics", "text": "Your Corpse Tactics orders can be relayed through your corpses. When you use Corpse Tactics, a corpse within range may pass the order to another of your corpses within 30 feet of it, which may pass it on further, extending your effective command range."}, {"name": "Mutate Specialist", "prereq": "Prerequisite: Must have Cursed Corpse Mutation", "text": "Once per long rest, when one of your Cursed Corpses would gain a random mutation, you may instead grant it a mutation already possessed by another of your corpses."}], "e250": [{"name": "Blood Production", "prereq": "Prerequisites: Must have Blood Manipulation", "text": "You have found a way to link your blood to Cursed Energy. For 1 CE, you can create a sufficient source of blood worth 10 HP that can only be used for your Blood Manipulation features. This does not regain HP."}, {"name": "Poisonous Blood", "prereq": "Prerequisites: Must have Blood Manipulation", "text": "As an action, you may draw your blood into a sealed vessel, spending up to 10 HP; the vessel holds that blood for 24 hours. A creature can drink it as a bonus action to regain hit points equal to the HP stored. You can maintain only one such vessel at a time."}, {"name": "Blood Crystallization", "prereq": "Prerequisites: Must have Blood Constructs", "text": "As an action for 3 CE, you crystallize your blood into a solid object: a simple weapon, a tool, or a 10-foot plank or pole. The object lasts 1 hour, has AC 15 and hit points equal to twice your level, and shatters into harmless shards when destroyed."}, {"name": "Crimson Afterimage", "prereq": "Prerequisites: Must have Flowing Red Scale", "text": "While Flowing Red Scale is active, your accelerated blood lets you leave a bloody afterimage. As a bonus action for 3 CE, you create an illusory duplicate in your space until the start of your next turn; the first attack roll made against you before then targets the duplicate, AC 10 + your proficiency bonus, instead of you, and the duplicate vanishes whether the attack hits or misses."}, {"name": "Supernova", "prereq": "Prerequisites: Must have Piercing Blood", "text": "You can create small orbs of condensed blood that explode like a buckshot. As an action, you condense your Piercing Blood into a tiny orb of blood in an unoccupied space that you can see within 30 feet, which stays there for a maximum of 1 minute before exploding. You can create as many orbs as your proficiency bonus in an action with each having its own cost, spending 5 CE and 5 HP for each, and can choose for them to explode immediately upon creation or manually as a reaction to a creature entering the range of explosion. The orb then explodes, forcing every creature within 10 feet of it to make a Dexterity saving throw for each orb. On a failure, the target takes 8d8 piercing damage and is knocked prone. On a success, they take half as much damage and aren’t knocked prone."}, {"name": "Wing King Imitation", "prereq": "Prerequisites: Must have Piercing Blood", "text": "You condense your blood into wings resembling veins as a bonus action for 10 CE, gathering the wings behind you and gaining the following benefits for 1 minute: your walking speed is quadrupled; you gain a flying speed equal to half your walking speed; as a free action on your turn, you can unleash lines of blood. This takes shape as three ranged Cursed Energy attacks against a creature within 60 feet. Each attack deals 3d10 + your CE modifier in necrotic damage. While using Wing King, you cannot use Piercing Blood."}], "e251": [{"name": "Aerokinesis", "prereq": "Prerequisite: Must have Storms of Disaster", "text": "Through training and understanding, you have found new applications for your storms. Choose one; you may select this feat multiple times, choosing a different application each time. Suffocation. As an action for 2 cursed energy, you target a creature within 30 feet that you can see. It must make a Constitution saving throw, taking your proficiency bonus in d6s of necrotic damage and beginning to suffocate on a failed save. While suffocating, its movement is halved and its attack rolls have disadvantage. If you move more than 30 feet away or lose concentration, the suffocation ends. Storm Sense. While a storm of your creation is active, you can sense the location of any creature within it, feeling the air each one displaces."}, {"name": "Flying Nimbus", "prereq": "Prerequisite: Must have Storm Creation", "text": "While using Storm Creation, you have a flying speed equal to your walking speed and can hover. When you use Storms of Disaster while flying, you can immediately move up to 10 ft without spending movement or provoking opportunity attacks."}, {"name": "Squall", "prereq": "Prerequisite: Must have Maximum: Divine Storm Sovereign", "text": "While you are within a storm of your creation, you may teleport to a different point within the storm as a bonus action, and you may originate your Storms of Disaster techniques from any point within the storm."}], "e252": [{"name": "Vermin Bulwark", "prereq": "Prerequisite: Must have Vermin of Disaster", "text": "As a reaction when a creature within 5 feet of one of your Insect Swarms is hit by an attack, you may have the swarm interpose itself; the swarm takes the damage instead of the target."}, {"name": "Vermin Techniques", "prereq": "Prerequisite: Must have Almighty Swarm", "text": "You have learned to better control the combined actions of your Vermin Swarms, allowing you to learn the following ways to use your Swarms: Insect Cloak. While you are occupying the same space as one of your Vermin Swarms, you can treat the Swarm's hit points as temporary hit points for yourself. Grasping Hand. You can spend 3 CE to replace one of your attacks on your turn with a grapple check through one of your Insect Swarms against a creature within 5 ft of the swarm. Instead of an Athletics check, you make a Cursed Energy (Arcana) check. The grapple gains a +1 bonus and +5 ft of range per size category above Medium the swarm is. On a success, the creature is grappled and can be pulled into the Insect Swarm. Transport Via Bugs. As an action for 6 CE, you form a link between one Large or larger Vermin Swarm within 10 ft and connect it to another Large or larger Vermin Swarm at any distance. Before the end of your turn, you can spend 5 ft of movement to walk into the space of the Insect Swarm within 5 ft, reappearing within 5 ft of the destination Insect Swarm."}, {"name": "Festering Life Sword", "prereq": "Prerequisite: Must have Parthenogenesis", "text": "As a bonus action for 6 CE, you transform a weapon you are holding. It loses all previous benefits and becomes the Special Grade Cursed Tool: Festering Life Sword. You can only have one weapon transformed this way at a time and this tool disappears when you finish a long rest or die."}], "e253": [{"name": "Levitation System", "prereq": "Prerequisite: Must have Gravity Field", "text": "As an action for 2 CE, you can cast Levitate. You can spend an additional 2 CE to force the creature to make the save at disadvantage."}, {"name": "Inverted Shield", "prereq": "Prerequisite: Must have Antigravity Shield", "text": "As a reaction when you are hit by a melee attack while your Antigravity Shield is active, you may spend 3 CE to invert the field. The attacker must make a Strength saving throw against your CE save DC or be pulled 10 feet toward you and knocked prone."}, {"name": "Antigravitational Flight", "prereq": "Prerequisite: Must have Boosted System", "text": "As an action for 3 CE, you can give yourself or another creature you touch a 60 feet hover speed for 10 minutes."}], "e254": [{"name": "Instant Manifestation", "prereq": "Prerequisite: Must have Dark Cube", "text": "When you are hit by an attack, you may use your reaction to manifest a Dark Cube around yourself; the cube takes the damage in your stead, applying the damage to the cube’s statistics. If you took the Dodge action on your turn, you may extend the cube to also enclose one creature within 5 feet of you."}, {"name": "Offensive Creations", "prereq": "Prerequisite: Must have Black Box Reinforcement", "text": "You have focused on using your technique to devastating effects and have learned offensive applications of your cursed technique: Crushing Cube. As an action for 4 CE, you target a 30 feet tall, 10 feet wide square cylinder within 30 feet. All creatures in range must make a Strength saving throw. On a failure they take 5d10 necrotic damage and fall prone as they are crushed under a massive Dark Cube. On a success, they take half as much damage and are not prone. Block Strike. As a bonus action for 2 CE, you cover your fist or other part of your body with a Dark Cube for 1 minute. You can make a melee cursed energy attack with your unarmed strikes. On a hit you deal your proficiency bonus in d4s + your CE modifier in necrotic damage. Dark Press. As an action for 5 CE, you can create a Dark Cube in front of you that explodes in length on one side. All creatures in a 10 feet wide 60 feet long line must make a Dexterity saving throw. On a failure, they take 6d8 necrotic damage and are pushed back to the edge of the line. If they impact a solid object or structure, they take the remaining distance as fall damage."}, {"name": "Sealing Cube", "prereq": "Prerequisite: Must have Maximum: Midnight Armor", "text": "When you trap a creature in a Perfect Cube, you can choose to seal the output of the creature. They can only spend the minimum cursed energy on a cursed technique while trapped within your Perfect Cube and cannot use cursed techniques that cost more than 5 cursed energy."}], "e255": [{"name": "Ferocious Courage", "prereq": "Prerequisite: Must have Ignition", "text": "When you hit a creature with your ignited weapon, you may spend 1 CE to let the flames leap to another creature within 15 feet of the target. That creature must make a Dexterity saving throw against your CE save DC, taking half your Ignition damage on a failure."}, {"name": "Blazing Heart", "prereq": "Prerequisite: Must have Mantle of Courage", "text": "When you activate Mantle of Courage, you may drape its flames over one willing ally within 30 feet instead of yourself. That ally gains the aura, resistances, and other benefits of the Mantle for the duration."}, {"name": "Soulfire", "prereq": "Prerequisite: Must have Eternal Flames", "text": "You have learned to burn even the soul. When you hit with a melee attack, you can spend 3 CE to cause all fire damage dealt on your turn to ignore immunity to fire damage and reduce a creature's maximum hit points until they complete a long rest."}, {"name": "Technique Release", "prereq": "Prerequisite: Must have Maximum: Conflagration", "text": "When you hit with an attack while Ignition is active, you may end Ignition early to discharge its remaining flame. Each creature within 10 feet of the target, other than you, must make a Dexterity saving throw against your CE save DC, taking your Ignition damage on a failure or half as much on a success."}], "e256": [{"name": "Dowsing Vibrations", "prereq": "Prerequisite: Must have Cursed Centipede", "text": "While your centipede shikigami is summoned, you gain tremorsense out to 100 feet while both of your feet are on the ground. You cannot be surprised by creatures touching the ground within your tremorsense, and you know the exact location of invisible creatures touching the ground within it. The range increases to 150 feet at 6th level, 200 feet at 11th, and 300 feet at 18th level."}, {"name": "Wu Gong", "prereq": "Prerequisite: Must have Insect Storage", "text": "You have learned to concentrate the venom of your cursed centipede and add it to your attacks. When you or your centipede hit with a melee attack, you can spend 1 CE to force the creature to make a Constitution saving throw. On a failure, the creature takes your proficiency in d6s of poison damage and they are stunned until the beginning of their next turn."}, {"name": "Living Gullet", "prereq": "Prerequisite: Must have Insect Storage", "text": "Your centipede’s stomach can carry living cargo. It may swallow one willing or incapacitated creature of Medium size or smaller; the creature can breathe inside but is blinded and restrained while swallowed. Disgorging the creature takes an action. The centipede cannot store items while carrying a creature."}], "e257": [{"name": "Forcible Confession", "prereq": "Prerequisite: Must have Binding Vow", "text": "As a bonus action for 2 CE, you can force a creature within 30 ft to speak only truthful words for 1 minute, or until they succeed on a Charisma saving throw at the end of their turn."}, {"name": "Cunning Judicator", "prereq": "Prerequisite: Must have Retrial", "text": "When a creature breaks a Binding Vow with you, you can spend 5 CE as a reaction to force the creature to make a Charisma saving throw. On a failure, it takes 1d4 force damage per 10 hit points it has remaining (rounded down, maximum 10d4)."}], "e258": [{"name": "Dead-Man's Circuit", "prereq": "Prerequisite: Must have Cursed Circuitry", "text": "You may key a circuit pattern to your own vital signs. When you set the pattern, you may choose for it to trigger if you fall unconscious or die, even if its normal activation condition is never met."}, {"name": "Circuit Chain Reaction", "prereq": "Prerequisite: Must have Advanced Circuits", "text": "When a circuit pattern is activated, you can spend 2 cursed energy to cause a chain reaction. Choose a circuit pattern within 20 feet of the activated pattern. That pattern is also activated, even if its activation condition is not met. You can use this feature a number of times equal to your proficiency bonus per long rest."}, {"name": "Living Circuitry", "prereq": "Prerequisite: Must have Linked Circuits", "text": "You have learned to infuse your own body with cursed circuitry. As an action, you can spend 10 cursed energy to gain the following benefits for 1 minute: your unarmed strikes deal an additional 1d6 lightning damage; you gain resistance to lightning damage; you can use Burst Leap on yourself as a bonus action without needing a circuit pattern. At 11th level, you can spend 15 cursed energy instead to also gain immunity to being stunned."}], "e259": [{"name": "Master Alchemist", "prereq": "Prerequisite: Must have Cursed Transmutation", "text": "You can transmute magical objects, and you may perform a transmutation on an object you can see within 30 feet without touching it."}, {"name": "Philosopher's Stone", "prereq": "Prerequisite: Must have Elemental Manipulation", "text": "You have created a Philosopher’s Stone, a powerful alchemical artifact. It grants you two masterworks. Chrysopoeia: once per long rest, you may transmute up to 1 cubic foot of base metal into gold worth up to 100 gp. Panacea: you may crush a fragment of the Stone, which reforms at dawn, to end one poison, disease, or curse afflicting a creature you touch."}, {"name": "Soul Alchemy", "prereq": "Prerequisite: Must have Alchemy of the Soul", "text": "You have learned to transmute souls. As an action for 8 CE, you can forge a soul bond with a willing creature within 30 ft. While bonded, you can sense each other's emotions and location, and you can communicate telepathically. If one of you takes damage, the other can choose to take half of that damage instead. This bond lasts until dispelled or until one of you dies."}], "e260": [{"name": "Wheel of Adaptation", "prereq": "Prerequisite: Must have Dark Claw", "text": "You manifest Mahoraga's wheel above your head, turning with every adaptation you complete. As a bonus action for 2 CE, you can turn the wheel toward one ally you can see within 30 ft, lending them your hard-won resilience — they gain the resistance or immunity of one of your active adaptations until the end of your next turn."}, {"name": "Mahoraga's Fury", "prereq": "Prerequisite: Must have Adaptation", "text": "When you are reduced to half your hit points or fewer, Mahoraga's fury surfaces through your claw. As a bonus action for 2 CE, you can slam the Dark Claw into the ground, erupting jagged claws in a 15 ft radius around you. Each creature in the area must make a Dexterity saving throw, taking your unarmed strike damage on a failed save or half as much on a success. Once you use this eruption, you can't use it again until you finish a short rest."}, {"name": "Perfect Adaptation", "prereq": "Prerequisite: Must have Eight-Handled Sword", "text": "Your adaptation is now perfect — nothing learned is wasted. As an action for 3 CE, you can discharge one of your adaptations: choose a damage type you have adapted to during this combat and release it in a 30 ft cone. Each creature in the area must make a Dexterity saving throw, taking 1d8 damage of the chosen type for each damage type you have adapted to this combat (maximum 5d8) on a failed save, or half as much on a success. Your adaptation to the discharged type ends."}], "e261": [{"name": "Ley Line Extension", "prereq": "Prerequisite: Must have Ley Line Command", "text": "You have learned to extend the benefits of your connection with the earth to others. When you create a Ley Line you can give a number of creatures equal to your Cursed Energy modifier the benefits of Flow of the Dragon while they are within 30 ft and touching the same ground as you."}, {"name": "Ground Control", "prereq": "Prerequisite: Must have Earth Dragon Soul", "text": "As an action for 3 CE, you stomp your foot and transform the ground within 30 ft in one of the following ways:"}], "e262": [{"name": "Density Manipulation", "prereq": "Prerequisites: Must have Excavation", "text": "You have learned to change the density of the stone you shape. As a bonus action for 1 CE, you can touch one of your stone constructs and either make it light as pumice — it can be carried or moved freely and no longer blocks movement — or hyper-dense: a creature underneath or adjacent to it must succeed on a Strength saving throw or be pinned beneath it, restrained until it uses its action to make a Strength (Athletics) check against your CE save DC to shove free."}, {"name": "Rock Burst", "prereq": "Prerequisites: Must have Sculpted Earth", "text": "As a reaction, you can cause one of your stone constructs within 60 feet of you to explode. Any creature within 5 feet must make a Dexterity saving throw. On a failed save, they take 1d12 bludgeoning damage and are knocked prone. You can spend CE up to half your proficiency bonus (rounded down) as part of this reaction to heighten the explosion and deal an additional 1d12 bludgeoning damage per CE and cause creatures in range to take half as much damage on a success."}, {"name": "Arms of the Giant", "prereq": "Prerequisite: Must have Stone Arms", "text": "You have taught your Stone Arms new grips. While maintaining your Stone Arms, you can use your action for one of the following instead of crushing: Interposing Fist — the arms close around you, granting you three-quarters cover until the start of your next turn. Sundering Grip — crush a restrained creature as normal, and the shock of the impact gives it disadvantage on its next attack roll. Hurl — throw a restrained creature up to 30 ft to an unoccupied space you can see; if it strikes a solid surface, it takes 3d6 bludgeoning damage."}], "e263": [{"name": "Snake Scales", "prereq": "Prerequisites: Must have Eight Lives", "text": "Like Orochi, you have learned to shed your skin. As a reaction to taking damage for 2 CE, you slough off your outer scales: you end one of the following conditions affecting you — grappled, restrained, or poisoned — and can move up to 10 ft without provoking opportunity attacks, leaving the shed skin behind."}, {"name": "Blessing of the Hydra", "prereq": "Prerequisites: Must have Collective Will", "text": "When you use Eight Lives to return to life, you can gain resistance to one damage type that reduced you to 0 hit points or immunity to one harmful condition you had. This benefit lasts for 1 hour."}, {"name": "Fang Versatility", "prereq": "Prerequisites: Must have Fangs of Orochi", "text": "You have trained your technique to be more versatile in combat. You can wield Fangs of Orochi as a Dagger or Shortsword, and you can throw a Fang as a thrown weapon (range 20/60 ft) — a thrown Fang slithers back to your hand at the start of your next turn. When one of your Fang shikigami hits a creature, you can forgo the damage to have the Fang coil around the target's limb instead: the target has disadvantage on attack rolls until the end of your next turn."}], "e264": [{"name": "Diptych", "prereq": "Prerequisite: Must have Cursed Painting", "text": "You have learned to fold, expand, and even connect the subspaces of your paintings. When you enter one of your painting subspaces, you can spend 4 cursed energy to exit from one of your physical paintings. Additionally, the number of paintings you can have at once increases by your proficiency bonus and the area of your subspace doubles."}, {"name": "Air Brush", "prereq": "Prerequisite: Must have Impasto Canvas", "text": "As a reaction to an attack roll, you can spend 1 Cursed Energy to add +4 to your AC against the attack by forming a cursed painting, storing the attack in your subspace on a miss. If you have taken the dodge action, you can use this reaction on allies within 5 feet."}, {"name": "Gradient", "prereq": "Prerequisite: Must have Sgraffito", "text": "As an action for 5 cursed energy, you create a subspace Gradient that fills a 30 ft cube centered on you for 1 minute (60 ft at 11th level). You can use your innate technique features within this subspace, but they cannot extend beyond it. As a bonus action for 2 CE while the Gradient persists, you can fade one willing creature you can see inside it into the color wash — they become invisible to creatures outside the Gradient until they attack, use a technique, or the Gradient ends."}], "e265": [{"name": "Regrown Flesh", "prereq": "Prerequisite: Must have Faster Throws", "text": "You have learned to knit your explosive flesh back together. As a bonus action for 2 CE, you can regrow or reattach a body part you removed that has not yet detonated, restoring its use. You do not regain the hit points you spent to remove it."}, {"name": "Elemental Bomb", "prereq": "Prerequisite: Must have Guerilla Tactics", "text": "You have learned how to create different types of explosions. When you use a bomb, you can spend additional cursed energy equal to the energy spent to make it an elemental bomb, choosing fire, cold, or lightning. The bomb's damage becomes that type, and it gains an additional effect: fire ignites flammable objects and deals an extra 1d6 fire damage to creatures that failed the save; cold halves the speed of creatures that failed the save until the end of their next turn; lightning arcs to one additional creature within 15 ft of the blast, dealing half the bomb's damage to it."}], "e266": [{"name": "Kinetic Absorption", "prereq": "Prerequisite: Must have Store and Release", "text": "As a reaction to bludgeoning, slashing, or piercing damage, you can spend 1 cursed energy to reduce the incoming damage by your Cursed Energy score and gain 1 Jin Charge. You cannot reduce the damage of other damage types."}, {"name": "Carried Momentum", "prereq": "Prerequisite: Must have Instantaneous Movement", "text": "You have learned to share your instantaneous movement. When you use Instantaneous Movement, you can spend 1 additional Jin charge to bring one willing creature you are touching with you, moving them to the same destination without provoking opportunity attacks."}], "e267": [{"name": "Veil of the Faceless God", "prereq": "Prerequisite: Must have Madness Inducement", "text": "You have learned to see through the cracks your madness opens. When a creature gains Madness from your technique, you can spend 1 CE as a reaction to peer through the fracture — until the end of your next turn, you can see and hear through that creature's senses."}, {"name": "Hands of Madness", "prereq": "Prerequisite: Must have Madness Enhancement", "text": "You have learned to use your Madness to enhance your unarmed strikes. You gain 1d6 Madness when you hit a creature with an unarmed strike. Additionally, your unarmed strikes deal an additional 1d6 psychic damage for every 10 Madness the target has."}, {"name": "True Mania", "prereq": "Prerequisite: Must have Obsession and Insanity", "text": "You have learned to aim the madness you unleash. When a creature becomes berserk from your Madness, you can spend 2 CE to name its obsession — you choose which creature the berserk creature perceives as its target."}], "e268": [{"name": "Destined One", "prereq": "Prerequisite: Must have Fate Manipulation", "text": "You have learned to tug the threads you tie. As a bonus action for 1 CE, you can pull the red thread binding a creature affected by one of your Fates: the creature must succeed on a Strength saving throw or be pulled up to 15 ft toward the creature it is bound to. If both bound creatures are willing, no save is required and you can swap their positions instead."}, {"name": "Web of Fate", "prereq": "Prerequisite: Must have Cursed Eyes of Fate", "text": "When you cast a Fate onto targets, you can instead target a number of creatures equal to 1 + your proficiency bonus within range. If the Fate requires Touch, you must touch all targets of the technique."}, {"name": "Maximum: Shears of Three Fates", "prereq": "Prerequisite: Must have Road of Karma", "text": "As an action for 15 cursed energy, you form a scissor with your fingers and snip one of the threads of fate of a creature you can see within 5 ft of you. At the start of each of the target’s turns, they must make a Death save. This roll cannot have advantage or disadvantage and the target gains 1 level of exhaustion for every failed death save. If the target fails 3 death saves, they fall to 0 hit points and die. They are unable to be revived by cursed techniques. If the target succeeds 3 death saves or you are reduced to 0 hit points or die, the technique ends and the target becomes immune to this technique for 3 days."}], "e269": [{"name": "Greater Foresight", "prereq": "Prerequisite: Must have Predictable Strikes", "text": "Your foresight spills over to those you fight beside. As a reaction for 1 CE when a creature you can see within 30 ft makes an attack roll, ability check, or saving throw, you can call out what you have already seen and grant them advantage on the roll. You can use this a number of times equal to your CE modifier per long rest."}, {"name": "True Warstaff: Full Spread", "prereq": "Prerequisite: Must have Precognition", "text": "You have learned to unfold your Warstaff into a full manga spread. As an action for 4 CE, you can drive the Warstaff into the ground at a point within 30 ft, projecting a standing panel that fills a 15 ft cube for 1 minute. Creatures inside the panel count as marked by your technique, and you can read their futures without spending the usual cursed energy."}, {"name": "Maximum: Omniscient Reader’s Viewpoint", "prereq": "Prerequisite: Must have Storyboard Dominion", "text": "You have gained the ability to not only see, but also manipulate the contents of your manga panel. At the beginning of your turn, you can choose a creature that you can see that is marked by 6 seconds and roll a d20. Record the roll. As a reaction, you can replace one roll that creature makes with the result of that roll. At the beginning of your turn, you lose any unused rolls."}], "e270": [{"name": "Quick Pose", "prereq": "Prerequisite: Must have Majestic Pose", "text": "You have learned to strike a pose in a fraction of a second. As a reaction for 5 CE when you are targeted by an attack or forced to make a Dexterity saving throw, you can stop time for yourself and immediately move up to your speed and take the Dodge action; time then resumes. After time resumes, your movement is 0 ft and you cannot take actions until the end of your next turn."}, {"name": "Prime Time", "prereq": "Prerequisite: Must have Golden Week", "text": "You have learned to share your stopped time. While time is stopped by your technique, you can spend 2 CE to carry one willing creature you touch up to your movement speed, placing them in an unoccupied space you can see. They have no memory of the movement."}, {"name": "Maximum: Clock Hand", "prereq": "Prerequisite: Must have Samsara Rewind", "text": "As a bonus action, you can spend 5 CE to summon the Clock Hand to your hands for 10 minutes. The Clock Hand counts as a Simple Melee weapon that you are proficient with and has the finesse and reach property. It deals 1d10 piercing damage on a hit and has the Hour Hand and Minute Hand properties. Hour Hand: if used against a creature in stopped time, the Clock Hand deals an additional 3d8 necrotic damage on a hit. Minute Hand: if used against a creature not in stopped time, on a hit the creature must make a Cursed Energy save or be frozen in time and suffer the penalties of stopped time until the end of their next turn."}], "e271": [{"name": "Scorpion Tactics", "prereq": "Prerequisite: Must have Scorpion Hair", "text": "You have trained with your hair and unlocked the following maneuvers. Barbed Defense: as a reaction to being targeted by an attack, you can make a Scorpion Hair attack against the attacker if they are within range. Hair Wrapping: on a hit with your Scorpion Hair, you can choose to deal no damage and instead grapple the creature; you can use your Cursed Energy modifier to make grapple checks with your hair. Embedded Barb: once per turn when you hit with your Scorpion Hair, you can spend 1 CE to leave a barb embedded in the wound — at the start of the creature's next turn it takes 1d6 piercing damage as the barb works deeper, then dissolves."}, {"name": "Mega-Drill", "prereq": "Prerequisite: Must have Drill Hair", "text": "You can now use more cursed energy to imbue one Mega-drill. As an action for 4 cursed energy, you can shoot this Mega-drill in a 5 ft wide, 80 ft long line. Creatures in this line must make a Dexterity saving throw. On a failure, it deals 6d10 piercing damage. On a success, they take half the damage. This technique deals maximum damage to objects and structures and ignores half and three quarters cover. The damage of this technique increases to 8d10 at 6th level and becomes 10d10 at 11th level."}, {"name": "Air Bomber", "prereq": "Prerequisite: Must have Aircraft Hair", "text": "You have learned the following destructive ways to amplify your Aircraft Hair forms. Copter Frenzy: as an action for 5 CE, you force all creatures within 15 ft to make a Dexterity saving throw. On a failed save they take your Helicopter Hair damage. On a successful save, they take half as much. Jet Crash: when you crash your Jet Hair into a creature or surface, you can spend 2 CE to angle the impact — creatures in a 15 ft cone behind the point of impact must make a Dexterity saving throw, taking half the crash damage on a failed save as the shockwave carries through, or no damage on a success."}], "e272": [{"name": "Extreme Inverse", "prereq": "Prerequisites: Must have Extreme Opposites", "text": "You have fully mastered your Inverse technique, allowing you to withstand devastating attacks while weak strikes take a heavy toll. When you take damage, the effect depends on whether it exceeds or falls below your threshold. If the damage exceeds your threshold, you reduce it by an amount equal to your level. However, if the damage is below your threshold, you increase the damage taken by an amount equal to your level. This makes you near-invulnerable to powerful blows, but even the lightest strike can prove perilous."}, {"name": "Inverted Field", "prereq": "Prerequisite: Must have Quick Inversion", "text": "While training on your technique, you have found out you have a lot more to offer than just being an indestructible powerhouse. You have learned how to alter a whole area to be affected by your technique. As a bonus action for 6 cursed energy, you cause all objects and creatures within 30 ft of you to be affected by your Inverse technique for 1 minute. A creature or object is no longer affected by Inverse if they leave the range of the field. You can deactivate this as a bonus action."}, {"name": "Maximum: Antithesis", "prereq": "Prerequisite: Must have Synesthesia", "text": "You’ve learned to channel your inverted energy outward, inverting the flow of harm itself while your Inverse is active: when you take damage within your threshold, you can spend 4 CE as a reaction to reflect half of that damage back to the attacker (damage becomes force or necrotic, your choice) if they are within 30 ft. When you take damage below your threshold, you can instead spend 1 CE as a free action to transfer the pain. Choose a creature within 30 ft to take force or necrotic damage (your choice) equal to twice your CE modifier."}], "e273": [{"name": "Combat IQ", "prereq": "Prerequisite: Must have Demonic Intellect", "text": "Your overclocked mind runs firing solutions for the whole field. While your Demonic Intellect overclock is active, you can spend 1 CE as a bonus action to feed an ally you can see within 30 ft a predicted opening — they gain advantage on their next attack roll before the end of your next turn."}, {"name": "Read the Board", "prereq": "Prerequisite: Must have Future and Past", "text": "Your calculations now model other minds. As an action for 2 CE, you can choose one creature you can see and predict its immediate intent — the DM tells you what the creature plans to do on its next turn, including its intended target and general action. A creature with an Intelligence of 3 or lower reveals only its target."}, {"name": "Calculate Scenario", "prereq": "Prerequisite: Must have Overload", "text": "You focus your mind for 1 minute and spend 3 cursed energy. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The DM offers a truthful reply. The answer doesn’t take into account any possible circumstances that might change the outcome, such as additional glimpses of the future or the loss or gain of a companion."}], "e274": [{"name": "Beginner’s Luck", "prereq": "Prerequisite: Must have Little Miracles", "text": "Your luck is generous to those you favor. As a bonus action for 1 CE, you can press one of your stored Miracles into the hand of a willing creature you touch — they hold it as one of their own and can spend it using your CE modifier where the technique calls for one. You cannot exceed your normal maximum Miracles this way."}, {"name": "Blessing of Fortune", "prereq": "Prerequisite: Must have Miraculous Outcome", "text": "When you or a creature you can see fails a death saving throw, you can spend 1 Miracle and 1 CE as a reaction. The roll is now considered a natural 20. You cannot experience a breakthrough or gain a Miracle in this way."}, {"name": "Innate Luck", "prereq": "Prerequisite: Must have Fated for Fortune", "text": "Your fortune casts a shadow. When you score a critical success through Fated for Fortune, you can spend 1 CE to unbalance someone else's luck — one enemy you can see within 30 ft has disadvantage on its next d20 roll made within 1 minute, as your stolen fortune tips the scales against them."}], "e275": [{"name": "Exploding Fighting Spirit", "prereq": "Prerequisite: Must have Missile Impact", "text": "You have learned to channel your passion for battle and fighting spirit into your cursed technique. When you hit a creature with Missile Fist, the impact releases a shockwave — all other creatures within 5 ft of the target take thunder damage equal to your CE modifier. You can release this shockwave a number of times each turn equal to your proficiency bonus."}, {"name": "Armored Missile Fist", "prereq": "Prerequisite: Must have Devastating Barrage", "text": "As a bonus action for 2 CE, you cover your hands in Missile Fists, gaining the following benefits for 1 minute: ● You gain a +2 bonus to AC while holding no weapons or shields. ● You can use your CE modifier for attack and damage rolls using your unarmed strikes. ● Your unarmed strikes deal your Missile Fist damage. ● The range of your unarmed strikes becomes 10 ft."}, {"name": "Titan's Grasp", "prereq": "Prerequisite: Must have Unrelenting Fury", "text": "As a reaction for 3 CE, when you or a creature within 30 ft would take damage, you interpose a Missile Fist, reducing the damage by your Missile Fist damage. Roll the user's current Missile Fist damage dice (Xd8 + CE modifier at the user's level) and reduce the incoming damage by the result."}], "e276": [{"name": "Immortal Jellyfish", "prereq": "Prerequisite: Must have Lunar Jellyfish", "text": "True to its name, your jellyfish refuses to die. When Moon Dregs is destroyed, you can spend 5 CE as a reaction to revert it to its polyp stage instead — it shrinks to Tiny size with 1 hit point. At the start of each of your turns, the polyp regains hit points equal to your CE modifier until it reaches half of Moon Dregs' hit point maximum, at which point it returns to full size."}, {"name": "Adorable Poison Jar", "prereq": "Prerequisite: Must have Poisonous Cursed Energy", "text": "You have learned to milk Moon Dregs' venom into a jar. As an action for 2 CE, you can harvest a vial of jellyfish venom. You can apply it to a weapon as an action — the next hit forces a Constitution saving throw against your CE save DC, poisoning the target for 1 minute and dealing 2d6 poison damage on a failed save — or throw the vial as an improvised weapon (range 20/60 ft), shattering it in a 5 ft radius with the same effect."}, {"name": "Maximum: Crippling Neurotoxin", "prereq": "Prerequisite: Must have Cleansing of Purity", "text": "You have finally learned to amplify your poisonous cursed energy into a crippling neurotoxin that locks down nerves. When you use Poisonous Cursed Energy, you can spend 8 additional cursed energy to enhance the poison. If a creature fails their save against Noxious Poison they are stunned until the end of their next turn and poisoned for 8 hours. On a successful save, the target is poisoned for 1 minute. A creature poisoned in this way is treated as being under 3 temporary levels of exhaustion. If a creature fails the save by 5 or more, they are paralyzed until the end of their next turn and poisoned for 24 hours. This poison ignores cursed techniques that grant resistance, immunity, or other reductions to poison damage and the poisoned condition. This poison cannot be removed by cursed techniques or reverse cursed technique."}], "e277": [{"name": "Dull Pain", "prereq": "Prerequisite: Must have Pain Killer", "text": "You can dull pain before it ever lands. As a bonus action for 1 CE, you can touch a creature and numb its nerves for 1 hour — it gains advantage on saving throws against being frightened and on Constitution saving throws made to maintain concentration, as pain can no longer distract it."}, {"name": "Field Poultice", "prereq": "Prerequisite: Must have Practiced Hands", "text": "You have learned to pack your medicine to go. As an action for 2 CE, you can prepare a poultice of cursed energy that holds your technique. A creature can use an action to press the poultice onto itself or another creature within 5 ft, gaining the effects of Pain Killer for 1 hour. The poultice loses its potency after 24 hours."}, {"name": "Maximum: Panacea", "prereq": "Prerequisite: Must have Analgesic", "text": "As a reaction to a creature within 10 feet (including yourself) falling to 0 hit points you can spend 4 CE and cause them to instead remain at 10 hit points and gain the benefits of Pain Killer."}], "e278": [{"name": "Immobilized Limbs", "prereq": "Prerequisite: Must have Immobilizing Eyes", "text": "When you use Immobilizing Eyes, you can spend 1 additional CE as part of activating the technique concentrate your eyes on a specific part of the creature, also causing one of the following restrictions while you maintain your technique: ● Legs. The target's speed is halved. If the target tries to move more than their movement speed, they must make a Dexterity saving throw or fall prone. ● Arms. The target gains an additional -3 penalty to attack rolls and cannot take object interactions. ● Torso. You reduce the target's AC by 3."}, {"name": "Measured Gaze", "prereq": "Prerequisite: Must have Peripheral Vision", "text": "You have learned to measure your gaze. When you use Immobilizing Eyes, you can soften it: the target's speed is halved but its attack rolls and AC are unaffected, and your eyes take no strain damage from that target resisting. You can also end the technique on one creature you are maintaining it against without ending it on the others."}, {"name": "Eye Drops", "prereq": "Prerequisite: Must have Reactive Eye Movement", "text": "Through constant exposure, your eyes have learned to rest between strains. As a bonus action for 1 CE, you can close your eyes and let them recover — your eyes regain hit points equal to your CE modifier, but you are blinded until the start of your next turn."}], "e279": [{"name": "Regalia Versatility", "prereq": "Prerequisite: Must have Regalia", "text": "You have learned to alter your regalia and can change it to a different type of weapon as a bonus action, including ranged weapons and shields. While your Regalia is a ranged weapon, it creates its own ammunition. While it is a shield, you gain a bonus to AC while wielding equal to the bonus to attack and damage rolls your regalia has. Your GM may also choose to allow more unique weapons."}, {"name": "Celestial Raiment", "prereq": "Prerequisite: Must have Cursed Wave", "text": "While you have your Regalia manifested, you can spend 3 CE as a bonus action to summon a hagoromo scarf around your body that lasts until your Regalia disappears. As a reaction, you can add your proficiency bonus to your AC until the beginning of your next turn, or to a saving throw you make as the silken scarf protects you from harm."}, {"name": "Technique Release", "prereq": "Prerequisite: Must have Soul Bound Treasure", "text": "You have learned a method that allows you to use your maximum output. On a hit, you can spend 2 CE to deal critical damage and the target must make a Strength saving throw or be knocked prone. After the attack, your regalia breaks and must be resummoned. You can also use this on a Cursed Wave attack for 4 CE."}], "e280": [{"name": "Retrograde Station", "prereq": "Prerequisite: Must have Reversion", "text": "As an action while touching part of a nonliving object that was destroyed an hour ago, you can spend 2 cursed energy to entirely repair it. Any other fragments or separated parts of it disappear and any destroyed parts reform for the object. At 6th level this increases to 1 day, at 8th level this increases to 7 days, at 11th level this increases to 1 month, at 18th level this becomes 1 year and at 20th level this increases to any point in time."}, {"name": "Flash Regress", "prereq": "Prerequisite: Must have Regression", "text": "What if we just went backwards, like really fast? When you use Regression, you can bring one willing creature you can touch along with you for an additional 1 cursed energy. The creature traces your reversed path with you and ends in an unoccupied space adjacent to your arrival point. If your path is blocked, the normal Blocked Path rules apply to both of you."}, {"name": "Maximum: Sword of Retrograde", "prereq": "Prerequisite: Must have Invert Causality", "text": "When you use Invert Causality, your guaranteed attack strikes along the target's reversed timeline. The target must make a Constitution saving throw. On a failed save, it is stunned until the end of your next turn and the movement from its most recent turn is undone, returning it to the position it occupied at the start of that turn (damage and other effects it caused remain). On a successful save, it cannot take reactions until the end of its next turn. You cannot roll a black flash on this attack."}], "e281": [{"name": "Musical Climax", "prereq": "Prerequisite: Must have Resonating Music", "text": "You've learned that just playing isn't enough, you need to build up to the best part. As an action you can start playing your instrument to charge your technique, concentrating for up to a number of rounds equal to your CE modifier, after which you must release it. When you release a Sound Blast or Sound Wave charged this way, you can originate it from any unoccupied point within 60 feet of you that you can see, throwing your sound, and you can shape a Sound Wave into a 60-foot line instead of a cone."}, {"name": "Emotional Melodies", "prereq": "Prerequisite: Must have Resonating Music", "text": "As a bonus action for 5 cursed energy, you can introduce a vibe of your choice for 1 minute while concentrating. You can only have one Vibe active at a time. Deafened creatures automatically succeed. Happy Vibes: on a hit with your Sound Blast, the target makes a Charisma saving throw or be Charmed and only hear you and your music until the Vibe ends; they can repeat the save at the beginning of their turn. Sad Vibes: on a hit with your Sound Blast, the target makes a Charisma saving throw or fall prone and their speed becomes 0 until the Vibe ends; they can repeat the save at the beginning of their turn. Angry Vibes: on a hit with your Sound Blast, the target makes a Charisma saving throw or becomes berserk until the Vibe ends — a berserk creature uses their reaction to make a melee attack at the closest creature at the start of their turn and must use their action to attack; they can repeat the save at the beginning of their turn."}, {"name": "Rock Squad", "prereq": "Prerequisite: Must have Maximum: Epic Solo", "text": "Looks like the band is getting back together! While your Epic Solo is active, you can conduct your allies' strikes. When an allied creature ends their turn within 15 feet of you during your Epic Solo, their next attack before the start of your next turn carries your rhythm: on a hit, the target is pushed 10 feet away from the ally, as if struck by your Sound Blast."}], "e282": [{"name": "Piercing Burst", "prereq": "Prerequisite: Must have Piercing Schrift", "text": "You have perfected your accuracy and combined it with your piercing ability. When you use Piercing Schrift, you can also target additional targets up to your proficiency bonus that are either in front of or behind your target as long as they are within the path of the attack. You use the attack roll against the original target to determine if you would hit the additional targets."}, {"name": "Cursed Seal Expert", "prereq": "Prerequisite: Must have Cursed Mark", "text": "Through diligent practice and creativity, you have created new types of cursed seals. You gain the following options: Blinding Mark: As a bonus action for 3 CE, you mark a creature within 30 feet for 1 minute. On a hit, the creature must make a Constitution saving throw. On a failed save, they are blinded for 1 minute. A creature can repeat the save at the end of their turn, removing the blinded condition on a success. Crippling Mark: As a bonus action for 3 CE, you mark a creature within 30 feet for 1 minute. On a hit, the target must make a Constitution saving throw or have either their movement speed halved for 1 minute or disadvantage on attacks for 1 minute (your choice). A creature can repeat the save at the end of their turn, ending the effect on a success."}], "e283": [{"name": "Shadow User", "prereq": "Prerequisite: Must have Shadow Strike", "text": "You have furthered the uses of your shadow choosing one of the following features (This feat can be taken multiple times). Shadow Skulker: As an action for 2 CE you physically enter the shadows gaining full cover for X rounds or until you exit from a shadow within 10 feet. As an action while the technique is active, you can move into a shadow within 10 ft. You can hear and see through the shadow you entered. If the shadow is sufficiently illuminated, you exit the shadow. (X = CE mod). Shadow Envoy: As an action for 2 cursed energy, you can imbue your cursed energy into a creature's shadow within 5 ft. To attempt this technique without them noticing, you must make a Cursed Energy check against their passive perception. You can imbue conditions for when the technique is triggered. You can choose to leave either a melee attack with a range of 10 ft using Shadow Strike or a simple message. If you choose to leave a Shadow Strike, it targets a specific creature under a condition you set, uses your Cursed Energy modifier and is made at advantage if the target is unaware. If you choose a message, you can choose to leave five words. When you create the message, you can choose any number of creatures who can see the message in the shadow. Two shadow spells below 5th level. The CE cost equals the spell's level."}, {"name": "Lingering Bindings", "prereq": "Prerequisite: Must have Dark Binding", "text": "Your binding no longer needs to hold your weapon hostage. When you use Dark Binding, you can spend an additional 2 cursed energy: the target's shadow is pinned by your cursed energy alone, and you keep your weapon. The binding lasts for 1 minute while you concentrate (the target remains grappled and restrained), and the target can use its action to make a Strength check against your CE save DC to tear free. You can maintain only one such binding at a time."}], "e284": [{"name": "Constellation Network", "prereq": "Prerequisite: Must have Minor Star Shikigami", "text": "You have linked your shikigami into a shared-sense web. As an action for 2 cursed energy, you attune to your minor star shikigami for 1 hour: you know the location of every creature within 30 feet of any of your minor shikigami that the shikigami can perceive, and you can speak brief messages through them. This does not blind or deafen you as normal sense-sharing does."}, {"name": "Keystone Star", "prereq": "Prerequisite: Must have Major Star Shikigami", "text": "Your major star shikigami can serve as the keystone of your pseudo-domain. When you form your pseudo-domain, the major star shikigami can hold its center instead of orbiting: while it holds the center, you do not need to spend your bonus action to maintain the domain's radius, and you can command your minor shikigami normally. If the major star shikigami is killed or leaves the center, the domain ends."}, {"name": "Judicial Amputation", "prereq": "Prerequisites: Must have Army of the Dictator", "text": "If a creature fails their saving throw against your pseudo-domain by 5 or more, the damage is treated as having the Limb Removing Effect and targets one of their arms or legs."}], "e285": [{"name": "Fox in the Mist", "prereq": "Prerequisite: Must have Kitsune Creation", "text": "You can fold a fox shikigami into a mote of your cursed fog and carry it with you. As an action for 1 cursed energy, you dismiss one of your fox shikigami into a mote you carry: it does not count against your active shikigami limit while carried. As a bonus action, you can release it into an unoccupied space within 30 feet of you."}, {"name": "Fox Fire", "prereq": "Prerequisite: Must have Living Fog", "text": "You can create incredibly dense fog that can be triggered to erupt in a vapor explosion. For an additional 3 CE when you create an area of Cursed Fog, you make the fog incredibly thick. As an action, you can cause the fog to detonate in a vapor explosion. All creatures within the fog other than yourself must make a Constitution saving throw, taking twice your Cursed Energy modifier in d8s of cold damage or half as much damage on a success as a blue explosion rips through, igniting the fog."}], "e286": [{"name": "Tools of the Craft", "prereq": "Prerequisite: Must have Guided Control", "text": "You can imbue a set of tools with your cursed energy, such as artisan's tools or thieves' tools (1 CE, lasting until your next long rest). You can use your CE modifier in place of the normal ability modifier for ability checks made using the imbued tools. Additionally, you can channel a technique through them: when you use Wind Scythe, you can originate the line from an imbued tool you can see within 60 feet of you instead of one you hold or a Floating Tool."}, {"name": "Eyes in the Skies", "prereq": "Prerequisite: Must have Floating Tool Improvement", "text": "Your Floating Tool is a perfect scouting perch. While you are riding a Floating Tool at least 20 feet above the ground, you can use your action to survey the area below: you learn the location of every creature within 120 feet of you that isn't behind total cover from your vantage. Allies who can see or hear you ignore disadvantage on Perception checks to notice those creatures until the start of your next turn."}], "e287": [{"name": "Cannibalism", "prereq": "Prerequisite: Must have Hunger of the Accursed", "text": "Your hunger has overwhelmed your humanity and led you to resort to this inhumane act. You can now devour the corpses of human races and use them for your innate technique features. You can take a Class Feature or Innate Technique feature using the rules of Hunger of the Accursed from a dead humanoid, changing parts of your appearance to resemble them when used. You cannot take Domain Expansions using this feature. When you steal a cursed technique or innate technique feature from a dead humanoid, you can only take it if you are of the correct level and fulfill any prerequisites for using it. Additionally, you can only spend the base cost the technique requires. No matter what you copy, you can only use the technique in its base form. For example, a maximum output hollow purple would only come as a hollow purple. This changes if used with the Output option of Digestion at 6th level. Table consent: devouring a sapient humanoid corpse requires the table's consent, and for a PC corpse, that player's out-of-character consent — without it the corpse is inedible."}, {"name": "Necrophage", "prereq": "Prerequisite: Must have Regurgitation", "text": "You have learned to read a corpse before committing your hunger. As an action, you can take a small taste of a corpse within 5 feet of you: you learn one feature, action, or trait from its statblock that you could steal with Hunger of the Accursed (your GM chooses and reveals it). Tasting costs no cursed energy and does not consume the corpse, which can still be devoured normally afterward."}, {"name": "Gourmand", "prereq": "Prerequisite: Must have Body of the Devourer", "text": "You have learned to appreciate the good food you have eaten. When you use Regurgitation, you can call upon one additional ability you stole from the same creature as part of the same bonus action, paying its cursed energy cost separately as normal. You can savor a second helping in this way once per short rest."}], "e288": [{"name": "Crossed Marks", "prereq": "Prerequisite: Must have Mastered Teleport", "text": "Your marks are doors, and doors open both ways. As an action for 4 cursed energy, you can transpose two creatures or objects that both bear your marks, instantly trading their positions no matter the distance between them. An unwilling creature can make a Cursed Energy saving throw to resist being moved."}, {"name": "Warded Marks", "prereq": "Prerequisites: Must have Improved Marking", "text": "Your marks can watch as well as carry. When you place a mark, you can spend 1 additional cursed energy to ward it: you are mentally alerted when a creature you did not designate comes within 10 feet of the warded mark, and you learn the creature's size category. You can also set a warded mark to flare when triggered, shedding bright light in a 20-foot radius as a silent alarm."}], "e289": [{"name": "Many Hands", "prereq": "Prerequisite: Must have One Man Army", "text": "Your clones can deliver your techniques as well as your strikes. When you use a cursed technique with a range of touch, you can originate it from the space of one of your clones within 60 feet of you instead of your own space."}, {"name": "Shell Game", "prereq": "Prerequisite: Must have Twice the Fun", "text": "Your enemies can never be sure which body is you. As a bonus action, you can swap positions with one of your clones within 60 feet of you."}, {"name": "Shared Burden", "prereq": "Prerequisite: Must have Four is a Party", "text": "You have learned to trade more than bodies and hit points. As a bonus action, you can transfer one condition affecting you — blinded, charmed, deafened, frightened, poisoned, or restrained — to one of your clones within 30 feet of you; the clone suffers the condition instead."}, {"name": "Long Leash", "prereq": "Prerequisite: Must have One Man Army", "text": "Your duplication is no longer confined to arm's reach. You can create clones within 30 feet of yourself instead of 5 feet."}], "e290": [{"name": "Shadow User", "prereq": "Prerequisites: Must have Divine Dogs", "text": "You have furthered your use of shadows. Choose one of the following features (this feat can be taken multiple times). Shadow Skulker: as an action for 2 CE you physically enter the shadows, gaining full cover for a turn or until you exit from a shadow within 10 feet. At the start of your turn, you can spend 1 CE to remain in the shadow. You can hear and see through the shadow and can summon tamed shikigami within the shadow. If the shadow is sufficiently illuminated, you exit the shadow. Shadow Ridge: as a reaction for 1 CE against a melee attack, you force a creature within 10 feet to make a Dexterity saving throw; on a failure the target rolls the attack at disadvantage as their legs fall into their shadow briefly and they fall prone. You can instead spend 3 CE to give the target disadvantage on the save. Alternatively, learn two shadow spells below 5th level; the CE cost equals the spell's level."}, {"name": "Chimerafication", "prereq": "Prerequisites: Must have Totality", "text": "You have learned how to better fuse the powers of your shadows even at the cost of creating a monstrosity. When creating a Totality, you can sacrifice a tamed shikigami even if it is not destroyed. You can use a number of shikigami up to half your proficiency bonus (rounded up) + 1 that are eligible for Totality to fuse into an eligible non-Totality shikigami, forming a Chimera. Chimeras can have humanoid forms, but cannot be used for Well's Unknown Abyss. You can also give an additional alteration to your altered shikigami created with Well's Unknown Abyss, counting as part of the technique."}, {"name": "Maximum: Embodiment", "prereq": "Prerequisite: Must have Chimera Shadow Garden", "text": "As an action, you can spend half the cost (minimum 1) of one of your tamed shikigami (no Totality or Chimera). Rather than summoning, you instead gain their movement, actions, legendary actions, features and one ability score of your choice from the shikigami for 1 hour — for example, Divine Dog's movement, Max Elephant's Constitution, or Mahoraga's Adaptation. You can embody one shikigami at a time."}, {"name": "Shadow Kennel", "prereq": "Prerequisite: Must have Shadow Manipulation", "text": "Your shadow can hold living shadows as well as objects. As an action, you can store one of your tamed shikigami in your shadow; while stored it counts as dismissed. As a reaction when a creature you can see within 30 feet of you is attacked, you can release the stored shikigami into an unoccupied space within 30 feet of you."}], "e291": [{"name": "Blood Iron","prereq": "Prerequisite: level 11","text": "Once per long rest, you may Polarize the iron in a living creature's blood. One Attract, Repel, or Crush ignores the metal requirement entirely and works on any creature; the target has disadvantage on its saving throw against that effect."},{"name": "Debris Throne","prereq": "Prerequisite: Magnetic Flight","text": "While you are flying, orbiting scrap grants you +2 AC against ranged attacks. Once per turn when a ranged attack misses you, you may use your reaction to fling a shard \u2014 make a ranged technique attack against the attacker, dealing 2d8 + your CE modifier piercing damage on a hit."},{"name": "Polarity Reversal","prereq": "Prerequisite: Attract or Repel","text": "When a creature succeeds on its saving throw against your Attract or Repel, you may reverse the field as part of the same effect: it moves 10 feet in the opposite direction (no saving throw). You may do this once per turn."},{"name": "Polar Cage","prereq": "Prerequisite: Crush","text": "When Crush restrains a target, you may spend 1 additional CE to shape its metal into a cage: the restraint lasts 1 minute instead of until the end of its next turn (the target repeats the Strength save at the end of each of its turns, ending the effect on a success)."}], "e292": [{"name":"Reed's Calculus","prereq":"Prerequisite: none","text":"The genius is the second power. As a bonus action, analyze a creature you can see: you learn its damage resistances, vulnerabilities, and immunities (if any), and the first attack each of your allies makes against it before the start of your next turn has advantage. You may use this feature a number of times equal to your proficiency bonus per long rest."},{"name":"Living Bridge","prereq":"Prerequisite: Contortionist","text":"You may shape your body into a 20-ft bridge, raft, or ramp that supports up to 2,000 lb — allies cross gaps, pits, and water on your back. Alternatively, you may become a trampoline: allies who fall onto you take no falling damage and may bounce up to 20 ft as part of their movement without provoking opportunity attacks."},{"name":"Snapback","prereq":"Prerequisite: Wrap & Hold","text":"When a creature escapes your grapple or restraint, you may use your reaction: the limb snaps back — the escapee takes 2d8 bludgeoning damage, and you may immediately make a grapple attempt against it as part of the same reaction."},{"name":"Containment Wrap","prereq":"Prerequisite: Wrap & Hold","text":"As an action for 2 CE, envelop a Medium-or-smaller unattended object or a 10-ft cube of hazardous terrain (fire, caltrops, a swarm, a triggered trap): its effects are suppressed for 1 minute (Focus) while wrapped — flames smother, traps cannot trigger, swarms cannot leave."},{"name":"Elastic Rebound","prereq":"Prerequisite: Kinetic Soak","text":"When a ranged attack targets you, you may use your reaction and spend 2 CE to stretch a catching membrane: reduce the attack's damage by your proficiency bonus + your CE modifier as the rubber gives. If this reduces the damage to 0, you catch the projectile — fling it back as part of the same reaction by making a ranged technique attack against a creature within 60 ft; on a hit it takes the caught attack's original damage."}], "e293": [{"name": "Fastball Special", "prereq": "Prerequisite: Ripped-Up Arsenal", "text": "As an action, hurl one willing creature one size smaller than you up to 60 ft in a straight line. If it lands adjacent to a hostile creature, it may immediately make one melee attack against that creature with advantage, adding your Strength modifier to the damage roll. Otherwise it lands on its feet in an unoccupied space. The thrown creature must be willing, and you cannot throw anything you could not lift."}, {"name": "Dead Stick Landing", "prereq": "Prerequisite: none", "text": "The test pilot\u2019s last trick \u2014 and proof the stone was always the point: when you fall, you take no falling damage. Each creature within 10 ft of your landing point makes a Dexterity saving throw, taking 2d8 bludgeoning damage and falling prone on a failure, as your dense CE discharges into the ground. The ground where you land becomes difficult terrain until cleared."}, {"name": "Yancy Street Rules", "prereq": "Prerequisite: Ripped-Up Arsenal", "text": "The street fights back. When you hit a creature with an improvised weapon, it must succeed on a Strength saving throw or fall prone; once per turn, you may instead force it to drop one object it is holding as the blow jars it loose."}, {"name": "Seismic Sense", "prereq": "Prerequisite: none", "text": "Your sedimented body conducts tremors the way a medium conducts CE: while standing on stone or earth, you gain tremorsense out to 30 ft, and you cannot be surprised by creatures in contact with the same ground."}]};
